/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20171128-6","meetingId":"h29-cm11","date":"2017年11月28日","dateIso":"2017-11-28","committee":"区民委員会","time":"午前１０時００分～午前１０時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７５号議案、指定管理者の指定","agenda":"第７５号議案、指定管理者の指定","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"１つ目は、この指定事業について文化振興事業団のほうが効果的な提案があったと。それと、２つ目は、建物の維持についてよりも有効性を重視したということですけれども、有効性というのはどういうことなのか伺いたいと思います。荏原平塚コミュニティグループというのはそもそもどういう、会社なのでしょうか、それも含めて少し概要をご説明いただきたいと思います。","respondent":"鈴木文化観光課長","answer":"それから建物の維持管理よりも事業のほうを重要視したですが、新しい施設、設置して５年ですので、まだ最初の大規模修繕に当たる１０年目までもう一期間あるということ、それから比較的小規模な改修、修繕については毎年度区と協議をしながら実施していますので、今。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"それともう一点、この荏原平塚コミュニティグループ３社について伺ったのですけれども、具体的にどこの会社になるのか、会社名を教えていただきたいのと、なぜかというと、一方はこの公益財団法人で、もう一方は会社という意味では、公の施設を管理する上で区はそこにどういうふうな判断があるのか、ここも含めてご説明いただきたいと思います。","respondent":"鈴木文化観光課長","answer":"区の指定事業の具体的な提案の内容ですが、文化振興事業団のほうは一つ大きなものとしてはやはりこれまでも協力体制で実施をしてきました区民芸術祭関係の事業です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"提案","question":"私も中塚委員と同じ７番の指定管理者候補として選定した理由の、指定事業については文化振興事業団の方が効果的な提案がありとか、事業の有効性を重要視したというところが気になったのです。今具体的にお話を聞いたので質問しないのですけれども、これからの要望として次回からここを充実させてほしい。要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"２点ほど伺います。ただ、今、時節柄、人件費ですとかも含めて運営のところで全体的にコスト高になる傾向があります。５年間というスパンの中で、この辺、運営上そこを縮減することによって人的なサービス等に人材確保も含めて支障が出る恐れがあると思われるのですが、その辺の弾力的な区とのやりとり、どのようにお考えか教えてください。そういう場合にはどの程度の数だったのか教えてください。","respondent":"鈴木文化観光課長","answer":"２点目の、２事業者以外の問い合わせ等の状況ですが、当初公募をかけている段階で全部で５者の問い合わせがございました。その後、説明会を開催しまして書類等の提示をしたところ、最終的に参加の意思を表示されたのが２者です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"塚本副委員長","kind":"質問","question":"どうしてというか、これはどういう決め方によって選定委員が決まるのかということ。その辺の違いというのは意図的なのか、そういうことではなくてたまたまということなのか、選定委員会と審査会の２つの会の持ち方や選ばれる人の選ばれ方などについて、詳しく教えていただけますか。","respondent":"鈴木文化観光課長","answer":"選定委員の、もしくは審査委員も含めてその決め方ですが、区のプロポ実施に関します区としての全体の要綱があります。その中で、まずは主管の課長もしくは部長、それから関連部署の課長、あとはほかの所管の部以外の部の管理職というのが主な区全体の基準になっております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"わかりました。一つだけさらに確認なのですが、例えば審査会のほうでは防災課計画係長が出席されていて、防災課長は選定委員会のほうにはいらっしゃらないので、その辺の連携というか、もちろんされているとは思うのですが、その辺について最後に少しご説明をいただきたいと思います。","respondent":"鈴木文化観光課長","answer":"審査会のほうの防災課につきましては、課長に最初お願いをしておりました。ところが、防災課のほうの大きな会議が入ってしまってどうしても調整がつかないということで、代理で係長に出席をお願いしたものです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"塚本副委員長","kind":"確認","question":"それで、選定委員会のほうに防災課の方がいらっしゃらなくて、その辺の情報連携ですね。審査会のほうでいろいろ質疑とかしたことがちゃんと伝わっているともちろん思うのですけれども、そういうことがちゃんとできているかということの確認をさせていただければと。","respondent":"鈴木文化観光課長","answer":"ご指摘の部分ですが、審査会での審査結果につきましては、評点、点数だけではなく各委員から出された意見も全てまとめたものを選定委員会でまず最初にご説明をしました。","voiceIndex":16,"id":"exchange-007"},{"speaker":"藤原委員","kind":"確認","question":"この品川文化振興事業団というのは、きゅりあんも運営している指定管理者だと思って、まずそこの確認を。","respondent":"鈴木文化観光課長","answer":"ご質問のとおり、文化振興事業団につきましては、きゅりあんの指定管理者も昨年更新を経て引き続きお願いしています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"ということは、もう大過がなければ半永久的に文化振興事業団を、システム上審査はするとおっしゃるとは思うのですけれども、でもほぼずっとこのままではないかなという思いがある。だったら、きゅりあんのときみたいに戻して、戻すって今は違いますけれども、もうこういう審査はしなくて、もう決まっているのですから。だから、もうここでいいのではないでしょうか。どう思いますか。","respondent":"鈴木文化観光課長","answer":"ご質問の事業団がしっかり安定しているということでというお話の中で、施設が新しい部分がありましたが、先ほどご説明で申し上げましたように、今回に関しては設置後まだ５年ですので、施設のほうに大きな課題はないと。","voiceIndex":20,"id":"exchange-009"},{"speaker":"藤原委員","kind":"意見","question":"私も選定理由を読ませていただいて、よくここまで書いてくれたなと。僅差ながらと書いてありますよね。荏原平塚コミュニティグループのほうが僅差で高かったのですよね。「僅差ながら安定的な運営を期待ができるが」と書いてあるので、私はそうとったのです。僅差で安定できて、ちょっと上だったのかと。ただ、この文章だけ読むと、僅差で上だったのかなという思いもあるのですが、その辺について。","respondent":"鈴木文化観光課長","answer":"私の説明がちょっと足りなかったのかもしれないのですが、７(1)ですが、施設維持管理についてはコミュニティグループのほうが僅差ながら安定的な運営が期待できると。","voiceIndex":22,"id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"ちょっと気になったのですけれども、先ほどのご答弁の中で、選定委員の中の保育課長がなぜ委員の中にいるのかというところで、広場を使うことがあるからとおっしゃっていたと思うのですが、スクエア荏原の広場というのはどこのことを指しているのかということを。","respondent":"鈴木文化観光課長","answer":"そこもですが、私の言葉が足りませんで申し訳ありません。スクエア荏原の建物、正面玄関の前の広場のことを指します。裏に幼保一体施設の保育園を併設しておりまして、すみません、先ほど近接するという言い方をしてしまったのですが、同じ敷地内に保育園があるという意味です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者として文化振興事業団を指定することに賛成したいと思います。意見ですけれども、質疑のやりとりの中で審査の過程や指定管理者のいわば範囲の話も明らかになりましたけれども、これはやはりあらかじめ資料に提示をして、その上で審査ができるようにしていただきたいと、この点は要望を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"若干もう少し内容について伺いたいのですけれども、地域センターの職員がどういう用事で八潮高校に行ったのか、その仕事の流れに例えば無理があったり慌ててしまった要因がなかったのか、そこも含めてどういう用事があったのかその点を伺いたいと。書面になるのでしょうか。要するにこういう点があったのでこういうことでこうですよと、中身をご説明いただきたいと思います。","respondent":"伊崎地域活動課長","answer":"これを受けまして、地域センターの所長会というのを毎月２回やっておりますが、所長会で書面および口頭で、先ほど申し上げたように厳重な注意を行うということを所長に伝え、所長から各地域センターに伝えているです。","voiceIndex":42,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"３４万４,０００円というのは、八潮高校のスロープの手すりを直したお金ですよね。全然無傷ということはないと思うのですが、それはどういう形で、直したのであるならばどういう処理をするのかということ。それなのに、改めてこれもお伺いするのですけれども、こういう形で金額というのは出てくるのでしょうか。","respondent":"伊崎地域活動課長","answer":"ただ、車両のほうですが、ご指摘のとおり車両にも損傷がございまして、こちらにつきましては、区では自動車の任意保険にはもちろん入っておりますけれども、その中に車両保険が入っておりませんので、区の負担ということで、費用としましては１２万７,９７４円。","voiceIndex":44,"id":"exchange-014"},{"speaker":"藤原委員","kind":"確認","question":"車両、庁有車はわかりましたし、その前に３４万４,０００円という形で出すということもわかりましたが、これは物損事故の保険を使っているのですよねということと、もう一つちょっと細かく聞くならば、個人で入ると特にそうかと思うのですけれども、保険を使うと保険料が上がるではないですか、多分上がるのですよね。保険を使ったのですかという確認から。","respondent":"伊崎地域活動課長","answer":"この事故があったことで翌年度からの保険料にどの程度反映するかということは、区全体として庁有車に保険を掛けておりますので、これがどの程度の割合になるのか、申し訳ございません、地域活動課では把握ができかねるところです。","voiceIndex":46,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2796#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":13606,"voices":54}},{"id":"h29-20171128-7","meetingId":"h29-cm11","date":"2017年11月28日","dateIso":"2017-11-28","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年請願第１６号 品川区議会から東京都へ、受動喫煙防止対策に関する意見書提出を求める請願","agenda":"平成２９年請願第１６号 品川区議会から東京都へ、受動喫煙防止対策に関する意見書提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その理由として、受動喫煙で１万５,０００人が肺がんとか、虚血性心疾患とか、脳卒中とかで亡くなられて、それから能動喫煙によって約１３万人、これはさらに１５万人に増えているという報道もされていますけれども、亡くなられているということに私は立ち返るべきではないかと思うのですけれども、区として「たばこ白書」について、どう捉えているかということもお聞かせいただけたらと思います。","respondent":"川島健康課長","answer":"「たばこ白書」の医学的な考え方は非常に重く捉える必要があると思うのですけれども、それが規制イコールという形になると、またいろいろ難しい考え方があるというようなところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところからすると、たばこの害により、もちろん吸っている人もそうですけれども、それに加えて、吸っていない人が受動喫煙で１万５,０００人も年間亡くなられているということに対して、やはりしっかりと規制をして健康増進のためにもやっていくということが必要なのではないかと思うのですけれども。","respondent":"川島健康課長","answer":"平成２９年度につきましても２万店舗にアンケートを行いまして、６,８９８店が回答し、禁煙や分煙の対策を行っている一般の飲食店でステッカー等の店頭表示をしているのが４６.３％だったという回答になっているということで、こちらは先ほども申し上げましたが。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでたばこの害がさまざまな病気に関係してくる一番の原因の１つになっているということが言われているわけですから、この「たばこ白書」をもとに、今回、条例も出てきていますけれども、「たばこ白書」をもとにして啓発をするということを、ぜひ私は区としても、国保医療年金課と共同しながら取り組むということができるのではないかというふうにすごく思っているのです。","respondent":"川島健康課長","answer":"ちょっと誤解を招きかねないということは確かにあるのですが、多分、品川区だけ喫煙率がほかと比べて高い低いというのはないと思っておりまして、２割をちょっと切るぐらいという全国的な傾向と近いのかなというふうに思っておりますが、次回の健康プランの見直しのときには。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、やはり「たばこ白書」から始まり、そしてこういうメディアキャンペーンのところでも、世界で最低レベルというふうに指摘をされているという、そういう状況の中で、この意識を変えていくということをぜひ区として、私は広報等で、皆さんの意識をぜひ持っていただきたいということも含めて、先ほどのパンフレットなども使ったりとかしていただきたいし。","respondent":"川島健康課長","answer":"区民の健康状態に関するアンケートにつきましては、今、集計が終わったところですので、もう少し、説明できるような段階でご報告させていただければと考えています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"大倉委員","kind":"質問・要望","question":"国と都の動きの対応についても、先ほど、区の独自の策を出すのは混乱を招くおそれがあるというお話もあったと思うのですが、今、都が出している条例案、仮のところと、厚労省が考えているところの大きく違っている点とかがわかれば教えていただきたいと思います。","respondent":"川島健康課長","answer":"この請願にありますような協議の場があって意見を言うということではないのですが、そういう意見を述べる場はあったというようなところです。それから、今のところ、この条例と国の法案の考え方に大きなずれというか相違はないと認識をしているところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"若林委員","kind":"意見","question":"１番と３番ですが、今のご説明で、国と都の法律、条例では、そんなにずれはないということで、その法律と都の条例の中での混乱は、そういう意味ではないのかというふうに捉えるのですけれども、そこに「混乱」という言葉をつけたときに、品川区理事者として、どういうふうに認識されておられるのかというのは、ちょっと聞いておきたいと思います。","respondent":"川島健康課長","answer":"今言ったとおり、区の体制をどのようにとるのかというところも含めて、早めに、１回考え方を示されておりますが、もっと踏み込んだところを教えていただきたいというのが理事者側としての考えです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国保などは、本当にすごくかかわっていることなので、そういうふうな各自治体の意見を聞きながらということはあるのかと思うのですけれども、東京都がこういう受動喫煙防止の条例をつくるに当たっても、協議をする形で条例がつくられていくのかということを１つ教えていただきたい。","respondent":"川島健康課長","answer":"国の法案と都の条例案との違いの店舗面積３０m2と１５０m2のところですけれども、こちらは先ほども申しましたが、国の法案については、まだ正式なものは示されていなくて、報道が先行しているようなところがあるので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"国は法規制の規制を緩める、でも、東京都としては、当初案に準じる形で条例を提案していますというところについて、私は大もとが違うのではないかと思いましたので、その経過も含めて申し上げました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"吸う方、吸わない方、事業者の方、医療機関の方、いろいろな立場でどの視点で見るかで大分見方も変わってくるかと思いますが、区民の健康を守るというところの品川区としては、やはり健康と経済的効果を天秤にかけるのではなくて、さっきも紹介がありましたけれども、喫煙により４.３兆円も経済損失があるというのが。","respondent":"川島健康課長","answer":"今ご指摘のとおり、健康増進という観点は非常に重要ですし、今までもやっているのですけれども、しっかりたばこの健康面に対する影響ですとか、禁煙支援、たばこをやめる支援をしっかりやっていきたいと考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この請願で、１と２のところは当然だと思います。やはり協議、先ほども条例をつくる上で、一自治体と東京都との、もうちょっとこうしてほしいというような意見交換などは、当然あるべきものだと思いますし、都民、区民の意見も十分に踏まえてというところでは、今のＦＣＴＣなども２００８年にできていまして、そうした受動喫煙、たばこによる害を長年にわたって日本は議論してきたと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"済みません、１つだけ確認です。そうすると、当然、法律のほうが優先されるわけで、都の条例の３０m2というのは効力を失うということでいいのか。そこがよく分からなくなってしまったので教えてください。","respondent":"川島健康課長","answer":"３０m2以下という厳しいほうが規定の仕方によっては、生きる可能性もあるです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"本日、結論を出すということでお願いします。いままで質疑をずっとやっているものは、区の政策的なことについてということでいろいろありましたけれども、これは基本的に意見書を出すかどうかという判断だと思います。その上で、この内容、特に記書きの３番の部分を踏まえて、意見書を提出するという考え方でいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"我が会派としては、この記書きの１、２、３、これについてそれぞれ区の理事者の見解も伺いました。いずれにしても、３番の混乱が起こらないようにということについて、１番の区と十分協議をするということも含めて、意見を届けるのは、そのとおりだというふうに思います。したがって、結論を出すで、採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対して規制をするということで、せっかく、やっと２０１６年１０月に厚労省が受動喫煙防止の強化についてたたき台を出したのにもかかわらず、自民党のほうからの反発があって、１５０m2以下は喫煙可とするという方向で調整がされているという報道がされておりますけれども、そういう中身の国の政策を見据えてということでやっていたのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"結論を出すということでお願いします。態度は、採択ということでお願いしたいと思います。受動喫煙の国の政策を見据えてというところでは、品川区でもそうですが、経営者の視点からも、喫煙者、非喫煙者からの視点からも、１回１回状況がいろいろ変わっていくというのは非常に困る環境ができるのかなと考えていますので、この点についてしっかりと意見書を出して取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-015"}]},{"id":"topic-02","title":"平成２９年請願第１８号 視覚障害者の外出の安全・安心を確保するための対策を講じるよう求める請願","agenda":"平成２９年請願第１８号 視覚障害者の外出の安全・安心を確保するための対策を講じるよう求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私たち共産党は、品川区が羽田新ルート計画の撤回を国に求めるべきだとずっと一貫して主張をしてきておりますけれども、ここは厚生委員会なので、羽田の新ルート計画をやめろとか、どうのこうのというふうなところで審査をするところではありませんので、ここでは視覚障害者の方に対する騒音被害からの対策についてということでお伺いをさせていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ただ、そこで困っている視覚障害の方がいらしたときに、周りの人たちによるサポート、あるいは、今でも同行援護というような安全・安心に町なかを歩くための支援も行っておりますので、そうしたものでの対応、そのようなことが考えられるのではないかと考えております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その時間帯の利用に対しては、上限を設けない、また、その用途も問わないで同行援護の対応をとっていただきたいということでご要望いただいているのですけれども、いかがでしょうかということです。同行援護が難しいということであれば、移動支援でも、そういうことも含めて、ぜひ対応していただきたいというご要望をいただいているのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"実際には、やはり検討してほしいというようなご要望ということでこの請願はあるというふうに考えておりますので、まずは当事者の方たちのご意見も伺いながら、その中でどういうことが区としてできるのかというのは考えていければというふうに思っているところです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしもそれが難しいのであれば、代替措置としてタクシーによる移動を可能にする。タクシーチケットは今、視覚障害、たしか２級までの方しか対応されていないと思うのですけれども、そういうところもさらに拡大をして、視覚障害の方の移動を保障していただきたいということもご要望でいただいているのですけれども、その点についてお聞かせください。","respondent":"中山障害者福祉課長","answer":"具体的にどういう検討の場を設けるかということですが、障害者福祉課だけではなく、安全・安心ということであれば、まちづくりの部署であるとかといったところも関連してくると思いますので、そういった庁内の課長と、それから。","voiceIndex":44,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、羽田新ルート計画が実施に移された場合、それをさらに拡大するということで検討がされるのかということと、それから、相談支援のところで、なかなかここのところが突破できなくて必要な時間数をなかなかいただけないということも伺っているのですけれども、そういうことも含めて。","respondent":"中山障害者福祉課長","answer":"この請願にあるのは、今現在、安全・安心な外出の妨げになっていくのではないかという不安に対して、まず検討の場を設けてほしいということだと考えています。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、誘導ブロック、点字ブロックについても、なかなか視覚障害の方、私たちも毎回ここの場所、ここのところと具体的に要望もいただいています。そういう点でも、品川区全域を対象に、飛行ルートに当たる周辺の地域に誘導ブロックを優先的に設置していただきたいというご要望もいただいているのですけれども、そこの点についてもお聞かせください。","respondent":"中村都市計画課長","answer":"そのような中で、今ありました点字ブロックですけれども、こちらも必要に応じまして、まずは国の責任において必要な対応をするべきと考えておりますけれども、そのような中で区としてもできることは可能な限り検討した上で実施していきたいというふうに考えております。","voiceIndex":49,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、私たち、条件闘争になるのではないかということで、行財政改革特別委員会の中では議論になっていますけれども、区としてのいろいろな対策の中に視覚障害の方のための誘導ブロックも国のほうに求めているのか、また、いくのか、その点についてもお聞かせいただけたらと、これは羽田新ルートがもしも撤回ということになったとしても、誘導ブロックがあるにこしたことはないので。","respondent":"中村都市計画課長、中山障害者福祉課長","answer":"ただ、品川区の中で仮にルート案が実際に実現したというような場合には、それは他の空港とは状況がそれぞれ違うと思いますので、必要な対応については国に求めてまいりたいと考えております。研修等の依頼があったときには、区の職員が参りまして、こうしたパンフレットを使いながら、どういうことを手助けしてほしいか、それが障害者の理解につながるようにということで対応しているのが現状です。","voiceIndex":51,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"誘導ブロックについてですが、もう今でも区としては防音対策とかは求めているわけではないですか。そういう点からすると、この誘導ブロックも本当に広い範囲で必要になってくるということで、これ、品川区全域ということなので、はっきりとルートが確定したらというよりは、もうほぼそういうふうなルートは国のほうから示されているわけですから、今から私は対策を求めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、大分質疑があったのですが、私ども、請願の方からお話をお聞きしました。その中で、例えば先ほどバリアフリー計画、大井町が出ましたけれども、大井町で音がちょっと出ているから大井町なのですけれども、このバリアフリー計画の進捗状況と今後の見通し、まずその辺を教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"現在、歩道関係で点字ブロックの設置が進んで、これは区道で区が取り組みをして、例えば、平成２８年に阪急のデパート前の歩道にそれを設置をしたりですとか、あとは、それぞれ個々の建物の入り口から建物の中へ入る方のために、入り口から案内施設、受付ですとか。","voiceIndex":55,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"お話を伺ったときに、請願者の方が、点字ブロックを白杖で歩くときに音の問題がやはり相当影響が大きいというお話を伺った中で、例えば、私ども、歩いている中で、点字ブロックが結構剥がれていたり、曲がっていたりしているのをときどき見かけるのです。こういう管理も、区の分だったら区道、大井町近辺ですと都道が多いので、都の管理もしっかり要望しておいてもらいたいということを感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"ここら辺は、日ごろそういう冊子、またテレビで心のバリアフリーを訴える場面とかというものに触れる折りに、私たちも町なかで見かけたときには、本当にそういう優しい心で接していかなければいけないのだ、また接していこうというふうに心がけるわけですけれども、なかなか自分で頭で思うのと、また、町なかで見かけたときに、本当にその行動ができるかという、そういう意味では。","respondent":"中山障害者福祉課長","answer":"おたがいさま運動みたいなものもありますので、社会福祉協議会とも連携しながら、障害のある方の気持ちに立って声をかけたり、お互いが助け合えるような社会にしていく必要があると考えています。","voiceIndex":58,"id":"exchange-025"},{"speaker":"若林委員","kind":"質問・要望","question":"当然、いわゆる全盲といいますか、全く見えない方、ぼやけてしまう方とか、視野が狭い方、手帳を６３０人所持されていますけれども、級もまた違うでしょうし、そういう意味では、一人ひとりに合理的配慮が必要な部分なのだろうというふうに思います。それは共助、公助両面で、ぜひ品川のやさしいまちづくりを引き続き拡充していただきたいと、こういう思いですので、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほど、声かけというところでは、例えば、ここにも鉄道の駅で視覚障害者の安全対策として、構内放送でそばにいる人への声かけの運動を促進していますとありますが、商店街とかのラジオみたいなもので声かけを啓発するというのも一部できるのかななどと思いながら、そうすると、いろいろな支援のあり方とかという中で、いろいろな課が関係してきて、商店街だと商業・ものづくり課、また、まちづくりであれば。","respondent":"中山障害者福祉課長","answer":"まちで視覚障害の方が安心・安全に外出するためというところでは、さまざまな部署が想定されると思いますので、部を越えた連携ができるような検討の場を考えていきたいと考えています。","voiceIndex":61,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"その状況は、先ほど、所管が違うからということで質問があったのですけれども、もし答えられるようでしたら、どんな感じなのかわかれば伺いたいのと、先ほど、駅の構内放送で声かけが進んでいるという話もありました。そうした部分の区の障害を持たれた方への姿勢がすごく問われてきている、そしてまたこの請願にも出てきているのではないかと私は思うのですけれども、その辺はいかがかでしょうか。","respondent":"中山障害者福祉課長、中村都市計画課長","answer":"できるだけさまざまな障害のある方が、そうした会議の傍聴に来られるような体制につきましては検討してまいります。バリアフリー計画におきまして、まず民間の計画につきましては、これはなかなか、やはりまだ検討中というところで、詳しくは申し上げられませんけれども、ただ、大きなところでいきますと、１つは、大井町駅のホームの中で。","voiceIndex":64,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そこがなかなか進まないというところにもすごく不安があるのだと思うのです。日ごろの不安が、もし飛行機が飛んだら、もっと不安になるという、そこにやはりつながっているのではないかと思いますので、ぜひ当事者の意見を聞いて、毎年出されている要望書の内容は、本当に前進させていただきたいというふうに思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"大井町駅周辺地区バリアフリー計画の中におきまして、音響信号やエスコートゾーン、こういったものにつきましては、交通管理者、警察と、それから公安委員会、こちらのほうで検討を継続していくということになっております。","voiceIndex":67,"id":"exchange-029"}]},{"id":"topic-03","title":"平成２９年請願第１９号 安全・安心の医療・介護の実現と夜勤交替制労働の改善を求める請願","agenda":"平成２９年請願第１９号 安全・安心の医療・介護の実現と夜勤交替制労働の改善を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これはここに書かれているように、２０１３年の調査から４年たっていますけれども、４年たっても、４年前のときからずっとこういうふうに、５局長通知が出されたのが平成２３年ですから、今からすると６年も前から出されていたにもかかわらず、そしてこういう調査が繰り返し繰り返し行われているにもかかわらず、全く改善されていないという状況に、本当に私もすごい残念な思いがしているところなのです。","respondent":"川島健康課長、寺嶋高齢者福祉課長","answer":"新しい東京都の保健医療計画は、今、第６次の改訂作業が行われておりますが、そちらの中にも医療資源、保健医療施設数の推移ですとか、それから、従事者の推移というようなところで、数のほうは把握して。もう１点は、そういったことがなかなか難しいのが、やはり小規模の施設であろうと思いますので、小規模施設につきましては、これから区といたしましてもいろいろ情報交換をしながら、実態の把握とともに。","voiceIndex":82,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、誰かが急変したらどうしようと思いながら、１人で、相談する人もいなくて夜勤をしているという、そういう実態があるのではないかと思うのですけれども、そこら辺の区の実態と課題についてもお聞かせいただきたいと思いますし、また、障害者の方からも、そういう声はいただいているのです。区の状況と課題をどう考えられているかということについてもお聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"ただ、例えば宿直等を活用した夜間支援体制の加算等が設置されているものもございまして、そういったところをうまく組み合わせながら、運営法人のほうにはできる範囲で対応していただきたいと考えています。そうした中で、なかなか複数の夜勤体制というのは現実的ではないと思うのです。ただし、１人対応で何かあったときの応援体制をとるなどという形で、法人ごとに努力をしているようなところです。","voiceIndex":85,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護施設での１人夜勤に対しては、区としては、今後、解消というふうな方向で課題として考えられているのか、また、現状の中で現場から声を上げて制度そのものを変えていくということも区に求められている部分もあると思うのですけれども、そういった点では、区としては改善に向けて考えているということはあるのか、その点についてお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"それで、先ほども言ったような法人、施設との意見交換会、懇談会等の中で、状況をお聞きしながら、区で何かできる支援があればという声があれば、それは積極的に取り組んでいきたいと考えていますし、法人が行うことについて、何か意見が欲しいとか。","voiceIndex":88,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、それについて地域から声を上げていくというところで、私は、先ほど意見書というふうなところがありましたけれども、この分野で区議会として声を上げていくことを、ぜひお願いしたいと思いますし、そういう点での皆さんのご意見もお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと確認をさせてください。看護労働の実態調査の回答が３万３,０００ほどあったのですが、日本医労連にはどのぐらいの人数が加入していらっしゃるのかということがわかれば。それから、ちょっと聞き損なったかもしれないですけれども、看護師は増加しているとさっき答弁があったのですが、そこら辺、２点、もう１回確認します。","respondent":"川島健康課長","answer":"日本医労連につきましては、７全国組合・４７都道府県医労連で構成され、約１７万人が加入しているです。それから、ここ数年の看護師数については、国全体で３万人ぐらいずつ増加傾向にあるです。","voiceIndex":93,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"確認","question":"３万３,０００というのがどのぐらいかわからなかったので。一昨年、平成２７年のものを見たときに、やはり３万ぐらいでちょっとわからなかったので、その確認でした。それから、確認ですが、基本的には、区として管轄外ということで、それでよろしいですねということ。確認でいいです。","respondent":"川島健康課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"最初の説明のところで、５局長通知、６局長通知が毎回出されても変わらない状況があるということです。そして、都道府県に医療勤務環境改善支援センターが設置されている。医療従事者の勤務環境改善を促進するために、こういうセンターが設置されているというふうに先ほど説明があったのですけれども、ここはどういうふうに対策を打たれているのかは把握はされていないでしょうか。そこを伺いたいと思います。","respondent":"川島健康課長","answer":"先ほどご答弁申し上げました医療勤務環境改善支援センターが設置されているというところは、私ども、わかっておりますが、こちらがどのような業務をやって、どのように改善されたかというところまでは詳細は把握してございません。","voiceIndex":97,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひこういった看護師会の皆さんなどにも積極的にお話を伺っていただきたいと、私もこの実態調査を見てすごく思いました。ですので、現場が諦めずにこうした現状を訴えて改善を求めているわけですので、やはりこの声にこたえていきたいと私は思うのです。そして、先ほども言ったのですけれども、看護師たちとの交流もぜひ積極的に進めていただけたらと思うのですが、そうした可能性はあるでしょうか。","respondent":"川島健康課長","answer":"いろいろな交流会ですとか、そういった意見を聞く場を設けたほうがいい、ご意見としては、大事なことだとは思うのですけれども、例えば勤務状況がどうなのかとかという名目でお話を聞く場という話になると思うのですけれども。","voiceIndex":99,"id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"先ほども説明の中で、こうした確保の困難だったり、実態の厳しさは、国や都と同様に、区も重要な課題と認識しているということですので、ぜひできる範囲で積極的に実態改善を進めていっていただきたいと思いますし、この場では、やはり意見書の提出を採択していただくということを進めていきたと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたい。それから先ほど、経営の話もありましたが、例えば、請願の１番、労働時間の上限規制とか、インターバル確保、夜勤の回数の規制とか、労働時間短縮、１人夜勤解消を早期にしなければいけないとかといったときに、本当に経営などという部分では、どういった影響が出てくるのかと、本当に実際にやったときにできるのでしょうか。","respondent":"川島健康課長","answer":"こちらの請願項目の１番にありますところをしっかり守ってやっていくというところだと、当然１日の従事者数を増やすというところになりますので、経営にはいろいろな影響があるのかなというふうには推測しています。","voiceIndex":102,"id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の請願ですけれども、その中で多分出ていなかったと思うので、データで教えていただければと思うのですが、疲れが翌日に残ることが多い、５０.９％という数字が出ております。はこの離職率がどのぐらいあるのかということを教えていただきながら、また質問をできればと思います。","respondent":"川島健康課長","answer":"公益社団法人日本看護協会というところの病院の実態調査の結果によりますと、２０１５年度、常勤看護職員の離職率は１０.９％というところです。それから、新卒の看護師の方の離職率は大体７.８％というところで、この辺の数字で推移しているというふうに聞いてあります。","voiceIndex":104,"id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"意欲を持って職場に入られて、それで離職をされていくというのは、本当に残念でならないところかと思いますけれども、そういう意味では、体制とかそういうことについても、病院のほうでもしっかりと考えてもらわなければならないと思いますし、また、区として支援ができるところがあれば支援していただければと思いますが、いかがでしょうか。","respondent":"川島健康課長","answer":"さまざま病院を取り巻く課題の中の１つ、病院に限らず診療所も含めてということではあるとは思うのですけれども、こういったところで、先ほども申しましたが、例えば病院のほうでも人を採用するのに困っているというようなことがあれば、募集のお手伝いをしたりだとか。","voiceIndex":106,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だから、そこのところも含めて、改善させていくためにも、こういうところから声を上げていくということがすごく大事なのではないかというふうに思っています。そういうふうな中で、そこが今、限界に差しかかっているという、危機的な状況だという、そういうところでの悲鳴にも似たような叫びから来る今回の請願ですので、ぜひ意見書を上げていくというところで一緒にお願いしたいというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今日、結論を出すということでお願いします。ただ、先方も患者に対してですから、いい形のお答え、頑張っているということをよく聞くことはあるのですけれども、人数が増えているという状況、それから、区として管轄の違う部分ということも先ほどのご答弁の中にありました。それから、この中で請願の３番、４番については、上の項目とつながっている部分がないということも指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-043"},{"speaker":"若林委員","kind":"意見","question":"私たちからすると、いわゆる医療の現場がないということにもなりますので、そういう現場のない議会がこういう声をいただいたからといって、それをそのまま国に意見書として出すというのは、ちょっとこれは、意見書をもらった国としても、どこに責任があるのだろうという責任の所在の問題もあり、ちょっとそぐわないというのが１つ大きな理由としてありますので、不採択という結論でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところで、ぜひこの地方議会から国に意見書を上げて、こういうふうな制度をしっかりとさせていくということが求められていると思います。患者・利用者の負担軽減というふうな点も、国際的に見ても、日本はすごく重い負担になっていますので、この点についても、国民の立場から見れば当然だと思いますので、ぜひこの請願を採択して、そして意見書を出していきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-045"},{"speaker":"大倉委員","kind":"意見","question":"この課題については、非常に国もしっかりと取り組みを進めていかなければいけないと思っています。請願項目の３番、４番に関しては、先ほどもありましたが、上の趣旨を見ても、なかなかこれが理解しにくい部分があるというところで、今回、結論を出し、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-046"}]},{"id":"topic-04","title":"平成２９年請願第２０号 国保・後期高齢者医療・介護保険の保険料引き下げを求める請願","agenda":"平成２９年請願第２０号 国保・後期高齢者医療・介護保険の保険料引き下げを求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"来年度は、２５％も含めた１００％なくすという方向は、確認されているのか、どういうふうな方向になるのかということを１つお聞かせいただきたいです。それともう１つ、それ以外の決算補填分の法定外繰り入れもなくすという方向が出されていると思うのですけれども、そこら辺、区としては保険料を引き下げるために努力をしています。","respondent":"三ッ橋国保医療年金課長","answer":"それは、国や都にのっとって考えていくものだと考えておりますが、しかしながら、区民の皆様一人ひとりのことを考えながら、被保険者のことを考えながら努力はしてまいりたいと考えています。","voiceIndex":122,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、こんな国保のあり方でいいのかというのが根本から問われると思うのです。税金を投入して、誰もが払える保険料にしていこうということで始まった保険であるにもかかわらず、これだけ決算補填をなくしていく、国や区がこういう形でどんどん税金を投入をやめたというふうなところで値上げになっているわけですから、ここのところが私は根本的に問われていると思うのです。","respondent":"三ッ橋国保医療年金課長","answer":"一番最初に私も申し上げましたように、国保ですが、生活保護の方や社会保険に入っていない方が入る、そのほか全ての方が入る保険でございまして、国民皆保険制度の全ての方がお互いにという相互扶助の考え方で成り立っている、この制度を維持存続。","voiceIndex":124,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、初めから税金を入れないと成り立たないというふうなことでできた制度ですから、そこのところを今、どんどん税金の投入をやめてしまっているがために、これだけ厳しい状況がつくられているので、やはり税金をもとに戻す、国に対しては言っていただいているということですけれども、それを強力に言っていただきたいし、そういうことを国が出したということで。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金の部分ですけれども、国保新聞の中にもございましたように、維持検討をするようにという文言はありましたので、解消の方向ではありますけれども、少なくとも維持検討という部分に関しましては、国にのっとって対応してまいりたいと思います。","voiceIndex":126,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"後期高齢者医療保険料のところですけれども、後期高齢者も、２年ごとに値上げということで、特例軽減も、多分、もともと社会保険の被扶養者だった方が、なくされていくというふうな方向になっていくのかというふうに思っているのですけれども、この方にとっては本当に大きな負担増になってくるというところで、そこら辺の来年度の後期高齢者の動向もあわせてお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"先ほど申し上げましたとおり、今、平成３０、３１年度につきましては、少なくともまだ検討中の段階です。","voiceIndex":128,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、逆に増えているのではないかというふうに思うのですけれども、あと、平成２９年度末で、当初の見込みでは１５億３,０００万円余になっていますけれども、これが今の段階でどれぐらいになるかということについて、明日の報告事項で報告があると思うのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"この基金につきましては、これも先般の委員会でご答弁申し上げましたけれども、中期財政運営方式、３カ年で見込むというやり方をとっているので、初年度は基本的には余る、真ん中の年は、きちんと正比例していればですけれども、真ん中の年はとんとんで。","voiceIndex":130,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"第５期のときも、計画では１０億円取り崩すということでの説明だったのが、実際は９,０００万円だったのです。そういうふうなところでは、多分この基金は６５歳以上の人の保険料ですから、全体の介護保険の割合からすると２２％を占める部分です。そういうことで言えば、もっと保険料は下げられるのではないのですかというところを私はお聞きしたいのです。","respondent":"寺嶋高齢者福祉課長","answer":"一部、明日のご説明と重複する部分もありますけれども、今ご質問いただきましたので少し触れさせていただきたいと思います。","voiceIndex":132,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、大規模災害時のためにもとっておくことが必要だというふうなことも先日から言われていますけれども、今回も、どれぐらい基金は置いておかなければならないと考えているのかということを１つお聞かせいただきたいと思います。ほかの区は、こんなに基金を積み立てられていないので、そこのところはぜひ活用していただきたいと思います。その点もお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"他区の状況につきましては、それぞれの保険者の考え方等もあろうかと思いますので、一概に一言で結論づけることはなかなか難しいのですけれども、例えば、保険料に関し、第６期については、品川区は２３区では安いほうから３番目という設定をしておりまして、当然。","voiceIndex":134,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この保険料というのは、そのときに払った６５歳以上の人の保険料ですから、やはり６５歳以上の、そこで払った人のために使うということが本来あるべき保険料のあり方ではないかというふうに思っていますけれども、その点をお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"繰り返しになりますけれども、今はそれができるのでやっているけれども、今後の高齢者人口増等々を見たときに、そういったこともまた今後の議論になっていくところであろうというふうには考えております。","voiceIndex":136,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"殊に国保に関して本会議の答弁もありましたが、個別の対応もしているというところもわかりますし、最後、この文書の中で、「介護保険料は、ため込んだ基金」という言葉を使っており、今、鈴木ひろ子委員もおっしゃっていましたが、基金は大規模災害やその他の不測の事態にも給付を円滑に行うことができるような準備基金ということ、その辺も十分意識した上で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-055"},{"speaker":"若林委員","kind":"意見","question":"結論を出すで、不採択で結構だと思います。したがって、この請願者の方、また署名が１３６名プラスアルファという形でありましたけれども、あえて言えば、少ない区民の方の声を受けて、この厚生委員会の場で、これだけの保険料の問題を上げる、上げないと議論をするということ自体が、私は少しといいますか大変無理があると思うということで、そのことは意見として言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"請願権は憲法に保障されているわけですから、そういうところからしても、今の発言はちょっと問題ではないかと思います。そのことをまず申し上げておきます。そういう中で、国保料や後期高齢者医療保険料、介護保険料、ここの値上げがされたら、本当に区民は、ますます大変な状況になるわけですから、ぜひ区のほうからも声も上げていただきたいし、制度もいい方向に変えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問","question":"国保と後期高齢者医療、介護保険、先ほどの答弁の中でもありました、本当に努力をされて、１０年、２０年、３０年と見据えて、しっかりと維持していこうというところで、ご努力を非常にされているのだというところを感じておりますので、今回、結論を出すということで、判断は不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-058"}]},{"id":"topic-05","title":"(2)その他","agenda":"(2)その他","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"議会も今年２月に出している中で、総務委員会でも報告というお話もありましたので、厚生委員長の立場なのか、議長の立場なのかはありますが、やはり議会からもそれに対して要望書を出すべきだと思うのですが、その辺はいかがでしょうか。委員長に対して要望という形になるのか、その辺の判断をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-059"},{"speaker":"若林委員","kind":"質問","question":"ただ、今回の医療圏の私の理解は、こういうものを所管というのか、管轄というのかわからないですけれども、あくまでも東京都に対して品川区が物を申していくというのが、いわゆる１つのルール上の大きな筋であって、議会からあえて声を出したほうがいいのか、区とある意味で一体となって議会も非常に後押ししている、当然、区と一体となって同じ思いですというふうに出すほうがいいのか、別々に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-060"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"今のお話のように、区の立場は立場として、要望書を東京都知事宛てに出すということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":62747,"voices":158}},{"id":"h29-20171128-8","meetingId":"h29-cm11","date":"2017年11月28日","dateIso":"2017-11-28","committee":"建設委員会","time":"午前１０時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７３号議案、品川区立従前居住者用住宅条例の一部を改正する条例","agenda":"第７３号議案、品川区立従前居住者用住宅条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考ということでＡ３資料が配られていますけれども、この地域の容積率などの建築要件の中で、最大限建てられるボリュームに比べて、今回の計画建築率はどれぐらい使っているのでしょうか。最大何階まで可能なのか伺いたいと思います。補助２９号線などの特定整備路線や補助２０５号線や補助１６３号線など、第４次優先整備路線など、こうした事業の方というのは、具体的にどうなのか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"今区内で実施中の特定整備路線、補助２９号線をはじめとした３路線についても、東京都がしっかりと次の暮らしを補償の中で行うということで、住宅に困窮しないような手当てがなされるものということで。","voiceIndex":10,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"今のところからいうと、要件には合致するけれども考えていないということなのですけれども、区が補助２９号線の立ち退き者を入れようと思えば入れられるということなのか、入れるためには要件みたいな何か改正とかが必要なのかどうかというのがあれば伺いたいというのが１点です。","respondent":"高梨木密整備推進課長","answer":"最初の補助２９号線等の都市計画道路事業の協力者が入るために改正等が必要かというところなのですが、先ほどご説明いたしましたとおり３年を限度とした仮入居ということであれば、現行条例規則の中で対応が可能ですが、繰り返しになりますが。","voiceIndex":12,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"補助２９号線というか、道路のことは道路のほうでと、そちらのことではないという基本的な考え方があるのはわかりました。何か規則とかを変えないと、補助２９号線の方というのは、あえて入れようと思ったら、長くは入れられないということなのか、ちょっと確認させてください。実際に今入居されている方の収入状況はどうなっているのかとか、そこら辺もちょっとお伺いしたいと思います。","respondent":"高梨木密整備推進課長","answer":"現在ソレイユ戸越に入っていらっしゃる方が値上げになるか、値下げになるのかですが、現在入っていらっしゃる方は全て値下げの対応になるです。","voiceIndex":14,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。料金改定のところは、資料に平成１９年に改正されているとあるのですけれども、なぜ法律改正時に改正しなかったのかなというのをちょっと１点伺いたいと思います。","respondent":"高梨木密整備推進課長、長尾住宅課長","answer":"収入区分の改定について法律改正当時になぜ行わなかったということについてお答えいたします。区営住宅の増設の件につきましては、民間の住宅ストックの有効活用の観点から、区としましては区営住宅の増設は考えておらず、現状の戸数の維持という方針で考えております。","voiceIndex":16,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、今住宅に困窮している方がたくさんいらっしゃいますし、ストックがあるといっても、ストックが高ねの花のストックですから、とてもそういった困窮している方が入れるような住宅ではありませんので、それは私は区営住宅を増やさない理由にはならないと考えていますので、ぜひこういった建替えの機会を捉えて、区営住宅の増設などにも道を開いていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"多分一時的に借りて、また開発が終わったらそちらに戻っていかれる方もいらっしゃると思うし、今の答弁の中でも、ずっと住まわれていくという形もあると思うのですね。そうすると、３１戸というのが、果たしてこれから品川区全体の道路等々の再開発を含めてみると、どうなのですかね。現実にそれで賄っていけるものなのか、もう少し増やしていかないといけないものなのか、その辺の見通しはいかがでしょうか。","respondent":"高梨木密整備推進課長","answer":"要するに常に埋まっていては機能を発揮しないという性質もありますので、現在はまず３１戸で東中延、中延地区を中心とした運用をしていくつもりですが、その運用の状況を見て、また増設であるとかというところの検討は進めていきたい、このように考えております。","voiceIndex":20,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"もちろん住みなれたところで住みたいという希望が多いかと思うのですね。大体いずれはここもだろうな、ここもだろうなという形が出てくる中での見通しというものを、どういう形のタイミングで見通しを立てがら、こういうものが必要なのか、それとも民間の居住地を活用していくのか、いろいろやり方はあったと思うのですけれども、全体的な考え方を教えていただけますか。","respondent":"高梨木密整備推進課長","answer":"そういったところのバランスを見ながら、また今後、現在行っている地域と今後事業を拡大していくような地域のバランスを見て、あと先ほど申しました３１戸の運用状況を見ながら、今後の従前居住者用住宅の建設については考えていきたいと、このように考えております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"最後に。ということは、それぞれの方々から丁寧にご相談を受けながら対応していますよという認識でよろしいのでしょうか。","respondent":"高梨木密整備推進課長","answer":"そのとおりです。事業に協力するためにみずからの財産を売るなり、処分するなりということで協力していただく方ですので、基本的には区民の方のニーズを聞きながら丁寧に対応していきたいと、このように考えております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問","question":"１点だけ。新旧対照表の７ページのところなのですけれども、右側のところに、備考で『仮入居者が使用する場合にあっては、「５万７,０００円」とあるのは、「７万９,０００円」とする』と赤字で記載があるのですけれども、この部分はどういう形で以前設定されていたのでしょうか。新しいほうは、特に仮入居と本入居の方の違いはなくなったという理解でよろしいでしょうか。","respondent":"高梨木密整備推進課長","answer":"条例上は古いほう、旧のほうでも、仮入居でも場合によっては７万９,０００円とするということで、あえて書いてあるのですが、規則のほうでしっかりとそこら辺は仮入居、本入居は公平に使用料を徴収するような形で定めておりましたので、現行条例でも問題はなかったのですが。","voiceIndex":26,"id":"exchange-009"},{"speaker":"いながわ副委員長","kind":"質問","question":"ちょっと僕もあまり理解していないのでお伺いしたいのですけれども、まず、裏面に設定額、上限額と書いてあって、この上限額というのは、要領の中で住宅使用料の、要は上限値を算定して基準となる収入区分に適用するというのですが、この上限額というのは、基準額ということという考え方でいいのか、ちょっと何か言い回しがよくわからない。","respondent":"高梨木密整備推進課長","answer":"要領の中で定め、金額を基準の収入区分に適用するということで、その考え方で問題ございません。その中で、条例といたしましては高いほうの金額を上限額として定めるというものです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"だから、その趣旨を逸脱しないようにうまく回るような仕組みをつくっていかなければいけないと思うので、ただ協力したから、ではここに入ってくださいよといって入っていただくのはいいのですけれども、その次を役所としては、例えば宅建管理センターかどこかは別にして、協力とか相談体制をしっかりやって本来の趣旨にのっとった運営ができるようにしていただきたいなという思いがあるのですけれども。","respondent":"高梨木密整備推進課長","answer":"委員ご指摘のとおりずっと恒久的に住まわれたい方がどんどん増えてしまうと、空きがなくなってしまうではないかということになってしまいますので、そこはやはり運用を見ながら、そういうことが増えるということは。","voiceIndex":32,"id":"exchange-011"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"まさに課長がおっしゃっているように３１戸できました、入った人が次が見つからないからずっといらっしゃるというのは、それはそれでそれも目的とされているとおっしゃっていたのですけれども、ただ、すごく家賃が通常より安いというのも事実ですし、そこは何かうまく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"一つだけ確認です。例えば、２ＤＫに住む対象の方が、自分はもう１人なので終活も含めて１Ｋの部屋でもいいよとおっしゃる場合は、そういうケースは１Ｋでも入居が可能なのでしょうか。","respondent":"高梨木密整備推進課長","answer":"もともと２ＤＫに今住んでいらっしゃって、従前居住者用住宅では１Ｋにしたいからということであれば、当然そこはそういう要件はございませんので自由ですし、従前居住者用住宅で今２ＤＫに住んでいて。","voiceIndex":35,"id":"exchange-013"},{"speaker":"安藤委員","kind":"意見","question":"賛成なのですけれども、補助２９号線推進のための事業ではないことはわかりましたし、あと目抜き通りとか消防活動困難地域の解消の道路ですとか、あるいは防災広場の整備とか、空き地創出のための事業に協力する方々の生活再建のための住宅ということで、使用料の変更も低所得者により配慮した変更だということなので賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-014"}]},{"id":"topic-02","title":"第７６号議案、指定管理者の指定","agenda":"第７６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点お伺いしたいのですけれども、ヒアリング審査を実施ということでありますけれども、昨今さまざまなところで個人情報の流出なども問題になっていますが、これは区の住宅なので入居者の収入ですとか、家族構成とか仕事の状況とかが結構丸わかりなので、多くの個人情報があると思うのですけれども、それらがしっかり管理をされていて。","respondent":"長尾住宅課長","answer":"住民の生活状況の把握というか、滞納に絡んでのところですけれども、これまでも東急コミュニティーに関しましては、指定管理者のほうで入居者のほうとのコミュニケーションに関しては、日常的にとっておりますし、何か問題があった場合につきましては。","voiceIndex":52,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"こちらサイドの要望ももちろんある、管理をちゃんとしてくださいというのも当然あるのですが、ただ指定管理者制度をとっているという意味で言うと、いろいろ創意工夫があっていろいろできるのではないかなという自由度があるということも大きなメリットであるのかなと思うのですが、それに対しての評価はどうであったのかということ。そして、残念なのは１社しかなかったということですよね。","respondent":"長尾住宅課長","answer":"指定管理者制度による事業者側の自由度のお話の件ですけれども、先ほどご説明の中でも触れましたが、こちらの東急コミュニティーにつきましては、区内に営業所、拠点になっている支店があることとあわせて、関連会社の技術的なサービスセンターが区民住宅の至近にあります。","voiceIndex":54,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、家賃もあまり相場と変わらないという状況になってくるのではないかなと思うのですが、そうなってくると、結局今回は東急コミュニティーが来ていただいてありがたいと思うのですけれども、逆に頼れなくなるということも考えなければいけないこともあるのかなと、今答弁を聞いてちょっと不安になってしまったのですけれども、そういうことを考えると。","respondent":"長尾住宅課長","answer":"指定管理者の候補企業が、数のお話ですけれども、今東急コミュニティーが話しているところでは、引き続き管理をし続けるところについて意欲を失っているわけではございませんので大丈夫ですが、この次の指定管理者のプロポーザルのところに向けて、そういったことがないように。","voiceIndex":56,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"逆に言うと、区立なわけですから、値引き等を出すことは幾らでもできる、自由度もあると思うのですよね。民間よりはいろいろ難しいかもしれないけれども。なので、それも含めながら、あとここはこういうところがあって、住み続けたいなというふうに思っていただけるような仕組みをまず次に向けていろいろと管理者の方々と議論しながら詰めていただきたいなと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"これはさまざまな事業が行われていて、マンション管理、公営住宅管理運営、生活支援サービス、コミュニティ形成支援、ほかにもありますけれども、これはどこら辺までが管理というか、指定管理なのか、要綱に基づいて、ちょっと要綱を私は見ていないのですけれども、どこら辺までの事業の内容をこの東急コミュニティーにしてもらっているのですか。","respondent":"長尾住宅課長","answer":"先ほどお伝えした申請届出等の受理であったり、あと建物の保全、修繕、改良に関すること、あと入居者に適正に管理していただくように、適正な管理を促す案内をしたりすることであったり、あと使用料滞納の話などが出てきますと、先ほどもお話が出ましたが。","voiceIndex":59,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"それは区民住宅の管理という本来的な業務なのですけれども、今後指定管理を頼む上において、さまざまな部分で付加価値をつけてより魅力的な区民住宅をつくっていく必要があると思うのですけれども、東急コミュニティーの事業内容、会社概要に書いてありますけれども、ここは区と契約を結ぶときに事業内容をはっきり限定して、こういう今おっしゃっていた項目に限定してということは明文化されて。","respondent":"長尾住宅課長","answer":"ただ、プロポーザルの中では、こちらが書いた仕様書に書いていない内容、例えば入居者の方のコミュニティ形成を支援するようなこういった活動をご提案しますといったお話も入っておりましたので、全て区のほうから指定した業務しかできないという形にはなっておりません。","voiceIndex":61,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"そこのところは、多少なりとも幅を持って区と東急コミュニティーの間の取り交わしをされていると、ある程度の弾力性を持って取り交わしがされているということで理解させていただいていいのですか。","respondent":"長尾住宅課長","answer":"はい、そのような形で協定を結んで、指定管理者業務を行っていただいているところです。","voiceIndex":63,"id":"exchange-021"},{"speaker":"大沢委員","kind":"意見","question":"事業内容、会社概要には、大規模修繕も書いてある。省エネ・環境、シニア向けライフサポート、いろいろと事業内容が行われているわけですけれども、今後これらの必要とされるような事業内容、事業については、東急コミュニティーとその都度話し合いをしながら運営をこのファミーユ、進めていくという考え方でいいわけですね。","respondent":"長尾住宅課長","answer":"基本協定書というもので、業務の大枠は決めていますが、その年度ごとに具体的にやる業務が追加されるというか、もしあれば、年度協定というものでさらに設定をしておりまして。","voiceIndex":65,"id":"exchange-022"},{"speaker":"新妻委員","kind":"確認","question":"今回、また東急コミュニティーで出されておりますが、何回目ですかね。東急コミュニティーが最初からずっとやっているのか、変わっているのか。そこら辺を確認させてください。","respondent":"長尾住宅課長","answer":"一方、ファミーユ西五反田東館につきましては、平成２１年度からとなっております。こちらは、建物がそれぞれ竣工した時期がずれておりますので、１年度ずつずれておりますけれども、そのような実績を持っております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"新妻委員","kind":"提案","question":"５年間指定管理になりますと、５年間という長い間ですので、さまざま区もしっかりと事業内容をチェックされていると思いますが、新たな提案ですとか、毎回この管理をしていただく中でなれ合いにならないように、しっかり区とそういう間柄でいてほしいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"ほかにも民間住宅管理会社がある中で、今回東急コミュニティー１社ということで、当初からずっとここの場所で管理業務をやられてきたということも重要な選定理由だと思うのですけれども、結局東急コミュニティーに支払う費用というのはお幾らなのでしょうか。それは一般の住宅管理費用の相場と比べて安いのか高いのか、ちょっとご存知でしたらお知らせください。","respondent":"長尾住宅課長","answer":"管理コストに関しましては、西館と東館をあわせまして、およそ２億円です。市場の管理コストと比べてというところですけれども、建物の規模であったり特性によって変わってくる部分であると思いますので、ちょっとそういった比較はなかなか難しいと考えています。すみません。","voiceIndex":70,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうすると、東急コミュニティー以外でも、費用が安くてもいいからうちがやりたいという業者が出てくる可能性もあるということですよね。先ほどからお話が出ていますけれども、しっかり競争原理が働くような選定システムにしていただきたいのですけれども、そうした費用について、どのぐらい品川区としては意識されているのでしょうか。その点、お知らせください。","respondent":"長尾住宅課長","answer":"ですので、やはり指定管理業務に携わっていただく中で、管理コストをできるだけ下げて、よりよいサービスを提供するというところは、区としましても、今後も重きを置いて制度の運用を図っていきたいと考えております。","voiceIndex":72,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり東急コミュニティーがずっと１社という状態ですと、いろいろ疑問を持たれることもあろうかと思いますので、その点、なぜ東急コミュニティーを選定したのかという理由をやはりしっかり区民の方等々にお知らせいただくような努力をしていただきたいと思います。これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"反対なのですけれども、態度表明します。港区では、２００６年に起こった区営の賃貸住宅のシンドラーのエレベーターの問題がありました。モニタリングは出ていると言いますが、モニタリングもかなり簡便なものなので、ちょっとそういった意味でも毎回言っているのですけれども、やはり議決にあたってはしっかりとこうしたところの透明性を確保していただいた上で出していただきたいということを意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-028"}]},{"id":"topic-03","title":"第７７号議案、大井一丁目地内特別区道路線の認定","agenda":"第７７号議案、大井一丁目地内特別区道路線の認定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回は、再開発事業で私道が区道になるということですけれども、区道部分というのはもともと私道だったということですけれども、それが今回区道になるまでの権利関係の変換の推移を伺いたいのですけれども、私道だったのが、私道というのは個人の土地ですよね。それが再開発組合の財産になって、今回、区に譲渡という流れでよろしいのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"これは再開発の権利変換に係るところなので私のほうからご説明いたしますと、私道ですが、これも土地の権利者ですね、再開発の区域の中に入っておりますので、土地所有の権利者というところで権利変換をするか、あるいは地区外への移転。","voiceIndex":87,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとよくわからなかったのですけれども、今言った話の流れで、土地の所有権が移ってきたということでいいのかということを伺いたいのですけれども、どうでしょうか。","respondent":"稲田都市開発課長","answer":"はい、権利変換をやりながら所有権は移ってきたです。","voiceIndex":89,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"今回区に譲渡ということなのですね。そういう意味では、最終的に工事中でも１軒残っていたお宅というのは、裁判になったという話もあるのですけれども、どんな裁判になったのか、どうなっているのか伺いたいと思います。それと、この再開発事業でのもともとの地権者数と、そのうち組合認可申請に同意された方は何人、最終的に何人で組合を設立されたのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"それと、組合設立のときの認可の同意状況です。７１人の権利者がおりまして、５４.７人同意したです。権利者の７７％、３分の２以上という規定がありますので、そういう状況で組合設立されてきたです。現在、組合員数で申しますと、５３名となっております。","voiceIndex":91,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"そうしたことで追い出して、なおかつ７１人のうち５３人と、７７％、１７名ぐらいの方が同意していなかったと。かなり低いですよね。２点伺いたいのですけれども、右側の三角のところ、南第１地区という名前ですけれども、右側の下の三角、今回の道路を挟んでの、こちらの三角の部分、これが第２地区という位置づけなのでしょうか。それはちょっと、どんな品川区として対価を手にしたのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"この木造密集地域の解消を主なところに置きましてやっているですが、まだある部分につきましては、まだまだ地域の皆さんの熟度が達していないというところで、今後まちづくりの進捗が図られるところというふうに認識しております。","voiceIndex":93,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"結局広場ですとか、今回の区道みたいなところができるというのが防災性の向上になるということなのですか。伺いたい。一般論で言うと、人口集中が今大変な問題になっていまして、インフラの問題とかが出ているのですけれども、なぜ都心居住を品川区は、この再開発の理由に挙げて、先ほども説明がありましたので、その考え方を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう大きな上位計画等に基づきながらまちづくりを進めていくというものです。","voiceIndex":95,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"今回５１億円を投入して、１,０００m2の広場をつくると、これはどう見ても高い買物ですよね。だから、５１億円も品川区は税金を出して、高い広場の買物をした上で、しかも９１億円住友不動産にもうけさせるというのは、私は密集解消という事業にとっても本当に何ていうのでしょうね、住友不動産にもうけさせてあげるための高層開発としか思えないのですけれども、いかがでしょうか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"適正な補助金を算出して出しています。","voiceIndex":98,"id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"先ほど見させていただきましたが、確認したかったのですけれども、この道路というのは、一方通行ですかということと、区道の要件というのは、どういう要件があるのでしょうか。先ほど私道を権利変換して区道にということだったのですけれども、区道にするためにはどんな手続が必要で、どういう要件があれば区道として指定されるのか、まず教えてください。","respondent":"稲田都市開発課長、今井土木管理課長","answer":"こちらの通行形態ですが、警視庁等と協議をしながら一方通行というふうに定めております。区道のほうの要件ですけれども、このようにやはり新しい区道の認定となりますと、地内ではありますけれども、一定の地番から一定の地番までを接続したものというふうな道路でございまして、両方とも公道に接続しておりますので。","voiceIndex":100,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"ということは、区道になる要件が、品川区独自の要件の中にあって、それに合致するので今回条例という形で出てきたということの意味合いでよろしいのでしょうか。これは別に区道なので東京都とか国と全く関係なくて、区だけの独自の判断によって指定がされるという範疇でよろしいのか、まずそれを教えてください。","respondent":"今井土木管理課長","answer":"こちらにつきましては、あくまでも区内の区域に存する道路ですので、国道、都道というふうなことでございませんので、区長が路線を認定するものです。","voiceIndex":103,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"わかりました。ただ、ちょっと心配だったのは、ちょっと湾曲しているのですよね。ただ、道路ができることによって車が走り出す、安全上危険を伴うというのは当然出てくるわけであって、危険回避をどうしていくのかということですね。それが非常に気になりました。かなり安全対策をとらないといけないのではないかなというふうに思いますが、その辺はいかがでしょうか。","respondent":"稲田都市開発課長","answer":"こちらの道路においては、そういうところで交通量、抜け道的な対策等は考えているところです。ガードパイプ、区道の歩道側、道は２ｍの歩道をつけまして、ポールを立てていったりとか、そういう安全対策もやっているということで、交通安全にも十分考えてやっていくです。","voiceIndex":105,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"お願いですけれども、今まで車が通っていないところが通るという意味では、近隣の方々の注意喚起ですね、安全配慮をしますということも含めてしっかりと告知をしていただいて、情報をお伝えして、気をつけていただきたいということは十分に対策をとっていただきたいなと考えていますので、その辺をお聞きして終わりたいと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"沿道の方々におきましても、こういう道路をつくるということは組合のほうからも丁寧に説明しています。あわせて交通安全についても引き続き注意喚起を呼びかけていきたいというふうに考えております。","voiceIndex":107,"id":"exchange-038"},{"speaker":"いながわ副委員長","kind":"確認","question":"４.００ｍから５.１２ｍの車道があって、歩道２.００ｍをつくります。これは区道、要は区画道路２号になります。よくあるのが裏側から出したりするケースというのもあると思うので。最後の１点が、Ａ地区が平成１４年に竣工した敷地境界があると思うのですけれども、ここまで今日確認できなかったのですが、敷地境界は塀か何かになっているのか、どういう状況なのかということを確認させてください。","respondent":"稲田都市開発課長","answer":"現在のところ、側溝を敷くようにこの断面ではなっておりますので、今後道路管理者の道路課のほうと協議をしながら構造については決めていくです。駐車場の出入口は１６３号線側に設けるようになっております。","voiceIndex":109,"id":"exchange-039"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"区道上の車道と歩道はガードパイプなのだけれども、民地と車道の間はいろいろな仕切り方があるというのですけれども、危険だからガードパイプにしていると思うので、その辺は本当に道路課と連携をしてしっかりやっていただきたいなという思いと、課長はよく構造美とか、また開発の美学というのがあると思うのですけれども、一体的な面としての再開発なのだから、ぜひ境界特有の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"反対です。わずかな区道認定や広場で容積率を現行４００％から６５０％に引き上げる再開発の都市計画決定で、住友不動産に巨大な便宜を図ると。一方で、犠牲になったのは、追い出されたり、風害などで被害を受ける地域住民だと思います。こうした住民そっちのけの大企業優遇の再開発事業に熱中するのはやめるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-041"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"賛成です。これから先も一体的な開発というのは進むと思いますので、地域住民からちゃんと意見を聞いてしっかりと進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-042"},{"speaker":"横山委員","kind":"確認","question":"すみません、１点だけ確認なのですけれども、平成２６年１０月の大崎ニューシティ臨時総会において目黒川デッキ接続の否決とあるのですけれども、こちらの否決内容については、区のほうでは把握されているのでしょうか。","respondent":"稲田都市開発課長","answer":"ただ、なぜ否決されたかという明確な理由は示されておりませんで、結果的に否決されたということでつなげられませんという状況です。","voiceIndex":128,"id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"確認します。これは当初からこのデッキの接続というのはあるという方向で話が進んでいたのか、ある程度の双方のオーケーですというようなことがあって、こうなってしまったのか、そこら辺をまず確認させていただきたいと思います。","respondent":"稲田都市開発課長","answer":"ただ、しかし、それにおきまして、その後このように総会で諮ったりしたところにおきましては否決されたというところで、計画上非常に必要なデッキであるというところで、話は進めてきたのですけれども、そういう状況であります。","voiceIndex":130,"id":"exchange-044"},{"speaker":"新妻委員","kind":"質問","question":"残念ですね。私も歩道を通って、今下におりる階段がつきましたけれども、そのままになっているなという期間がちょっとありましたので、早くつながればという思いもありましたけれども、今後また区としてもこれは推進をしていただけるという、区としてのお考えを１点伺いたいのと、あと階段をおりてつながらなかったけれども、道路の下に階段がつながりましたが、これはどこがやったのですか。","respondent":"稲田都市開発課長","answer":"このデッキ接続は、都市計画でうたってこのまちをつくっていくというところにおいては欠かせないものですので、引き続き再開発組合のほうへ指導するとともに、区としましても、再開発組合のほうと協議を進めながらよりよい解決策を考えていきたいというふうに考えております。","voiceIndex":132,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"どうしてつなげてはいけないのというところが非常に原因がよくわからないということで、多分組合のほうもお手上げ状態、何とかしてほしいということがあっての今回の陳情だと思うのですけれども、正直どうなのですか、これは何とかしてあげたいという思いはあるのですが、行政側として何かできる可能性はあるのですか。何もできないのですか。何か手だてはあるのですか、ないのですか、いかがですか。","respondent":"稲田都市開発課長","answer":"非常にここが難しいというか、難解というか、今後におきましては非常に難しいというところです。今後再開発組合とも協議をしていくというふうな話を上げておりますけれども、その協議、今まで成立してこなかったではないかというのはおっしゃるとおりです。","voiceIndex":134,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"十分に行政側の気持ちをくみ取っているつもりでいるのですね。それで、行政側としては、強制力はないのですかね。一番最大の、これはできるかどうかわかりません。裁判になってしまうかもしれないので、慎重にしなければいけないと思うのですけれども、ただ、この総会のメンバー、そしてなぜここがだめなのかという理由を問いただすというぐらいの強制力を持った形ではできないのでしょうか。","respondent":"稲田都市開発課長","answer":"相手方との交渉を引き続きやるです。","voiceIndex":136,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"これは建設委員会としてということで議論が出てくれば、したいところであるのですが、例えば、できるかどうかわかりませんが、この大崎ニューシティの代表者に来ていただいて意見聴取するというのはいかがなのですかね。こういう陳情が出てきました、それで、さらにこれを審議するにあたってご意見をいただきたいというようなことは建設委員会としてはできないものなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-048"},{"speaker":"大沢委員","kind":"提案","question":"ここは再開発組合で費用を負担した。切れ目なく説得していくためには最低限のものが必要だ。ここのところは費用の面は確保しなければいけない。費用というのは、これまでの経緯の中で都市再生特別地区提案による目黒川デッキ接続計画、これは再開発の計画の中に含まれているということで、この費用については再開発組合が持っている、こういうことで１回確認をさせていただいていいでしょうか。","respondent":"稲田都市開発課長","answer":"はい、このデッキの建設費用ですが、再開発組合の事業の中に含まれているものです。","voiceIndex":140,"id":"exchange-049"},{"speaker":"大沢委員","kind":"質問","question":"となると、ここを置いて、大体が完成を見ているわけですけれども、再開発組合の仮に事業が終われば、当然組合というのは解散をするのでしょうけれども、組合の存続について説明をお願いします。","respondent":"稲田都市開発課長","answer":"この再開発事業で上げたこの都市計画で、こういう施設をつくっていきますよという計画を上げている以上、まだそれがつながっていないと、完成していないというところにおきましては、再開発組合は基本的に解散等はできないという状況です。","voiceIndex":142,"id":"exchange-050"},{"speaker":"大沢委員","kind":"意見","question":"そうなると、まだこれは事業半ばということで理解をしましたけれども、ではそれを担保しつつ、今後これはしっかりと再開発デッキ建設に向けた協議を進めることを引き続き指導してまいりますということで、先立つものは、これに対する費用というのはしっかりと確保して、そのことができるわけですね。これについてご意見をどうぞ。","respondent":"稲田都市開発課長","answer":"この費用につきましても、しっかりと確保しています。","voiceIndex":144,"id":"exchange-051"},{"speaker":"筒井委員","kind":"確認","question":"目黒川デッキ、現段階で暫定的におろしている状態ですけれども、私も現地を見たことがあるのですけれども、景観上も著しくよくないもので、本当に違和感を感じるような状況なのですけれども、今さらなのですけれども、この再開発準備組合と大崎ニューシティというのは、当初の段階からうまく巻き込めなかったのかということの確認と、２点目として、大崎ニューシティは、これも再開発事業なのでしょうか。","respondent":"稲田都市開発課長","answer":"ただ、途中ちょっと見通しが立ってきた部分もございまして、事業を進めてきたです。それから、大崎ニューシティ側も再開発でこれはやっております。大崎駅東口第１地区という地区名でやっておりまして、区の補助金も入っているところです。","voiceIndex":146,"id":"exchange-052"},{"speaker":"筒井委員","kind":"質問・要望","question":"こういう状況ですから、区長みずから直接交渉していただいたほうがよいかなと思うのですけれども、その点、区としての今後の交渉の対応はどうするのかということをお聞きします。","respondent":"稲田都市開発課長","answer":"この地区、この事業におきまして、さまざまな、いろいろなことが背景にあるということはもちろん承知しながら、これまでもいろいろと対応等も考えてきたところです。","voiceIndex":148,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも大崎ニューシティのほうには、大崎全体の活性化という大局的な見地を持っていただきたいということを考えていますので、その旨もぜひともお伝えいただいて、今後とも積極的な行政指導をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"そもそも資料にもありますけれども、目黒川デッキ接続計画を含む都市計画決定がありながら、デッキだけつながらないというのは、ちょっと純粋になぜなのかなというのをお伺いしたい。そこまでやられると、さすがに日常の生活に、これからを考えると不安を感じるというお話でした。区は、このように地域の今まで住んでいた方が大変になっているという状況をどういうふうにつかんでいるのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういうところにおきましては、ＪＲのほうに申し入れをしたりしておりまして、ホームドアの設置等々にも至っているというところがあります。小関橋周辺等の混雑等も出てきたというところでございまして、こちらは信号機等も設置しながら安全対策等を考えているところです。","voiceIndex":151,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"今後は組合に対して進めるということですが、品川区自身が大崎ニューシティとの協議というのはしないのかなというのがちょっと素朴な疑問で、今後の進め方で、そういった対応はしないのかどうか伺います。","respondent":"稲田都市開発課長","answer":"品川区自身が交渉相手と交渉しないのかですが、これはあくまでも再開発組合が特別地区提案をして、このまちづくりをやっていくということでやってきているものです。基本的には再開発組合が交渉して建設をするというところで実施するものです。","voiceIndex":153,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"その計画は重要だということで計画を進めてきた。重要な計画だと区が認識したとしても、それが担保されないという段階で進めていくというのは、進め方としてもやはりおかしいのではないかと聞いているので伺ったのですけれども、そういうものなのでしょうか。もう一度お答えください。品川区は組合の一員だけれども、そこの交渉にはかかわりませんということなのか、どうなのでしょうか。お願いします。","respondent":"稲田都市開発課長","answer":"結果的に現在つながっていないですが、基本的にこのように都市計画を考えながらまちづくりを進めるという意味におきましては、このような形で進めるということは特に問題ないものです。","voiceIndex":155,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"これから、率直に言って大崎はどうなってしまうのかなと思うのですね。そこで伺いたいのは、これからどんどんつくっていくとなると、これ以上にそういうインフラ問題が出てくると思うのですが、どう解決するつもりなのですか。これはちょっとまずいのではないかなと思うのですけれども、ちょっと改めたほうがいいのではないかということと、どう解決するつもりなのですかということをお伺いしたい。","respondent":"稲田都市開発課長","answer":"詳細なところにおきましては、ＪＲ東日本とも今後におきましても、調整を行いながらやっていくというところでございまして、きっちりとした都市基盤をつくりながら東京都の副都心にふさわしいまちづくりを今後も進めるものです。","voiceIndex":157,"id":"exchange-058"},{"speaker":"安藤委員","kind":"意見","question":"私はそのことは指摘したいと思いますし、やはりこうしたまちづくりというのは、立ち止まって見直すべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":159,"id":"exchange-059"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"国とかも入っているのですかね。その辺も教えていただきたいことと、あと仮設の階段なのですけれども、本来はつくるべき階段、これも確認なのですけれども、本来つくる予定ではなかった階段を、つながらないから下に逃がすためにつくった階段となると、本来使うべきところではないところにお金が支出されているということについてどうお考えなのか、そのままこの階段は残っていくのかどうなのか。","respondent":"稲田都市開発課長","answer":"それから仮設階段、これは河川の上にデッキがかかっているのですけれども、東京都のほうから供用を開始しないといつまでも仮設のデッキのままではいけませんという指導を受けました。そういうところにおきましては、反対側に渡して人が上れるように仮設階段を設置してきたです。","voiceIndex":160,"id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"これはちょっと的を外れているかもしれないですけれども、万が一つながらなかったら、要は２年つながっていないわけですよね。だって、この仮設をつくるだけでも何千万円なのか、億かかるのかわからないですけれども、相当お金が、その費用は税金なわけですから、その辺をどうお考えなのかというのを最後にお聞かせいただきたいと思います。答えられる範囲で構わない。","respondent":"稲田都市開発課長","answer":"仮設階段にしましても、あくまでも仮設ですので、本来つながるところにつながればというところではありますが、このあり方についても今後管理者等とも話し合いながら、どうすることが一番いいのかというところも含めまして考えていきたいと思いますので、そういう考えでおります。","voiceIndex":162,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択なのですけれども、品川区の進める再開発の破たんは明らかで、それが地域住民に悲鳴を上げさせていると思います。一方で、このデッキが接続すればオフィスビルの方はそこを通るわけですから、今の地域住民の不安や危険の軽減につながるので、その思いもよくわかるので、趣旨採択ということにさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"陳情者の方にもお話を伺ったのですけれども、再開発について、きれいになっていいとは思うがと書いていますが、と言いながら、むしろやはり超高層開発のまちづくりの弊害によって現実に不安を感じていて、このデッキがつながればそういう不安の軽減になるという思いからの陳情だと私は理解をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-063"}]},{"id":"topic-04","title":"平成３０年１月区営住宅入居者募集","agenda":"平成３０年１月区営住宅入居者募集","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"すみません、ちょっと確認させてください。今回募集が９戸ということなのですが、空き部屋が何戸あったうちの今回９戸なのかというところ、募集の９戸に対して空いている部屋は何の用途のためにとっているのかというところも少し教えていただきたいと思います。","respondent":"長尾住宅課長","answer":"そのうち、中延一丁目の区営住宅の建替えに伴う仮移転の方で５戸、前回の７月の区営住宅募集で、募集済みの住戸で今入居の手続を進めている段階のものが４戸、一つは現状復旧の工事中で、今回の募集には間に合わなかったものが１戸あります。","voiceIndex":182,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"具体的にどこの住宅というのを伺いたいのですけれども、この資料にも書いていただくことはできないのでしょうか。お願いしたいのですけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"予定では、西中延区営住宅で１戸、西大井六丁目区営住宅で１戸、東大井三丁目で１戸、南大井五丁目で１戸、南大井一丁目で２戸、そして現在建設中の中延一丁目区営住宅で３戸の予定でおります。","voiceIndex":184,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとできれば、こういった資料に書いていただきたいのですけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"詳細につきましては、冊子が完成しました後に委員にお配りしておりますので、現段階では予定ということでこのような記載にしています。","voiceIndex":186,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"予定ということなのですけれども、予定ということでもいいので、ぜひ明らかにしていただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-067"},{"speaker":"西本委員","kind":"確認","question":"確認です。今回９戸ということなのですが、キャンセル待ちとかはあるのですか。それとも９戸だったら９人だけという形になるのでしょうか。","respondent":"長尾住宅課長","answer":"こちらは抽選の際に補欠も含めて抽選をしておりますので、もしキャンセルされた場合は、その補欠の方の優先順位が高い方から次にご案内していくという流れでおります。","voiceIndex":189,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"補欠は、何人までとるという形になるのでしょうか。次の募集のときにまたスタートラインになってしまうのですか。その仕組みを教えてください。","respondent":"長尾住宅課長","answer":"補欠の方に関しては、各申込み住戸区分ごとにプラス５名を抽選しております。私が把握している限り、区営住宅で補欠の方も全ていなくなるというパターンはなく、皆さん大体ご案内して、それで入居しておりますので、今までのところでは運用としてはそういう形でやっております。","voiceIndex":191,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"すみません、ちょっとよく聞こえなかったのですけれども、要はそれぞれに５戸補欠の方が選ばれる。だから、順番が決まっていて、１番の人は入る、２番から６番までは待ち状態、結局今までの経緯だと大体その補欠の人たちは入れずにということなのか、それとも入っているということですか。入れずに、結局また次のときに再度申込みをしなければいけないということなのですか。","respondent":"長尾住宅課長","answer":"抽選の中で、まず当選の方が１名、補欠の方が５名抽選されます。当選された方がもしキャンセルされた場合は、補欠で当選されている方を優先順位に従ってご案内していきます。そのご案内が全て終わって、皆さん仮にキャンセルされた場合は、次の募集の中の住戸として上げられます。","voiceIndex":193,"id":"exchange-070"}]},{"id":"topic-05","title":"避難行動要支援者の支援体制づくりの手引き作成および配布","agenda":"避難行動要支援者の支援体制づくりの手引き作成および配布","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"一つだけ要望も兼ねてなのですが、一番下のところに、配布予定のそれぞれのところが書かれておりますが、これまでも要望されてきて、なかなか周知が進まない中でこういう冊子をつくっていただきました。こんな形でやっていきますというものがありましたら教えていただきたいと思います。","respondent":"古巻防災課長","answer":"具体的なところにつきましては、まだちょっと内部で検討しているところですけれども、今委員からもご指摘いただきましたとおり、使われてこその資料というのは同じ思いですので、丁寧に説明しながら活用が進むように配布をしていきたいというふうに思っております。","voiceIndex":202,"id":"exchange-071"},{"speaker":"筒井委員","kind":"質問","question":"聞き漏らしたかもしれませんけれども、実施計画の地区数のこの地区というのは何の地区ですか。","respondent":"古巻防災課長","answer":"これの１地区ごとに一つのモデル団体を選んで支援の実施をしているということで、各５地区は今申し上げた５地区なのですけれども、この１地区ごとに一つの団体でモデル実施をしているというふうにご理解いただければと思います。","voiceIndex":204,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとここまで言われたら、防災区民組織の方も悲鳴を上げるのではないかという不安があるのですけれども、それはどうなのですかね。私は、もっと区がかかわらなくてはいけないというふうに思っているのですけれども、そこら辺はいかがなのかということと、実際に体制づくりを担ってもらいたいと思っている防災区民組織の実態はどうなのかということなのですけれども、組織率は何％でしょうか。","respondent":"古巻防災課長","answer":"防災区民組織に関するご質問からお答えしますけれども、基本的に防災区民組織は町会、自治体を母体としておりますので、一部組織がない部分もありますけれども、基本的に２０１防災区民組織があるということで、ほぼ全ての町会に防災区民組織、町会を母体にしていますので。","voiceIndex":209,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"町会員が全員入っているわけではないですよね。実態的にどれぐらいの方が動いていらっしゃるのかというのは、区としてつかんでいるのか伺いたいというのが１点です。実際に区民の方々と意見を聞きながらつくったものであるのかどうかというのと、もし反応みたいなものがあれば、今の時点でつかんでいるものがあれば、この手引きに対する区民の皆さんの反応みたいなものがあれば、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"冊子そのものについては、これから区民の方にお配りするという段取りですので、まだこれ自体についての区民の声というのは防災課のほうに何か上がってきているということではございませんので、これから年が明けてからになりますけれども、お配りする中で。","voiceIndex":211,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとなかなかやはりご説明を伺っても、うーん、できるのかなという思いは拭えないのですけれども、ちょっとこれはやはり行政が一つ一つの組織に入って必要なイニシアチブをとって、必要な援助をして進めないと私は進まないと思うのですけれども、こういう具体的な対応マニュアルをつくっていくとか計画をつくるというのは、私は大事なことだと思うのですけれども、やはりそこに行政がもう少し、というか。","respondent":"古巻防災課長","answer":"そこを何とか進めていくために今回こういった形の支援体制を行っているですので、その中から、先ほどの答弁の繰り返しになると思いますけれども、さまざまな課題を注視して、よりよい活用というか、対策の促進が図れるような進め方を模索している部分もありますし。","voiceIndex":215,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"これを読んだときに、ちょっと皆さんは、えっと思っているのですよね。それが一つと、それとあと、共助というのは全て否定するものではないと思いますけれども、先ほどから言っていますように災害の基本的な法律とかでも区民の命と財産を守る責任は一元的には行政になるわけですね。なぜこういったことを防災区民組織、共助に任せるのか、その理由を２点目としてはっきりとお伺いしたいと思います。","respondent":"古巻防災課長","answer":"ですから、こういった中で、避難行動要支援者の支援体制をつくるということでお願いしていることについては、いろいろ難しい面は確かにあるというのはおっしゃるとおりではあると思いますけれども、そういった中で発災直後のことについてきちんと支援体制をつくっていきましょう。","voiceIndex":217,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"これでやめますけれども、結果として阪神・淡路大震災とかでも、近所の方に助けていただいているということもあるのですけれども、災害が起きる前からやはり行政が命と財産を守るというところを諦めてしまっているように見えてしまうというのですかね、そういうのはやはり私はちょっと違うのではないかというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-077"},{"speaker":"筒井委員","kind":"確認","question":"確認も含めてなのですけれども、区内２０１の防災区民組織、この防災区民組織というのは事前に登録とかが必要なのでしょうかということと、これは非常に大変充実したマニュアルだと思うのですけれども、ご答弁が出たかもしれないのですけれども、これは全部完璧にやらなければいけないということではないのですよね。","respondent":"古巻防災課長","answer":"それから一遍に今年全部やらなければいけないということではなくて、少しずつ進めていけるようにということも考慮していますので、またその中でご相談いただきながらこの手引きの中身、ご相談に応じながら地域の中でこういった支援体制づくりが進むことを。","voiceIndex":220,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"今後品川区内にも高層マンションがかなり建ってくると思うのですけれども、このマニュアルにも大崎ウエストシティタワーズの事例があって、これも非常に参考になると思うのですけれども、今後マンションが増えてきて、その中で独自の防災組織というのができると思うので、そうしたことで、新たな、今ご答弁がありましたけも。","respondent":"古巻防災課長","answer":"ですから、そういったところも含めて、それを防災区民組織という形で認識するということではないのですけれども、どこどこのマンションの管理組合については区と協議しながらいろいろ対策を進めているということと、それから。","voiceIndex":222,"id":"exchange-079"},{"speaker":"いながわ副委員長","kind":"確認","question":"確認だけ。この中で、名簿というのが年に１回配付されると書いてあるのですけれども、ちょっと確認だけでいいのですけれども、名簿というのはどこがつくった名簿なのか。これは統一性があるのかどうなのかだけ確認させてください。要するに、どこがつくった名簿を、防災課が出すのかわからないですけれども、ちゃんと統一性がある名簿なのかどうなのかだけの確認をお願いします。","respondent":"古巻防災課長","answer":"齟齬というのですかね、異動の時期によってちょっと違う名簿になっている可能性はありますけれども、基本的には同じ中身で、高齢者福祉課とも防災課とも共通で使わせていただいているものというふうに考えていただければよろしいかと思います。","voiceIndex":224,"id":"exchange-080"},{"speaker":"いながわ副委員長","kind":"質問","question":"何であの人は載っていないのだろうといったら、いや、施設に入っているからどうこうなのか、誕生日が要するにちょっとずれたおかげで１年間載らなかったとか、いろいろ何かあるみたいなので、その辺ちょっと僕も、すみません、質問しておきながら恐縮なのだけれども、要するにそういうことも地域では結構詳細にいろいろ見ながら、向こう三軒両隣なので、あれ。","respondent":"古巻防災課長","answer":"というのは、実は今回ここでお示ししている避難行動要支援者の支援のための名簿ですけれども、これは平時から情報を開示してもいいという同意を得られた方の名簿になりますので、その同意のない方についてはちょっとこの名簿からは除かせていただいております。","voiceIndex":226,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"防災区民組織となると、ほとんど町会経由になってくると思うのですけれども、そうなった場合、これを見たときにどう感じるかな。そうなった場合に、要支援をしてくださいというふうに申告をした形の名簿になると思うのですが、町会に入会されている方で認識はよろしいですか。その辺を町会に入会をしていない人も入っているのかどうか、そこら辺の確認はされているのでしょうか。その辺はいかがですか。","respondent":"古巻防災課長","answer":"避難所等を運営、さまざま大変な中でこういった体制づくりをしていただいているですので、防災課として考え方をきちんと地域のほうに説明させていただいて丁寧に進めていきたいと考えております。","voiceIndex":228,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"ステップ。ただ、やはり支援をする人たちの中心というのは町会の人たちが中心なわけですから、そこの心情的なことを考えると、やはり日頃からのつき合いですからね。誤解のないように。そうではなくて、何でこれをしなければいけないのか、するべきなのか、何のためにこの手引きをつくったのかということをしっかりと丁寧に伝えていただいて進めていただきたいと思いますので、要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":61214,"voices":235}},{"id":"h29-20171128-9","meetingId":"h29-cm11","date":"2017年11月28日","dateIso":"2017-11-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年請願第１２号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２９年請願第１２号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"この間、先ほど課長からもご説明ありましたとおり、さまざまな支援を年々重ねていただいて、とりわけ平成２７年からの特別支援等につきましては、私立幼稚園の方々も皆様喜ばれて、ただ、やはりさまざまな課題というものを抱えている中で、果たしてその時々の支援がこういう形でいいのかというのは、先ほど来、順を追ってお話しいただいておりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"こんの委員","kind":"質問","question":"今日結論を出すでお願いします。一方で、国の動きも幼児教育の無償化という流れも今後出てくる中で、まだそれはもう少し先の話となると、やはり子育て支援策の１つとして大事な家庭の幼児教育に対する家計の負担軽減というものが必要かなと思いますので、この請願については採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"本日決めていいと思います。そして、態度は採択をしたいと考えています。教育費の負担というのは、格差がどんどん拡大していると指摘されておりますが、私どももそのとおりだと思います。やはり未来を担う子どもたちにきちんと保育、教育するということは自治体や社会の責任であると思いますので、そういう点で、この要望については私どもも毎年賛成をしているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、採択でお願いしたいと思います。私たちの会派でもいろいろ議論を重ねた中で、教育費の負担軽減を行うため、本区では助成金の増額、そして所得制限の撤廃など、先ほども課長からご説明がありました。そしてまた、次世代を担う子どもたちのためにも、しっかりと育てる環境が大事だということで、今回のこの請願に関しては採択をしたいということで結論を出します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということで、さまざまなご説明をいただいたのですが、私立幼稚園に関しては３歳から５歳で３,２００人程度で、公立のほうは六百数十人ということで、特に４歳、５歳のお子さんたちの教育に関して大変大きな役割を担っており、今後も、その教育を担っていっていただきたいというところで、その補助というか、バックアップとしてこのような形で保護者の方々に支援をしたり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"}]},{"id":"topic-02","title":"平成２９年請願第１５号 一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２９年請願第１５号 一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ただ、区独自のカウント方法はその待機児童というのが、隠れ待機児童と言われる希望者を排除したものになっているというところに問題があると思います。つまり、４月に再申請しなければ待機児童としないというところに、やはり問題があると思います。そういったところもしっかりと解消していく、そういった立場に立たなければ、本当の意味で待機児童ゼロにできないと思うのですけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"もう少し人口が落ち着いてくれば、認可保育園で対応できる人数になってくることもあるかと思いますが、現時点では補完的な役割として認証保育所の利用も視野に入れていくべきと考えております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり区民がそれ望んでいると思いますので、入園を希望している方がどこにも入れないということがないように、しっかりと取り組んでいただきたいと思うのですけれどもいかがでしょうか。この間の不承諾通知の数などを見ますと、そういったことが懸念されるのではないかと思いますが、地域別の把握をして、それに合わせた形で認可保育園を増設をしていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"海側につきましても、今年の４月の時点では待機児童少なかったのですけれども、今マンションの建設が進んでおりますので、こちらのほうにも複数園の開設を見込んでおります。平成３０年４月には、待機児童数に合わせて、かなりバランスよく配置して開設する予定です。","voiceIndex":20,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"今地域ごとに、待機児童が２０人以上いたところは複数園の開設が見込まれるということでしたけれども、その２０人以上は、以前に示していただいた６つの地域に分けられた中で２０人以上の待機児童がいたということでよろしいでしょうか。その確認をさせていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの２０人以上というのは、もう少し細かく分けて西五反田・大崎地区に２園、小山・荏原地区には認証を含めて６園、他には旗の台・豊町が１０人以上ですので、そちらのほうに開設をいたします。","voiceIndex":22,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると６つの区割りよりも、もう少し細かく見ていただいているというところで、地域を細かく設定していますが、やっている対策は、隠れ待機児童とか、数を減らしたものでしているというところだと思います。あわせてこの間、来年度は待機児童がゼロになると見込んでいるということですので、もしならなかった場合、入れないという方が出てしまった場合の対策をするお考えはあるのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"今の想定以上に申請者が多くなり、現状のゼロに近くなるという見込みを超えた場合には、認可保育園で定員外の受け入れなど、対策を現在検討しています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"そうしましたら、今まで見込んでいた申請数よりも増えているのか、それとも減っているのか。現況をご説明いただけますでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"来年４月の申し込みについてはまだ締め切っておりませんので、何とも言えない状況ですけれども、１０月の待機児童につきましては、昨年同期よりも減っております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"申請数が減っているということでよろしいですか。先ほど区の負担が、８５％が５５％ですか、減るということで、事業費を捻出して待機児童対策に充てるというお話でしたけれども、やはりそういったことによらず、公立園は公立園としてしっかり残していただいて、その上で認可保育園を増やしていくといったことが必要だと思うのです。そしてこの労働環境について、私立と公立の違いを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ご質問の待機児童対策の関係と民営化ですが、区としては先ほどの待機児童対策担当課長の答弁にもありましたように、待機児童対策とは別に今後建て替えの費用だとか、その辺にかかる予算を抑える上で、民営化を進めることは重要だと考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"労働環境については、勤務年数が公立園のほうが１３年ぐらいでしたか、やはり長く働き続けられることによって、子どもが入っている間に保育士が変わらないということで、保育の質が担保されると思いますが、いかがでしょうか。お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"費用のほうですけれども、そうすると、先ほど建て替えの費用がかかるので民間委託するというようなお話があったと思うのですが、まず区で建て替えてから民営化、民間委託していくということだと、費用の削減にはならないということでよろしいのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"区のほうで責任を持って改修および建て替えをやった後に民間委託するという方向で考えております。","voiceIndex":35,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"品川区の中でも少ないということで、ぜひ増やしてほしいということを言っておりますけれども、区は今まで増やしているという答弁をされるのですが、防災公園といったものしか増えていないとのが現状で、やはり目標にされている１人当たり５m2でしたか、やはりそういった面でも、保育園の面でも、あとお年寄りが利用するために、しっかりと増やしていくことが必要だと思いますが、いかがでしょうか。","respondent":"溝口公園課長","answer":"ただ、一方でしながわ中央公園ですとか、ひらさん広場、なかなか用地の確保は難しいところですが、できる限り公園の整備というのをあわせて進めてきているところですので、総合的に品川区内全体、しっかりと皆さんに公園をご利用いただけるよう今既存の整備。","voiceIndex":37,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"防災については進めているということで、それはそれでやっていただきたいのですけれども、その防災の地域に入っていない、木密地域のところではないところで、今整備が進められているような場所は実際にあるのでしょうか。伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"防災は防災でやっていただいて構わないのですけれども、それ以外のところで、今進んでいる公園の整備を検討されているところがあるのか伺いたいと思います。","respondent":"溝口公園課長","answer":"そういった中でもまちづくりとあわせて公開空地、または公園、そういったものもあわせて整備していくような計画をしておりますので、まちづくりと一帯になった形で、そういった機会を捉えながら公園整備に取り組んでいこうというのが、今現状です。","voiceIndex":43,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、防災などは補助金が入って進められていると思うのですが、やはりそういったところに、区独自で格差是正のために公園をつくっていただきたいと思いますが、そういったお考えはあるのか伺いたいと思います。","respondent":"溝口公園課長","answer":"そういった中で、どういう形で財源を使って整備していくのかといったものも含めながら、今後もしっかりと公園整備には取り組んでいきたいというふうに考えているところです。","voiceIndex":45,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今同潤会のところでも公園をつくられるということでしたけれども、それができると何％ぐらい、この荏原の地域で上がるかお伺いいたします。そういったことで、臨海部には大規模公園があるということですけれども、荏原ではそういったものが作れないというお話だと思うのですが、小さくてもその目標に向かって格差をなくしていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"溝口公園課長","answer":"防災まちづくり、さまざまな形のまちづくり、または公園整備単体として、しながわ中央公園については公園として必要だということで、用地買収をして整備をしたところです。そういったものも含めて、今後ともしっかりと取り組んでいきたいと考えているところです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"園庭のない保育園などはあり得ないです。その辺の認識について区はどう思っているのかを１つ伺いたいと思います。民間委託の話が出たのでちょっと関連して伺いたいのですけれども、先ほどの説明でも八潮の２カ所がありますよね。それとこの４園の民間委託は、法人に委託するのか、あるいは株式会社なのか、どういうことを区は考えているのか、改めて関連して伺いたいと思います。","respondent":"大澤待機児童対策担当課長、吉田保育施設調整担当課長","answer":"考え方としては、もちろん園庭あったほうがいいと思うのですけれども、このような現状を考えますと難しいというところがあります。２番目の委託先は法人か、株式会社になるかどうかということにつきましては、最初のところは３３年の三ツ木保育園ですので。平成３０年４月の申請数ですけれども、現時点では集計できておりません。","voiceIndex":49,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"待機児童の集計ができていないということですけれども、今現在の時点の数字でいいからというふうに先ほど一言断ったので、教えていただきたいと思います。全体的にはもちろん民間委託はだめだという立場ですけれども、あえてそのことを強調しておきたいと思いますので、その辺についての見解を伺いたいと思います。","respondent":"大澤待機児童対策担当課長、吉田保育施設調整担当課長","answer":"園庭は大切だとは思いますけれども、今の時点ではそれよりも認可保育園を１園でも多く増やすことのほうが大事だと考えております。それと、以前の文教委員会でもご案内したとおり、八潮北、八潮西につきまして、１年程度委託の開始時期がずれるのですけれども、一括して委託業者を選ぶことによって、コストメリットが出せるような委託の形式を想定しております。","voiceIndex":53,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、民間委託はそういうことも含めて、考慮する必要があるのではないかなと思っています。それから申請者数については１,３３３人だということですけれども、私が伺ったのは地域ごとにどうなのか、地域によってあっちの保育園はあいているけれども、自分は６カ所選んだが不承諾になってしまった、だけれどもあっちの保育園には行けないのだという方も、過去いっぱいいたわけです。","respondent":"大澤待機児童対策担当課長","answer":"申請者の地域別というのは１０月の時点ではやっていませんけれども、待機児童を地区別に分けて、その地区に開設をしているので、一定その需要には応えられると考えています。","voiceIndex":56,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問・要望","question":"そもそもこの一人ひとりの子どもが大切にされる品川区を求める請願という題に違和感がありまして、その一人ひとりの子どもを大切にするというふうに出されるのであれば、当然まず第一義的な保護者であるとか、家庭の責務というものをしっかり出した上で、それでは品川区というのだったら話はわかりますけれども、そこをないがしろにして、まず区がどうこう、ましてやこの記書き以降、請願項目を見ると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"請願項目の１番については、認可保育園をこれだけ増設していますし、実際に数字も挙げてご説明をいただきました。ですから、区として、これからも適地があれば認可保育園を増設していく姿勢が確認できましたので、１に関しては、区としては対応してくださっていると理解をしております。ですから、２番については区としての考えが理解できます。したがいまして、今回の本請願については、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"私どもは、今日結論を出していいと思います。１番については、区は実際来年の４月、待機児童がゼロになるかどうかは甚だ不安な状況ですけれども、認可保育園を増設してゼロを目指していほしいという趣旨で、区の方針と変わらないので、当然採択していいのではないかなと考えています。３番の公園についても先ほど申し上げたようなことで、当然だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、私たちの会派では不採択とします。そして３番目に関しては、お年寄りから子どもまでの利用できる公園等の増設についてですが、本区には２６６の区立公園がありまして、今後も公園の場所を確保し、バランスのとれた公園整備を行っていくということでございましたので、この請願については不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今日結論を出すということです。不採択でお願いしたいと思います。それから２番については総合的な判断が必要というお話がありまして、改築や、そのほか将来の事情を考えて民営化を進めていっている、今現在全てを一気に民営化するということではなくて、諸般の事情を検討しながら進めていくというところですので、ぜひその点については検討内容は多岐にわたってきちんとしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"ですから、このことについては、私は採択という共通認識ができるのではないかと思って聞いていたのですけれども、他の委員の皆さんも区がやっているからいいのではないか、だから不採択だというふうにご主張される、そこのところがつじつまが合わない、道理に合わない、そういうご意見だと思うのですが、委員長はどういうふうに理解されているのでしょうか。","respondent":"つる委員長","answer":"先ほど皆さんが各会派の代表として、継続、結論を出すという態度に合わせて意見を出していただきましたので、その発言していただいたとおりというふうに認識をしております。","voiceIndex":66,"id":"exchange-027"}]},{"id":"topic-03","title":"平成２９年請願第１７号 区立小中学校給食費の無償化を求める請願","agenda":"平成２９年請願第１７号 区立小中学校給食費の無償化を求める請願","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"１点、今ご説明ありました、実質的に無償化が図られているというお話が前段のところであったと思うのですが、そこのところがちょっとよくわからなかったので、もう一度詳しくご説明いただければと思います。","respondent":"有馬学務課長","answer":"そういったことを鑑みても、給食にかかる費用は、全て公費で行われており、保護者の負担は給食食材費のみですので、実質的な無償化が図られていると考えているというふうに述べたものです。","voiceIndex":75,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"やはり無償化できていないということだと思います。そこで、近年滞納者の人数が何人いらっしゃるのか伺いたいと思います。この滞納者が増えているという現状を見ますと、やはり今、経済的な不況の中で子育ての負担も重いというところによる格差の広がりもありますので、そういったことを踏まえさらに経済的負担の軽減が必要になるということだと思うのですが、そこのところ改めて伺いたいと思います。","respondent":"有馬学務課長","answer":"それでも国が７人に１人が貧困だと言っているところで、５人に１人の部分で受給認定をしておりますので、低所得者対策に対する支援は十分できているというふうに考えております。","voiceIndex":77,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"そうなると、区の認識としては、この学校給食の完全無償化というのは必要ないということなのでしょうか。憲法第２６条には義務教育の無償化というところがあります。憲法第２６条には、義務教育の無償が書かれておりますけれども、やはりそれが必要だと考えているのか、その認識を伺いたいと思います。","respondent":"有馬学務課長","answer":"憲法第２６条の第２項の一番最後のところで、義務教育はこれを無償とすると書いてあるということだと思います。それを受けて、先ほど冒頭に申し上げた法の体系ができているものと考えています。","voiceIndex":79,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際に給食費を払っている方がいるわけですから、無償化はできていないと思います。総合戦略のアンケートの中でも、やはり教育の負担が大きくて望む子どもの人数が実現できていないという回答もありました。他の自治体では第２子から半額にしたりとか、さまざまな取り組みが行われていますけれども、そういった補助の拡大をぜひ行っていただきたいと思うのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"繰り返しになりますけれども、就学援助で２割、具体的に言えば２２.７％という形で認定をしております。それ以外に多子家庭世帯への３人目の補助として２５０名近い方への補助を行っておりますので、当面はこの形を継続していきたいと考えています。","voiceIndex":81,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は姿勢を改めないということですけれども、やはり私はこの教育費の負担軽減をしていっていただきたいと思います。先ほど来、法律に基づいているというお話ですけれども、学校給食法ですか、その法律の中では、役割分担を決めているだけであって、区がやってはいけないということではないと思います。そこは完全無償化に向けて、ぜひ取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"第３子の多子家庭への給食補助を２５０名ぐらいだとおっしゃっていたのですけれども、これは小学校と中学校で、それぞれ人数具体的に何人なのか、全体の児童生徒数の何％に相当するのか、その実態をちょっと教えていただきたいというのが１つです。３つ目は、この給食が教育であるという位置づけがどういうふうになっているのか、区の認識もあわせて伺いたいと思います。","respondent":"有馬学務課長","answer":"食も１つの教育にはなってきているというふうには捉えているところです。","voiceIndex":84,"id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"その点について、先ほど給食が教育の一環ではないかというふうな認識を問いましたが、改めて今日の給食の果たす役割について認識を伺いたいのと、５万５,０００円という金額が中学生の世帯にとってどういう比重を占めているかという認識、１人しかいなければ５万５,０００円は重たいけれども頑張るが、２人とか、多人数になってくるとなかなかの負担かなと思いますので、その点について区の認識を伺います。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"給食指導につきましては、指導の一環として学校では取り組んでおります。例えば給食の際の食事のマナーですとか、あるいは盛りつけをよそうなど、これは低学年の際には非常に分量という具体物を扱う絶好の教材となります。ただ、経費を誰が負担するかということはまた別の問題でありまして、きちんとした栄養を提供するといったことはそのとおりだというふうに考えておりますが、経費は経費で分けて考えていきたいと考えております。","voiceIndex":86,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"だからやはりそういう点で、ぜひ教育の充実という点で、少なくとも第３子目はやっているということなのですから、それを拡大していって、第３子の範囲をもっと広げるとか、先ほどのだて委員が質問されたように第２子まで広げるとか、順々でいいですから、無償化に向けてやはり施策として位置づけてやっていくべきだと考えていますけれども、最後にその点を伺って終わりにしたいと思います。","respondent":"有馬学務課長","answer":"冒頭の説明でちょっと触れましたけれども、これを区が全部負担をするとなると相当な経費で、年間で１０億円ぐらいかかります。","voiceIndex":92,"id":"exchange-035"},{"speaker":"こんの委員","kind":"質問","question":"ああ、こういうふうにしてくださっているのだなというところでありますけれども、先ほどやはり子どもの貧困という、こうした問題もある中で、今後国の動向も注視しますというご答弁がありましたが、国の動向というのはどのように今認識をされているのか、まずそこを１点、具体的なものが国として動きがあれば、その認識を伺いたいと思います。１点お願いします。","respondent":"有馬学務課長","answer":"近年子どもに対する施策の充実というようなことが言われているのが１点と、それからこの給食費の無償化が少し増え続けたというようなことがありまして、これ初めてですけれども、今年の９月に文部科学省のほうから、学校給食無償化等の調査ということが初めて実施されました。","voiceIndex":94,"id":"exchange-036"},{"speaker":"こんの委員","kind":"提案","question":"そこで少し紹介なのですけれども、こういった無償化についての動きというのは、実は２０１７年の５月に我が党でも、実は学校の小中学校、全小中学校における完全給食の実施ということと、それから地方自治体における学校給食の無償化の支援をしているところへ支援をしていくようにというふうに政府に提言、提案もさせていただいているところです。","respondent":"有馬学務課長","answer":"今回はまだ本当のさわり程度というような中身の調査だというふうには捉えております。やはりこの中での大きな問題は、最後には財源をどうするかというようなところも触れておりますので、そういったところが大きな課題になってくるのだろうと考えています。","voiceIndex":96,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ注視しながら進めていただきたいと考えています。ですから国の動向をしっかり注視して進めていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-038"},{"speaker":"渡部委員","kind":"意見","question":"私たちとしては今日結論を出して、不採択にします。もう冒頭よりお話もありましたとおり、私たち会派としましてもと言いましょうか。実費負担の原則はもうずっと、先ほど来課長のほうからご説明もいただきましたし、もうそれはそのとおりですので、今回特別何か議論するということなく、もう単純にこれは不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"結論は今日出すことでいいと思います。態度は採択です。その理由は先ほどの質疑のところでも言ったのですけれども、無償化をするとしたら経費として１０億円かかるということなのですが、一気にはいかないまでも、徐々に拡大をしてほしい。賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-040"},{"speaker":"松永委員","kind":"質問・要望","question":"その他の設備、人件費、光熱費などに関して、また消費税が５％から８％になったときに関しても、料金を据え置いている。今、先ほどもお話がありましたように、国でもそうした実態調査を行っているということでございましたので、すぐになかなか無償化するのはなかなか難しいのではないかというふうに考えておりまして、今回のこの請願に関しては不採択という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"意見","question":"もう議論が随分あったのですが、食材費のみ徴収していて、それ以外のさまざまなところは区が負担している分、実質的な無償化であると、無償化に近い状況であるということと、あと生活保護や就学援助でフォローしているという部分と多子家庭の方々にもフォローが行われているという観点から、先ほど貧困のお話ありましたけれども、今後そういった議論が進んでいくのだと思いますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-042"}]},{"id":"topic-04","title":"平成２９年陳情第１１号 園児の安全性に懸念のある「（仮称）キッズガーデン小山」（小山７丁目）の建築等を是正するよう求める陳情","agenda":"平成２９年陳情第１１号 園児の安全性に懸念のある「（仮称）キッズガーデン小山」（小山７丁目）の建築等を是正するよう求める陳情","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今の説明のところなのですけれども、９月２６日から２カ月間、２７回申し入れを行っているというのは、これは品川区の事業者に対する申し入れ回数のことであり、それに対して事業者がどういうふうに答えているのか、まずそこを伺いたいと思います。つまり、書類とか、必要な手続が何かということです。","respondent":"大澤待機児童対策担当課長","answer":"一つ一つに関しましては、今細かいことを全て申し上げることはできませんが、例えばこの陳情にも記載がありますように、セットバックについてきちんと社内で検討するようにということを申し入れて答えをいただいたりしています。","voiceIndex":114,"id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"品川区が認可するわけではなくて東京都が認可するので、それに当たって品川区が東京都に必要な書類を提出していると思うのです。事業者が直接提出するのもあるのかもしれないけれども、ちょっとそのあたりのプロセスについて伺ったつもりなのですけれども。","respondent":"大澤待機児童対策担当課長","answer":"認可の申請は一度区のほうで全て書類をいただきまして、区から東京都に申請をします。その後、児童福祉審議会が開かれて、そこで認可をされるかどうか話し合われまして、その結果認可という流れになります。","voiceIndex":116,"id":"exchange-044"},{"speaker":"南委員","kind":"確認","question":"その中に住民への説明会が義務として入っているのか、それともやったほうがいいよというようなあいまいな形なのかどうなのか、ちょっとそのあたりのことも含めて、どんな手続がどのように行われてきたのか、どこまで通ったのか。手続きが完璧に行われて提出、認可の申請になっていったのかというあたりのことを確認したいと思って聞いたのですけれども。","respondent":"大澤待機児童対策担当課長","answer":"認可の申請書類自体は、まだいただいていません。１２月の上旬を目途にいただくことになっているかと思いますが、申し訳ございません、今ちょっと細かい日程までは把握しておりません。ただ、認可の申請の中に説明会の有無という項目はなかったと思います。","voiceIndex":118,"id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"ちょっと聞き方がまずかったのかもしれませんけれども、東京都に出す申請書類で、計画承認というものがあるのではないかなと思っているのですが、そのことについて伺いたかったので訂正いたします。計画承認の申請手続がどういうふうに行われたのか、また、いつ提出されて、いつ計画承認がされたのか、それに伴って、先ほど申した近隣の方々への説明がどの程度行われているのか、そのあたりについてです。","respondent":"大澤待機児童対策担当課長","answer":"事業者のほうは２月から戸別訪問を行っています。４月までで、３回だったと思うのですけれども、行っていたかと思います。近隣への説明をしたかどうかというのは計画申請の際のチェック項目に入っていて、戸別訪問を実際にしていましたので、そこはクリアしております。","voiceIndex":120,"id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"そのあたりの認識を、今回また同じ方から陳情が提出されているという状況について区はどういうふうに認識しているのか、それが１つと、あと今申し上げたように、やはり説明がきちんとされていなかったということに尽きていくのではないかなと思っているのですけれども、そのあたりはどうだったのかについて区の認識を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"戸別訪問はしていたけれども、説明会を行っていなかったということで、それは９月の文教委員会でも説明させていただいているのですが、区のほうから事業者に説明会を行ってくださいということで申し入れをして、９月までの間に５回行ったものです。","voiceIndex":122,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"お話を伺うと、戸別訪問されたのだけれども、７月ぐらいのときに工事を始めますよという４日ほど前になって初めておいでになってびっくりして、一体工事というのは何の工事なのですかということで、改めて説明会開催を求めて、７月と８月に説明会を実施したと前回の９月の委員会ときにもそういうご説明ありました。結果的にはおさまっていなかったということだと思うのです。","respondent":"大澤待機児童対策担当課長","answer":"ただ、やはり個別案件によって全く事情が違いますので、一概にルールを課すということもどうかということもありまして、今その辺はいろいろなケースを考えながら検討しているところです。","voiceIndex":126,"id":"exchange-048"},{"speaker":"南委員","kind":"確認","question":"個別案件でいろいろ違うというのはわかります。あるいはもう少し詰めた話をきちんとしていく必要があるのかどうか。それから再確認なのですけれども、近隣住民の理解を得るということは、保育事業にとっては欠かせない条件だと、同じようなことなのですが、ちょっと角度を変えて聞くのですけれども、欠かせない条件だと思っているのですが、その点についての区の認識はどうなのかお伺いします。","respondent":"大澤待機児童対策担当課長","answer":"事業者に関しましては、いろいろこの間、最初の取っかかりでうまくいかなかったということはありますけれども、その後５回の説明会、また１０月、１１月で運営を考える会を３回、その後１２月以降において、開園後も。","voiceIndex":128,"id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"でも、実際問題こういう陳情の形で議会から品川区に２点ですか、要請をしてほしいという内容で出されているわけです。１つは建物の位置を変更してもらいたいということ。こういう発言について区は承知をしておられるのか、事業者が住民に対してそういう発言をしたことについてはどういうふうに考えているのか、そのあたりも伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"１点目の安全確保のためのセットバックは、既に変更しております。法令に反していないという言葉が事業者からどういう流れの中で出てきたのか、ちょっとわかりませんので、今私としては何のコメントもできません。","voiceIndex":130,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"法令に反していないのはもう当然のことです。それはこの間の経過であり、事実であるわけです。今回陳情がなされたのですけれども、先ほど示した３つの点、検討会云々とか、その３つの点についての進捗状況というのは、改めてどういうふうに進んでいるのか、ルール化については先ほどちょっと触れていましたけれども、再確認をしたいと思いますので教えてください。","respondent":"大澤待機児童対策担当課長","answer":"妥協点を見出すというのは、先ほども申し上げたように、運営を考える会の中で名前を変えてほしいとか、細かいことについていろいろ出ておりますので、それは事業者のほうも妥協点を見出して話し合いを進めて、そのお答えについては住民の方にお返ししている形です。","voiceIndex":132,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"他の場面で同じような状況のことで。そういう区の事業を補完していただくのですから、先ほども述べましたが区民の信頼、ご近所のご理解、ご協力、そういうことがなしには進まないのが保育事業だと思うのです。したがって、区の指導としてどうかというような答弁は、違うのではないかと私は思います。改めてその説明を求めるという点について、最後に答弁いただいて終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"事業者の説明に足りない部分があったので説明会等を開催するように申し入れたところです。","voiceIndex":134,"id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"失礼いたしました。結論を出します。すごく難しい問題です。この間キッズ・スマイル・プロジェクトは、品川区ですでに何カ所かやっておりますが、特段何か問題等も起こしているわけではないですから、それ相応に業者もやっているのではというふうに推察もされますし、今回、品川区としてもさまざまやっています。なので、ちょっとこれ以上のことはどうなのだろうということになりますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"一方で、業者のレスポンスの話がありましたけれども、やはりそうしたところの手当ても、区としてしてくださっているということもご説明がありましたので、引き続き住民の方からのご要望があるかと思いますので、そこのところは寄り添っていただきながら、業者がきちんと住民の方にご理解をいただけるよう中に入る区の役割というものをさらにお願いをしたいと要望いたしまして、区の今の現状。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"それで、来年の４月に開園していただくということは、これは待機児童をゼロにするという点からも、私どももぜひ開設していただきたいとは思っているのですが、オープンした後もまだ近隣と事業者との関係でもしそういう状況が残っていたとしたならば、一番不幸な思いをするのは子どもであり、預けて安心して働きたいというお父さんやお母さんたちであり、そこにしわ寄せを行かせないためにも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-055"},{"speaker":"松永委員","kind":"質問","question":"本日結論を出す、それで不採択でお願いいたします。先ほどの説明にもありましたように、事業者に対して２７回の申し出をされたということを伺っております。しかしそうした中で、住民との理解がまだ得られていない部分があるのかもしれませんが、また今後住民の理解を得るために説明会を行っていかれるとお伺いしましたので、今回のこの陳情に関しましては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今日結論を出すということで、不採択ということでお願いしたいと思います。ただ、こういったボタンのかけ違いといいますか、さまざまなことが起きるので、今後も運営を考える会ですか、それで対応していくということですので、ぜひ区としては継続したバックアップをして、近隣住民の方の理解を得ていただくよう支援していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-057"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その内訳がわかったら教えていただきたいということが１つです。それと保育課長の説明のところで、(3)の休日保育です。この年間の延べ利用数なのですけれども、１日当たりの登園人数とか、あるいは保育料がどういう内容になっているか、事務事業概要にはそこまで出ていなかったので知りたいなと思うので教えてください。質問が多数あるのですけれども、お願いします。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"同様に、株式会社・学校法人立ですと、常勤が２６４人、非常勤が１１２人ということになります。利用料に関しましては、既にご案内のとおり、平成２７年度に子ども・子育て支援新制度ができた関係で、休日保育に関する保育料の負担の考え方も整理されましたので、保育園に在園している方は無料です。","voiceIndex":152,"id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"今具体的な表を持ち合わせてこなかったのですけれども、株式会社・学校法人立の保育園の離職率とか在園勤続年数だとか、そういうのはどちらかといえば、公立に比べれば在職年数なんかも少ないです。質問が長く、くどくて申しわけなかったのですけれども、その辺の見方をどうしたらいいかというのを教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ただ、６年から１０年という方も、株式会社立全体では１７％ぐらいいらっしゃいますので、１年目の方ばかりではないということはわかるかと思います。","voiceIndex":156,"id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"保育という性質上、やはりそういうふうに思いますし、当然親としても、０歳で入れたなら卒園するまで同じ先生方の顔ぶれがそろっていたほうがいいし、一定の保育が継続されていくという点でもいいのではないかなと思いますので、定着していけるような支援、そういうものをこれからも引き続き努力をしていただきたいと思っているのですけれども、そのあたりの見解を区としてどのように考えているでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"保育士の定着に、やはり一定の賃金の保障というものが１つ重要なことだと思いますので、今回処遇改善の額を出しましたけれども、平成２９年度は平均でこれにプラス、月額で２万７,０００円ということでやっておりますので、今後とも国や都の制度を見ながら。","voiceIndex":158,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"私立園のほうでは、事故や衛生管理とありますけれども、当然これは公立園にも必要かと思いますが、私立園はやはり民間というところで、大丈夫なのという声があるため、より一層その部分への指導、目を向けることからかと思いますが、一方で公立園というのは実際どうなのかというところについて、どんなふうに区として公立園の指導をしているのか、その辺も教えていただきたいと思います。","respondent":"佐藤保育課長","answer":"公立保育園に対する研修の件です。５歳児対応に関しましては、保幼小の連携というものを品川区が独自の事業として特に力を入れていますので、５歳児担任については特別に個別相談や指導を必ず行うということです。","voiceIndex":161,"id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"ですから、その辺について保育士がどのようにお子さんに接しているのか、これまで何かあれば報告があったでしょうから、ないということは何もなかったと理解をしておりますが、お子さんが自分の言葉で自分の気持ちをきちんと伝え、嫌なものは嫌、いいものはいいということを伝えられない学年ほどきちんとした保育内容が必要かと思いますので、そうした点の指導はどうされているのか、お聞きしたいと思います。","respondent":"佐藤保育課長","answer":"そういった場合、先日の園長会で、各園の職員全員に、もし気になることがあれば直接保育課のほうか私もしくは係長に直接電話をして、何か気になる点があれば伝えるようにということを申し伝えておりますし、そのようなことはパワハラ等の抑制にもなりますので。","voiceIndex":163,"id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"そのような対応をとってくださるのであれば、引き続き声が保育課長のほうに上げやすい体制というのでしょうか、というものが必要かなと思いますので、よろしくお願いします。よりいい保育のため、保育士同士の関係、保育士の先輩後輩の関係など保育士関係というのも保育の質を担保する意味では非常に大事な点だと思いますが、そうしたところへの指導というのは何か対応をされているのでしょうか。","respondent":"佐藤保育課長","answer":"保育園ですと、当然各施設単位の縦の関係なのですけれども、委員ご指摘のとおり、横の関係というものは非常に大事だということで、昨今は若い職員も多いですので、なかなか年配の実力のある園長には言えないこともあるという話を研修等で聞いていますので、主任研修であったり。","voiceIndex":165,"id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"保育士確保というところでは、やはりこの保育士関係、保育士間の関係というところも非常に大事になってくると思うので、処遇改善のお給料の面だけではなくて、働きやすい環境を何かあったら相談窓口のように聞いてさしあげて、何か手だてが保育課のほうでもできるのであれば、そうした手だてをお願いして、保育士がその保育園で働きやすい保育士同士の人間関係が構築できるように。","respondent":"佐藤保育課長","answer":"現場の保育園で働く職員が生き生きとやりがいを持って働くことが一番大事だと思っています。そういった体制と、保育士もやりがいを持って働くことによって、子どもへのいい影響もありますので、委員ご指摘の趣旨を踏まえまして、これからも引き続き指導してまいります。","voiceIndex":167,"id":"exchange-064"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"この保育の質の確保についてというところで、保育課主催研修の実施状況というものがあるのだけれども、この研修会場はどこで何人ぐらいが出席していて、何回ぐらいにわたってやるか、あるいは講師はどういう方がやるのかを教えてもらいたいのですけれども。","respondent":"佐藤保育課長","answer":"講師の方もさまざまです。ベテラン園長に頼むこともありますし、保育の知識が豊富な大学等の教授の先生にもお願いしてやっていただくことも複数あります。研修の回数は、非常にたくさんやっておりまして申しわけございません。年間４０回から５０回ぐらいは行っております。","voiceIndex":169,"id":"exchange-065","title":"議員研修会の内容と所要時間"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"東京都福祉保健局でやっているのですけれども、研修として認可外保育園のスタッフたちに６回か７回のシリーズで、ずらずらと行ってやるみたいだが、これ回数はわかったのですけれども、研修の１クールというのが１回だけなのかお知らせください。","respondent":"佐藤保育課長","answer":"例えば、保護者対応研修ということで、保護者支援というものも非常に大事で、保育所保育指針に書かれていますけれども、そういった研修は全部で４回であるほか保育課の研修や、先ほどこんの委員からご指摘のあった乳児保育等、継続研修に関しましては全部で５回とか。","voiceIndex":171,"id":"exchange-066"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"結局これは公立の保育園のスタッフが、例えば新人だとか、一般職員だとか、副園長だとかというのが、会場に集まってきてやるという話になると思うのですけれども、例えば私立園の保育士が参加するとかは想定されていないのですか。","respondent":"佐藤保育課長","answer":"私立園に関しましても、真ん中の一般職員というところで参加をしていただいておりまして、平成２９年度であれば、これまでのところ私立認可園で２５２名の保育士が参加をしていただいています。","voiceIndex":173,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"１つだけ教えてほしいのですけれども、やはり今日いただいた資料の中で１時間延長でご利用されている方が多いです。そうなりますと、例えば通勤通学等の前段階を考えると、人によっては、例えば利用時間が７時半ではなくて８時からの１１時間ということになると、私はこれがぐっと減るのではないかなと思ったりするのですが、そういう考察というのはされたことありますか。","respondent":"佐藤保育課長","answer":"子ども・子育て支援新制度が、平成２７年度に制定されて、子ども・子育て計画の観点でも５年間を目途にさまざまな検討をすると思いますので、国等の標準時間の考え方が今後変われば、それに合わせて区のほうも対応していきたいと思っています。","voiceIndex":175,"id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"あまり８時半からとしている会社は聞かないですから。現在、さまざまな手法で保育士の確保というのをなさってこられていて、いわゆるセカンドキャリアだとかというのを支援していますけれども、実際問題、言葉は悪いのですが、施策として適当なのですか、つまり、そういうものを活用されて、これからもう１回保育士として頑張ろうかしら、というような方が区内に果たしていらっしゃるのか。","respondent":"佐藤保育課長","answer":"ですから保育士として働かれたりする方は、新規採用であったり、どこか民間で働いていた方が条件のいいところに移るという形で、一定の範囲の中で動いているというのが大方の見方なのかなと考えております。","voiceIndex":177,"id":"exchange-069"},{"speaker":"渡部委員","kind":"質問","question":"それで、なぜそれを聞いたかと申しますと、先ほど南委員の質問であったのですが、社会福祉法人立で何年とか、株式会社立で何年などという勤続年数、経験年数ですか、話が出ていましたけれども、これは、１園当たりにいる年数でしょう。","respondent":"大澤待機児童対策担当課長","answer":"今回の経験年数のところは、他の園から移ってきた方は以前の年数も加味しております。","voiceIndex":179,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"ということは、例えば社会福祉法人立では、そんなに長くはないのですけれども、７.５年とありますが、平均で７年で保育士を辞めてしまうということですか。いる方でならすと、大体平均だと７年で辞めてしまっているという見方なのですね。答弁はいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから研修のところで、研修に行かれたときの手当てというのでしょうか、手当てというのは人の手当てで、ある方が研修に行ってしまったら、他の方が見るというわけにもいかないし、多く見るのもあれなので、どのような手当てをされているのかをお尋ねします。そして指導検査のところは、私立保育園は保育園の数からすると３年に１回ぐらいで回ってくるのですか。大変すばらしい事業をやられているので。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"委員ご指摘のとおり、幼児教育の無償化というのは国でかなり検討が進んでいるのもありますので、国や都において制度化され財源があれば、区のほうも補助金を受けて、事業の拡充を図るというのが１点目と、財源の確保もありますけれども。それから区独自でも巡回指導には行って、気がついたときにはその場で指導はしています。","voiceIndex":182,"id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。何しろぎりぎりの人員で保育園はやられていると思います。そういう点については研修の重要性からも非常に認識するところでありますので、その辺についてどうでしょうか。","respondent":"佐藤保育課長","answer":"確かに研修の内容が充実しても、参加する方が多くなかったり、もしくは多岐にわたらないと意味がないと思いますので、委員のご指摘のとおり、工夫できる点はしていきたいと思います。","voiceIndex":185,"id":"exchange-073"},{"speaker":"のだて委員","kind":"確認","question":"あわせて、先ほど窓口を保育課に一括して空きを管理するとおっしゃられていたのは、私は一時保育のほうかなと思ったのですが、オアシスルームのほうをそういう形とするということなのでしょうか。ちょっと確認です。そして一時保育ですが、私立保育園の利用者が平成２６年度と比べて半分ぐらいに下がっているのですが、これは何かあったのか、区の見解を伺いたいと思います。","respondent":"佐藤保育課長","answer":"受付を保育課一本にするという予定で検討している件は、一時保育です。今現在、各施設に区民の方が電話して確認しなければなりませんので、それを保育課のほうで一括管理をするというところです。","voiceIndex":187,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"子ども・子育て会議の中で、この利用者の方が予約しにくいときは本当にしにくいということで、時間に合わせて電話して、とれればラッキーだというお話もありましたので、そういったところの改善をどう考えていらっしゃるのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"年間１万５,０００件以上の利用がありますので、これを保育課で受付けるというのは、かなり現実的ではないので、システムの導入のほうを進めたいというふうに、今考えております。","voiceIndex":189,"id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。やる回数などが増えたことによって、研修に参加できるようになったということなのか、区の見解を伺いたいと思います。この私立保育園の保育士の給与のほうなのですけれども、まず１点、これは素朴な疑問なのですが、学校法人立が株式会社立と一緒に書かれているというのは、分類としては株式会社と同じようなものだということで併記しているのか、そこを伺いたいと思います。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"一般職員につきましても、一応６００人ぐらい増えているというのはその関係で、メニューを追加したということが原因だと考えております。５年未満の園が今区内で１８園ありますけれども、１８園中１６園が株式会社立ですし、５年未満の園の９割は株式会社立であることから、新規園を開設したかどうかというところで。","voiceIndex":191,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":62817,"voices":198}},{"id":"h29-20171128-5","meetingId":"h29-cm11","date":"2017年11月28日","dateIso":"2017-11-28","committee":"総務委員会","time":"午前１０時００分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７２号議案 職員の育児休業等に関する条例の一部を改正する条例","agenda":"第７２号議案 職員の育児休業等に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この条例にかかわる方が非常勤職員の一般職ということなのですが、この非常勤職員の一般職というのは、庁内のどこでどのようなお仕事をされていらっしゃる方なのか、何人くらいいらっしゃるのか教えてください。この間、お聞きしたら、現状では対象者がいませんということなのですが、対象となり得る人はどのような人なのかを教えてください。","respondent":"黒田人事課長","answer":"育児休業ですので、この場合ですと１歳６カ月または２歳の子を養育しているですと、通常ですと、養育里親になっているという状況等でなければ、なかなか育児休業の要件に該当することがありませんので、現時点で、区では対象となる職員がいないです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"再任用の非常勤職員なので、お年が上の方が多いので、出産などにはあまりかかわりがないということなのですが、今言った、里親や養子縁組、あと、すごくまれだけれども、夫婦で年齢が離れていて、お子さんに恵まれたといったケースだと、これに該当するのかどうか。そこがもう一つ。再任用の短時間の方ということですが、フルタイムの人は正規と同じ扱いなのか。そこのところを教えてください。","respondent":"黒田人事課長","answer":"配偶者との年齢が離れている場合にも、この制度が適用されるということになろうかと思います。フルタイムにつきましては、一般職のフルタイム職員ですので、職員と同じ制度であるです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"改正内容のところで、１ページの２の改正内容の(1)のところは、非常勤職員の一般職の方で、(2)のところは、第３条と第４条と第８条関係は、全職員にかかわるというご説明でした。そちらのほうを見て、わからないのが、第８条は全部育児短時間勤務のことですよね。これと、今回の絡みがどういう関係なのか。どこがどう変わるのか、第８条関係で教えてください。","respondent":"黒田人事課長","answer":"第３条、第４条、第８条につきましては、育児休業を延長したり、再承認する場合に、今までですと、配偶者が疾病で入院したとか、育児休業をとらないと子の養育ができない状況のときは、特例として、区で再度延長を認めたり、再承認できるという規定だったのです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のところなのですが、育児短時間勤務、第８条のところは、保育園に入れなくて、育休をとらないで時短を選ぶということですか。一番最後、施行期日の前のところに「(2)の規定は育児休業を取得することができる全職員で、一般職が対象となる」とありますけれども、一般職の育児休業は、正規の方は３歳までかなと思っているので、その辺も少し教えてください。","respondent":"黒田人事課長","answer":"どのぐらいの人数の職員が対象となるのかですが、育児休業は３歳までとれますので、延長する予定なのかどうかというところは、ご本人でいろいろと違いもありますので、育児休業をとる職員が対象であるということになろうかと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"意見","question":"賛成いたします。一言、申し添えます。先ほども課長からご説明がありましたが、今まで認められていなかった部分を含めて休業の取得可能期間を長くするということについては、国でも働き方改革というところで、さまざま取り組んでいることに伴っての改正というところで、育児休業等の可能性がそれだけ拡大するということで、私どもとしては賛成いたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"我々も賛成いたします。今、働き方改革というものが出ております。さまざまな事情がある中で、このように働く人に対する対応がだんだんよくなってくるということは歓迎したいと思います。ただ、関係者への周知といいますか、まだまだ知らない人もたくさんいらっしゃると思いますので、その辺もよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-006"}]},{"id":"topic-02","title":"第７４号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約","agenda":"第７４号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の契約金額が、１０億９,６２０万円で決まったわけですけれども、資料の一番最後のところに断面略図がついております。深さは約４０ｍ、内径が１０.５ｍで、かなり大きな立坑であると思っているのです。この下水道工事は、工事として規模的に大規模なほうなのですか。予算の全体像もわかったら教えていただきたいと思います。","respondent":"持田河川下水道課長","answer":"全体の事業費です。こちらは上流部と下流部ということで、分けて事業が進められてありますが、今、予定としましては、上流部でおおむね６５億円、下流部で４５億円ぐらいということで、１１０億円というのを、全体の事業費ということで考えているところです。","voiceIndex":34,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。上流部が６５億円くらい、下流部が４５億円ぐらい、かなり大きな工事だということです。全部開通するのがいつなのかというのを教えていただきたい。立坑の工事の方法をわかりやすく簡単に教えてほしい。付帯工で防火水槽撤去等とありますけれども、これが一体何なのかを教えていただきたい。残土がかなり出ると思うのですが、残土処理のことで、どこで処理されるのかもわかったら教えてください。","respondent":"持田河川下水道課長","answer":"続きまして、工事中の防音対策等です。先ほど私が説明しました工法というのは、さほど騒音、振動等はない工法です。その後、トンネルの工事に入りますが、その際には、防音ハウスという大きな物置、倉庫のようなもので全体を囲うということになっています。","voiceIndex":36,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"契約のところなのですが、いつも伺っています、辞退の理由を１つ。落札されたところが、予定価格の９８.３％の金額なのです。漏れたところが９９.４％の入札価格なのですが、この差というのはどういうところであらわれているのか。そういうものははっきりするのかどうか、その点を教えてください。","respondent":"立川経理課長","answer":"１点目、辞退理由ですが、こちらは、配置予定技術者の調整がつかなかったです。それから、金額の違いですが、これは、それぞれの企業で積算した結果です。","voiceIndex":38,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"その辺がどうなのかなというのが、すごく関心があるのです。企業の中身というか、秘密といえば、秘密なのですかね。そういうところの違いで、金額の安いほうに決まっていくということなので、その辺を知り得る手立てはないのでしょうか。そこにすごく関心を持っているのです。","respondent":"立川経理課長","answer":"それぞれの企業がそれぞれに積算しているですので、内訳については把握できるのですけれども、実際、どういう経緯でこういう金額になったかというのは、そこまでわからないという状況です。","voiceIndex":40,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"２点。不動テトラと淺川建設の共同企業体が受注するわけですけれども、このような大きな工事をやる場合の募集対象者というと、全国になるのですか。その範囲を教えてください。","respondent":"立川経理課長","answer":"こちらは、いわゆる本店がどこにあるとか、そういった地域要件はないです。第２グループ以下になりますと、品川区内の業者であるということが要件になるです。","voiceIndex":42,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、近年、異常気象が報じられていて、降雨も１００ｍｍを超えることがあるというのが新聞報道であります。特に都心は道路面、それから、敷地がコンクリートまたはアスファルトになっていて、降雨を吸収する場所がない。そうしたら、この数値というのは、浸水被害を考えるならば、柔軟に見直しをするべきではないかなと思うのですが、その辺はどのようなお考えなのでしょうか。","respondent":"持田河川下水道課長","answer":"どこまでの降雨量に耐えられる設備をつくるかというのは、非常に難しいところです。","voiceIndex":44,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"しかし、やはりどんどん変えていかないと、１,２００万人の都民、まして都心部には、８００万人の方が住んでいる中で、特に湾岸に近い方の浸水被害はかなり高い確率で、我々でも想定できるわけです。そういうものは、河川下水道課でも数値を考えて、上げていく姿勢はあるのですか。ずっとここのところ５０ｍｍ対応で来ていて、その辺にギャップを感じるのですが、もう一度だけご見解をお聞かせください。","respondent":"持田河川下水道課長","answer":"なかなか所管で雨の対策の規模を決めにくいところはあります。しかしながら、５０ｍｍを超える部分についての対策を何も考えていないわけではなく、こういったいろいろな既存の施設を使いながら、５０ｍｍを超えるときでも対応できるようにという姿勢であるのは間違いないです。","voiceIndex":46,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"須貝委員の質問と似たようなところがあるのですが、私も５０ｍｍの降雨に対応する浸水対策というのが、今現実に戸越・西品川地区において起きている浸水被害をどの程度軽減することにつながると想定されての工事なのかなということを伺いたいと思います。","respondent":"持田河川下水道課長","answer":"ただ、何度も繰り返しますが、７０ｍｍ、１００ｍｍという、すごく大きな施設をつくるわけではございませんので、浸水被害といったものが完全になくなるかというと、そこはなかなか難しいところです。","voiceIndex":48,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"完璧ではないにしても、床上ということは、生活にも後々影響を与えるということで、最低限対策をするという趣旨と捉えてよろしいでしょうか。かなり大きな工事ですし、こういった工事による負荷というのも、近隣の方にはあるのかなと思うと、これでどれくらいの被害が防げるようになるのだという周知は、現地の方たちにはされているのでしょうか。その辺を少し教えてください。","respondent":"持田河川下水道課長","answer":"この事業につきましては、地域の皆様に説明会なども実施いたしまして、今、私が説明しましたように、５０ｍｍまでは、これまではためていたものが目黒川にざっと流れて、それ以上のものがためられますというご説明をしています。","voiceIndex":50,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、西品川一丁目エリアは、今、再開発が行われている中で、そういった大規模な工事をやられているところに、またもう一個工事を行うというのは、例えば、再開発をやっているところにうまく一緒に工事ができなかったのかというか、そういうところは検討されているのでしょうか。","respondent":"持田河川下水道課長","answer":"工事が最盛期になってきますと、ダンプトラック等の出入りで道路が込んでしまうということも考えられますので、そのとき、例えばどれぐらいダンプが出るのかというのは、そこに入った段階で少しそういった調整はしていきたいと思います。","voiceIndex":52,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど来からの集中豪雨や、そういった異常気象の被害が多い中で、前倒しというか、早く進めていただきたいなという思いがあるのが１点。地下４０ｍという意味では、かなり深度が深いところで、今、すごく複雑にいろいろなもので地下が掘られているといった中で、将来的な見通しというか、調整というのはどうされていくのか、わかったら教えてください。","respondent":"持田河川下水道課長","answer":"終わる時期につきましては、我々としてもできるだけ早く効果を出したいと思っていますので、できるだけ早めにと考えています。いかんせん工事の順番などもありますので、現在、検討した結果、平成３６年頃を見込んでいるです。地下の深いところの工事の調整です。","voiceIndex":55,"id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"大きく２つお聞きしたいのです。先ほどのご説明の中で、聞き漏らしていたら申しわけないのですけれども、西品川公園は、基本的に平成３６年まで全部使えなくなるということなのでしょうか。今日に向けて、私の会派の地元の議員に話を聞いたのですけれども、地元の方から議案に対しての異論というか、ご意見もあるようなことも伺ったのです。","respondent":"持田河川下水道課長","answer":"地元にご説明したときに、この場所を使われている団体の方や、イベントに使っていただいている方から、使えるエリアとして狭くなってしまうということでご意見がございました。","voiceIndex":58,"id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"地元の方も特に反対意見が燃え上がっているということではないと聞いていますので、丁寧にご説明をしていただき、これは必要な事業だと思いますので、しばらく辛抱していただくことに対して、理解を求めていくことも継続していただきたいなということが１点目です。実は、先日、区議会の有志数十人で、芳水小学校の建築現場を拝見させていただきました。その辺について伺いたいと思います。","respondent":"立川経理課長","answer":"大規模な工事の一部契約です。契約の原則としましては、公正性や競争性といったところが重要と認識しているものです。実際、どうなのかということなのですけれども、基本的には、競争入札ということで考えます。","voiceIndex":60,"id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"我々も、特に私も現場を見なければ、議会としては、１億８,０００万円以上のものについては、一つ一つの契約は分けたほうがいいのではないかという考えではいたのです。区も、今、それはお考えということがありましたので、ぜひそれは研究を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-020"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ご説明いただいたのですが、なかなか１個１個がわからない、難しいなと思っているのです。プロの課長自身が、ここの部分は品川区に取り入れたほうがいいであろうと思われるものはあるのでしょうか。かなりチェックが厳しくなりますね。そういった意味で、品川区の場合、こういうものが導入されてチェックする場合、職員は現状で足りていくのか、もっと必要になるのか。その辺も教えてください。","respondent":"立川経理課長","answer":"予定価格の事後公表なのですが、こちらは１,０００万円以上の予定価格については、事前公表としております。１,０００万円以下のものについては、予定価格を公表しておりませんので、そういった運用になっております。","voiceIndex":85,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"契約をチェックする意味で、談合などは本当に防止していかなければいけないという意味で、東京都でＪＶ結成義務の撤廃が談合を防いでいく方法だと考えているというのを聞いたことがあるので、そこがわかったら教えていただきたい。ここのところ、ほとんど制限付き一般競争入札の手法でやっていると思うのですが、現在、品川区において総合評価方式でやっている部分がどのくらいあるのか教えていただきたい。","respondent":"立川経理課長","answer":"続きまして、区で実施している総合評価の割合なのですけれども、実際、競争入札に付する案件は年間の工事では全体で３００件くらいです。今は、総合評価方式は、大体１割弱実施しています。こちらは、毎年少しずつ拡大していく必要があると認識しています。","voiceIndex":87,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"すみません。今の質疑で理解できなかったのですけれども、ＪＶ結成義務の撤廃ということで、義務を撤廃するのだと思っていたのです。だから、ＪＶを結成することは可能と理解していいのでしょうか。","respondent":"立川経理課長","answer":"これは、義務を撤廃するのであって、ＪＶとしての参加を拒むものではないです。ですから、今回、東京都においても、３５件中１０件はＪＶが受注しているというものです。","voiceIndex":89,"id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"確認ですけれども、大きな工事でも自発的にＪＶを結成して受注することは可能と理解してよろしいでしょうか。少し確認させてください。","respondent":"立川経理課長","answer":"これまでどおり、ＪＶでの受注は可能です。","voiceIndex":91,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"すみません。その続きなのですけれども、東京都の場合は、ＪＶ結成義務がいろいろな企業の参入を妨げているのではないかという理解なわけです。品川区の場合は、そういうことは感じてはいないということで、このまま継続されるつもりと理解していいでしょうか。","respondent":"立川経理課長","answer":"それは、皆様ご認識のところと思いますけれども、そういった金額だけを目的に実施しているものではございませんので、品川区としましては、ＪＶの結成義務については、このまま続けていきたいと考えております。","voiceIndex":93,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"今、一般的に、民間会社の場合には、入札予定価格は提示しないですね。提示しないで、それぞれが予定価格がない中で入札金額を出してくるという中で、どこが入札するかわからないですから、適正な金額と思われる価格を提示するようになって、より入札が公平な感じがするのです。その辺、いかがでしょうか。そこら辺の検査システムはどうなっているのですか。その辺についてもお聞かせください。","respondent":"立川経理課長","answer":"案件によりましては、当然そういった地域要件では事業者が集まらない、区内業者だけでは施工できないという案件もありますので、そういった場合には、適宜地域要件を外して発注しています。","voiceIndex":95,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"いつも思うのですが、品川区は公共施設をつくったり、学校を立て直したり、頻繁にやっている中で、我々は何度か不調に終わったとか、入札者が１者しかなかったという話を聞いている。やはりこれだけ品川区は予算、資金があるから、それぞれ公共工事云々を進められるのですから、本当に入札にあたっては、２０者、３０者が当たり前でいいのではないかと思うのです。ところが、今日も３者しか載っていない。","respondent":"立川経理課長","answer":"地域要件につきましては、それぞれの自治体で設けております。品川区だけが地域要件を外すとなると、これもまた難しい話かなと考えています。いずれにしましても、今後、日本全体の契約制度がどういった方向に行くのか。それから、国土交通省がどういった考え方を示してくるのか。","voiceIndex":97,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に１点だけ。今回、東京都の入札不調というのは、新聞報道でも出ています。９件のうち、２件しか入札参加者がいなくて、７件は不調。今、これだけ公共工事、民間のマンション、デベロッパーが動いている中で、あまり厳しい条件を提示すると、逆に工事ができなくなるのではないかなと。私もそう思いますので、適正な、または経理課でしっかりした入札制度、また改革をやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"「予定価格の事後公表」の６の「発注図書の充実」、「図面の詳細化、積算内訳書における数量表示や工程表の公表など」と記載してあります。その辺のところを確認させていただきたい。現在、どういった漏えい防止策の強化をしているのかお聞きしたいと思います。我が会派にも、いろいろと入札のことについては、建設４団体の方からも、区内業者にぜひ仕事をいただきたいという要望もあるのです。","respondent":"立川経理課長","answer":"東京都の入札に参加されている方もいらっしゃいますので、実際、６月に事業者向けの説明会が東京都で実施されております。東京都の制度ですので、区から周知するというものではないかなと認識しております。","voiceIndex":100,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"すみません、「低入札価格調査制度の適用範囲の拡大」というところなのですけれども、３のところに「低入札価格調査制度の運用厳格化」とあります。その中で、調査がいつ行われるのかということと、項目を厳格にしていくと、失格になってしまうという意味においては、結構失格というか、怪しいというか、問題を抱えているところが多いのではないかなと思われるのですが、その辺はどうでしょうか。","respondent":"立川経理課長","answer":"調査によって時間がかかっているという案件は、現在のところはないというものです。","voiceIndex":102,"id":"exchange-030"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"議会において、都の制度ではありますけれども、区内の業者から非常に強い要望をいただいておりまして、この案が３月に出てから、他の会派のほうにも行っていると思うのです。最初に伺いたいのが、都では既に大井ホッケー競技場の入札が終わっていると思うのです。これが、どういうところがとって、また、そこにはＪＶも参加していたのかどうか。もし情報があれば教えていただきたいです。","respondent":"立川経理課長","answer":"大井ホッケー競技場の入札状況につきましては、把握しておりません。","voiceIndex":104,"id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"こういうことはあってもいいことだとは思うのですけれども、前々から私どもの会派の要望として出していましたが、これは金額ではなくて、いわゆるオリンピックのレガシーに携わらせていただきたいという、品川区内の建築事業者の思いが非常に強いものがあったのです。品川区に影響が出ているということは、１つ指摘しておきたいなと思います。これは、都が認めているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"東芝病院の存続ということで、議会としても平成２９年２月６日に東芝病院の存続に関する要望書を提出していますので、今回も議会として要望書を提出していただきたいと思います。以上、お願いします。","respondent":"伊藤委員長","answer":"そのとおり取り扱いします。以上で、本件を終了いたします。その他で何かありますでしょうか。","voiceIndex":113,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":31873,"voices":115}},{"id":"h29-20171129-6","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"区民委員会","time":"午前１０時０８分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"本日は、都市型観光のうち、品川歴史館の活用","agenda":"本日は、都市型観光のうち、品川歴史館の活用","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それは住み慣れているところですから、ああ、昔はこういうところだったのだとか、昔の暮らしはこうだったのだとか、この道は今も残っているのだとか、そのようにすごく愛着を持って見られるのですけれども、逆に言うと、観光客の視点というのが正直言うとわからないのです。そういう意味では、区としてはどういう視点で考えようとしているのか、そこを伺いたいと思うのです。","respondent":"鈴木文化観光課長","answer":"先ほどご説明しましたように、本来の歴史館の機能としましては、区の貴重な、歴史的な資源の保存と展示をもって、区民の方に区の歴史や現状を知っていただいて、区に愛着を持っていただくというのが本来の趣旨です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問","question":"３の展示の概要の(2)特別展・企画展・コーナー展示のところで、さっきご説明があったかもしれないのですけれども、「※うち１５名は外国人」とあるのですけれども、これは記念イベントに参加された人数ということですか。","respondent":"鈴木文化観光課長","answer":"この※の外国人の１５名というのは、国際友好協会の協力をいただきまして、在住の外国の方が中心ですが、品川の歴史とか、日本の文化・歴史についてご覧いただくということで、国際友好協会に所属というか、いらっしゃっている外国人の方にご覧いただいたものです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"見ていただいた外国人の方たちからのご意見や感想とかが何かあったらお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"それとどうしても品川の歴史という視点よりは、外国の方々が見て、日本の文化や歴史がちょっと珍しいといいますか、関心を持つ視点だというところは意見をいただいております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"意見","question":"２の観覧者数の推移という括りで、５年度分が載っています。主な内訳が知りたいです。は区分として、１００円の有料入場者と、招待的な、無料というか、有料でない方の比率を知りたいというのが１つです。年代別とか、それこそ区民なのか区外なのか、何かしらの想定的な、推計も含めてあるとは思うのですが、その辺をお知らせいただければと思います。","respondent":"鈴木文化観光課長","answer":"ただ、今、茶室を含めて老朽化が進んできておりますので、観光資源としての活用と、施設の更新・改修も含めて、今年度ちょっと検討しているところでございまして、来年度以降、その計画が確定し次第、それに沿った手順を踏んで、改修なり。","voiceIndex":12,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"意見","question":"でないと、よりいいものを提供できないし、やはり多くの方に来てほしいというところで、そういう切り口を全庁的に検討すべきだというのが意見としてありますので、その辺の見解に含みがあるかどうか。これを含めて検討するほうが有意義ではないかという思いを持っていますので、この辺で、現時点で言える範囲でいいのですが、ご答弁願えればと思います。","respondent":"鈴木文化観光課長","answer":"品川歴史館の機能や内容のコンテンツ、それからアクセスの面での検討について、どのような状況、考え方かということだと思います。コンテンツにつきましては、ご覧いただいたように、建物の面積としては決して余裕があるわけではございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に、これは理事者の方に向けてではなくて、当然この質疑の中では、現状の品川歴史館をベースにしか答弁はできないし、全庁的になると、これはもう大きく超えてしまうことなので、大きな政治判断があってもいいかなという思いを持っています。これは別に答弁を求める話では当然ないのですが、ぜひとも機会があれば、区民委員会をはじめ、検討の場があっていいかなという感想的な話で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"木村委員","kind":"質問","question":"そういうもので品川区が今現在こうなっていて、過去にこういうことがあったということを皆さんに見ていただくのですが、また今度はそれにプラスして、今の品川区の良さとか、文化観光課として何かお客様の誘致をするためのものとつなげるようなことは考えられるかどうか、あったら教えてもらえたらと。","respondent":"鈴木文化観光課長","answer":"ご質問がありました、純粋な本来の機能である歴史展示以外の活用ですが、先ほども少し申し上げましたが、大政奉還１５０周年の関連事業を今年度・来年度と実施してまいります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"観覧者数をもう少し伺いたいのですが、確実な数字は今持っていないというお話だったのですけれども、まずは平成２８年度の１万２,０２２人の中で、学校教育で来ていらっしゃる方の数字がわかれば教えていただきたいのと、その前に、これに入っているのかという確認です。その辺のコンセプトを改めてお伺いしたいと思っています。これは感想ですけれども、質問に答えていただけますか。","respondent":"鈴木文化観光課長","answer":"ご指摘のように、今、一般の大人の方が１００円という入場料では、施設の維持管理また新しい資料の購入や発掘の経費はとても出るものではないですが、本来区の公立の施設として、区民の方に品川の歴史を知って親しんでいただくという趣旨の区の施設ですので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"質問した中で、ツアーがかなりあるとおっしゃっていたので、どのぐらいあるのか。品川歴史館に来た後に旧道でお食事するツアーみたいなものをどこかがしていますよね。何かあったのです、もし勘違いだったら申し訳ないのですけれども。だから、区外から来る方々がどのぐらいいらっしゃるのかというのを知りたいので、その辺についてお伺いします。","respondent":"鈴木文化観光課長","answer":"先ほどご質問の中にありました、品川歴史館に来て旧東海道を歩くようなツアーですけれども、区ではなくて、観光協会が主導しながら、ガイドしながわというボランティアのガイド団体がホームページで一定程度周知をしていらっしゃるようで、ガイドしながわなどの団体に。","voiceIndex":21,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川の観光という意味でお伺いしたいのですけれども、今日は品川歴史館のことですが、都市型観光という意味の品川という意味で、品川歴史館だけという意味でなく、ちょっとずれてしまうかもしれませんけれども、例えばしろへびサミットをした上神明天祖神社とか、ちょっと上がって下がって、大仏の五智如来とか、いろいろな意味で、品川歴史館の中にも今日出ていましたけれども寺社とか。","respondent":"鈴木文化観光課長","answer":"昨年度設置しました観光振興協議会で今、ショートトリップの専門部会を設置しまして、そこで今具体的にウォーキングの資源やエリアを検討いただいていますので、実際観光に携わる方の検討結果も踏まえて。","voiceIndex":23,"id":"exchange-010"},{"speaker":"塚本副委員長","kind":"質問","question":"今まで幾つか質疑があった中で１つ、シェアサイクルについて、かなり利用されているというお話がありました。利用頻度を見て、より多くの方に利用していただくためには、交通アクセスの問題はどうしてもあると思うので、車をとめられないとか、駅から遠いとか。今３台ですか、あの駐輪スペースというか、ポートを拡大することについてはいかがお考えかということを最初にお伺いします。","respondent":"鈴木文化観光課長","answer":"基本は３台ですけれども、今日は４台とまっている。それから、常にではないのですが、実は５台、６台、あそこはもともと品川歴史館を利用する方の駐輪場の一角に設置しているのですが、少し集中してたまったこともあります。","voiceIndex":25,"id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問","question":"わかりました。一応区外から来た方が訪れるのにはかなり有効なところがあると思いますので、今お聞きしたら、若干オーバーするようなところもあるということですので、できる限りニーズに対応できる検討をお願いしたいと思います。","respondent":"鈴木文化観光課長","answer":"なので、企画展に関しましては比較的、関連する所蔵資料をお借りしたエリアにはポスターやチラシで周知させていただいて、そちらのエリアの方にも来ていただくという連携もしています。その辺が大きな違いと企画展の狙いということで考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"塚本副委員長","kind":"意見","question":"特別展と企画展の性格の違いがあるということだと思うのですが、一応「災害と品川」という名前もちょっとシンプルというか、やや脚色もあっていいかなと思うので、人を呼ぶような感じで、決まったものでないのかもしれないのですが、その点も含めていいものにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":13492,"voices":36}},{"id":"h29-20171129-7","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"厚生委員会","time":"午前１０時１０分～午後 ４時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１「意見書（案）について」","agenda":"の１「意見書（案）について」","exchanges":[{"speaker":"若林委員","kind":"意見","question":"短時間で正副委員長で取りまとめ、意見書（案）を作成いただいて、大変ご苦労さまでした。感謝申し上げます。１点だけ、記書きの２と３について、本当に軽微なところなのですが、２のほうは「受動喫煙防止条例（案）」の頭に「東京都」がなくて、３番は「東京都」と頭についているので、ここはどちらかに統一したほうがいいのかと。こういう意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"共産党としては、この意見書を出すことに対しても反対で、特に３番の「今後予想される国の施策を見据えて」というところで、昨日も申し上げましたけれど、厚生労働省が出したものに対して、自民党から大幅な後退の案が出されて、本当に、それでは国民の命も、それからオリンピック・パラリンピックに来る来場者の方々の命も健康も守れないと考えていますので、この意見書提出者に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"}]},{"id":"topic-02","title":"」を行います。 初めに、（１）「第七期品川区介護保険事業計画骨子（案）","agenda":"」を行います。 初めに、（１）「第七期品川区介護保険事業計画骨子（案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今ご説明いただいた、今後のスケジュールのところなのですけれども、骨子案の配布場所というか、置いてある場所というのを今ご説明いただきましたけれども、そこに行くと、骨子案はいただくことができるのかどうか、それで骨子案は何部ぐらい印刷されているのか、１つお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"説明会につきましては、ご意見をいただくということで、まず先ほどのはがき、それからファクス、メール、持参等々でご意見をいただける体制をこちらで用意しているということで、説明会等については予定はしてございません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会ができない理由と、区民の方が何人か、こちらでやっていただきたいということで、そういう場所を設定しますので、ぜひ説明していただけないかというふうなお願いがあったときには応えていただけないのか、その点についてもお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"骨子案に限らず、ご不明な点等につきましては、常にご相談をお受けする、窓口・電話等でお答えする体制は、常にとっておりますので、説明会というものは予定はしておりません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民の側から、場所を設定したので対応していただきたいということに対しても、応えることはできないということでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"今の段階では、そのような対応は考えておりません。","voiceIndex":17,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はぜひ、本当に区民に対しての情報提供と、それから区民の意見を聞くというところがとても大事なところだと思いますので、その点については、ずっと言い続けているのですけれども、前向きにご検討いただきたいということで、改めて要望させていただきたいと思います。これは初めて取り組んだということで言っていましたけれど、看護師の団体、日本看護協会も取り組んでいます。","respondent":"寺嶋高齢者福祉課長","answer":"幾つかご質問をいただきましたけれど、まず先ほどのご要望ということでしたが、今の段階では説明会等の予定はありませんとお答えした、「現段階では」という部分について補足しますと、例えば説明を聞きたいということで、窓口に１００人ほど来られてしまったら。","voiceIndex":19,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど言いました１８０万人の署名というのは、それだけ、ほとんど全てのかかわる団体が、大変危機的な状況になっていることから、取り組まないではいられないというところで声を上げていますので、現場の状況を一番把握しているのがこういう自治体ですから、そこのところでは、現場の実態を厚生労働省なりにしっかりと届けて、介護報酬の引き下げをするなというのも。","respondent":"寺嶋高齢者福祉課長","answer":"地域包括支援センターの位置づけですけれども、品川区の場合は、従来の在宅介護支援センター、平成１８年度よりも以前の段階から、高齢者に関する総合相談をはじめとした対応を行ってきたところで、介護保険制度が始まって。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"在宅介護支援センターをサブセンターということで位置づけるのであれば、このサブセンターの中にやはり保健師をしっかりと配置すべきではないかと思うのですけど、改めて、条例との関係で満たしていないというところをどう考えられているのか、お聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"高齢者福祉課のということですけれども、保健師としましては、実人数、３人です。それから社会福祉士が、準ずる者を含めて１０名、それから主任ケアマネジャーが３名です。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、私はぜひ保健師を配置していただきたいということで、強力に求めたいと思います。そういうところで地域包括支援センターが位置づけられて、さまざまな取り組みをしているというのが他区の状況だと思いますので、ぜひそれはお願いしたいと思います。ぜひ情報の公表もしていただきたいと思うのですけど、その点についていかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"公表につきましては、今後もきちんとした情報が伝わるように、適切な公表となるよう努めてまいりたいと考えております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都で公表されているような、中身を充実させた形で、品川区のホームページにも公表を今後していくということでよろしいのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"東京都とのタイムラグ等の問題も含めまして、きちんと対応ができるか等も見定めた上で、必要な公表につきましては検討していきたいと考えております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あと、８ページの（３）に総合事業の推進ということで書かれているのですけれども、この総合事業というのが、第六期の大きく変わったところで、平成２７年から品川区は、いち早く行ったわけですけれども、総合事業をやって３年間、今年３年目ですけれど、総合事業を行った結果がどういうプラス面と課題があったかというところでの。","respondent":"松山高齢者地域支援課長","answer":"ただ、総合事業開始前に何度もご説明したとおり、事業者とは将来を見定めた上での協議をしております。必要な方につきましては、加算で対応しているという現状ですので、現在のところ、見直すという考えはございません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうなってくると、本当に、事業者はもう大変な状況になっていくと思うのですけれど、そういう中でも介護報酬が引き下がったままということになると、ますます危機的な状況を加速させることになると思いますので、そこのところはぜひ、少なくとも介護報酬まで引き上げるようにということで、ぜひお願いしたいということで要望します。","respondent":"松山高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"委員がお尋ねの、総合事業の検証のまとめの報告ですけれども、委員会等で、また介護制度推進委員会等で、その都度報告はさせていただいているところですので、その中で検証はできていると考えております。計画の中ではどうなっているかということになりますと、今の段階では２割で見込まざるを得ないという状況なので、これが、先ほど言った５,８００円程度という「程度」に含まれているところで、少なくとも３割の方が増えるということは。","voiceIndex":31,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あと１４ページなのですけれども、１番の「第１号被保険者数と認定者数の推移と見込み」というところで、ここに第六期から第七期、どうなっていくのかということで数字が示されています。このところがなぜなのかということと、それから例えば品川区では平成２９年の認定率が１７.７％になっていますけれども、今の段階で国平均と都の平均がわかったら教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"先ほどの３割負担の開始日等につきましては、一部報道されているところもありますけれども、そもそもどういう階層の方がというところで、一番肝心な設定のところがまだわかりませんので、これは見込みようがないです。それから、あと１４ページの認定率のところです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"長くなってしまってすみません。１５ページなのですけれども、２番の「介護サービス量の推移と今後の見込み」というところで、利用者の推移と見込みということで書かれているのですけれど、これは、保険料を出すに当たり、いろいろと、どれぐらい給付費がかかるのかということも書かれているのですが、要介護度別の認定者の見込みなどというのも、その中には見込みとして出るのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"１５ページのサービス量の見込みの中で、要介護度別ということでお話がありましたけれども、ここの部分につきましては、各サービスがどれぐらい伸びるかという相対の数字をあらわしたもので、もちろん保険料を見込むときの計算では、それに合わせて。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、その基金なのですけれども、昨日も、災害のために保険料が入らなくなった場合にということでとっておくのだというお話だったのですけど、改めて厚生労働省の文書を見ますと、基金の取り崩しの考え方というのが出ていまして、これは前にも少し申し上げましたけれども、介護給付費準備基金の取り崩しについてということで、これも厚生労働省の第七期の介護保険料算定に当たっての留意事項に。","respondent":"寺嶋高齢者福祉課長","answer":"一番重要なのは、見込みをなるべく正確に行うというところで、基金が急に増えたり減ったりということではなくて、計画的な基金の推移があるということ、それから将来に向けた、特に、昨日と重複しますが、できれば２０４０年代ぐらいのところまで。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ですが、こういう考え方ですということで述べているものなので、そういうところはぜひ参考にもしていただきたいと思います。それと、第七期の保険料が、一番最後の１８ページに書かれているのですけど、これは１段階から１４段階までというのは今までと同じで、割合も同じということですけれども、段階別の人数の割合というのがわかったら教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"その数値の割合等につきましては、その前の１６ページにグラフと表で記載しておりまして、ここの地域支援事業といったところが全体の割合になるものです。下の棒グラフで言うと、一番上のグレーの部分が地域支援事業を指しておりますので、ここの数字になります。","voiceIndex":40,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"課題として、先ほど課長から、介護予防ケアマネジメントの強化で研修も進めているということだったのですけれども、なぜそうした強化が必要になったと感じたのかとか、８ページの上のほうにあるゆうゆうプラザなども厚生委員会で視察などもしましたけれども、本当に元気な高齢者の皆さんが通ってきていて、お子さんたちもいて、いい空間だとは感じたりもしたのですけど。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"虐待しかり、認知症しかりですけれども、こういった対応が非常に増えておりますので、ケアマネジメントの強化というところが必要になってくるというのが全体的な考え方です。私からは、介護予防ケアマネジメントの必要性についてですけれども、これまでもケアマネジャーは介護の知識を深めてまいりましたけれども、こちらのほうで、やはり自立支援についての共通理解を深めるということで。","voiceIndex":43,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それをここであらわすとなれば、本当に大変な膨大なページになってしまうと思うので、やはりちょっと見られる形でまとめておいていただきたいし、それで区としても、そうした振り返り、ＰＤＣＡサイクルではないですけど、そうしたものが明確に進められるのではないかと思うのですけれども、そうしたものをつくる考えはないでしょうか。それと、１２ページの施設整備のところです。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"ＰＤＣＡサイクルと、それから第六期の検証ということですけれども、第六期としてざっくり出してということで、わかりづらいというご指摘であれば対応も考えるのですけれども、逆に、毎年、運営状況をご報告して。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１点だけ。第七期の基本的なところで、たしか介護離職ゼロという言葉が強く出ていたと思います。これは９ページだと一番下に出てきますが、これは施策の展開になってしまうかもしれないのですけど、どのようなイメージを持たれているか。ここのところに、「総合的なケアマネジメント」という言葉が出ているのですけど、この辺、どのような考え方か、概略だけ教えていただければと思います。","respondent":"寺嶋高齢者福祉課長","answer":"あと介護離職ゼロというときに、いろんな要素がありまして、やはり一番、現状に詳しいのは、何といっても運営法人ですから、その原因について、どういったことが原因で、例えば離職者が出るのかといったあたりは、今年度もそうですけど、来年度にもかけまして。","voiceIndex":49,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"確認","question":"介護人材という面から、今のお話をいただいたと思うのですけど、介護しながら仕事を続けていく方。そっちのほうの介護離職ゼロというのが今回出てきていると思うのですけど、そっちのほうについての確認をしたかったのですが。","respondent":"寺嶋高齢者福祉課長","answer":"それ以外につきましても、いわゆる、そういう介護者の方に集まっていただいて、介護者教室という名称でいろいろと、こちらから介護に関するアドバイスであるとか、リフレッシュの仕方等を含めた生活の仕方というのですか、そういったこともご案内しながら。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、現状、区で行っているのと、それから働き方というか企業側に対する働きかけというのも今回出ています。その辺がこの計画の中にどういうふうに盛り込まれているのかという、そこがわからなかったので。","respondent":"寺嶋高齢者福祉課長","answer":"あとサービスの利用の仕方というところが、また１つ変わってくるので、こういったサービスの利用の仕方があれば、企業も対応が可能であるなどというところの、サービスの利用方法などについてもご案内ができれば、１つ前に進むのかとは考えております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"施策はもう本当に、今ある中でこれから検討していってもらうと思いますけど、この計画の中に、自分からすると、その最後の部分が読み切れなかったような部分があったので、それが確認したかったところです。どこかにあったらすみません。自分がそこまで、短時間の間に読んでいなかったのかもしれないので、その辺をまた教えていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７月１１日の厚生委員会の中で、介護保険事業計画の改定に伴う高齢者アンケート調査というものの報告があったと思うのですけど、この結果と分析というのがどうなっているのかというのを教えていただきたいと思います。そして来年の８月から施行されるという状況になると思うのですけど、そういう点では、ここの中に組み込まれていくのではないかと思うのですけど、その点について、その３点をお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"夏に実施しましたアンケートですけれども、締め切りの後も提出していただく件数が多かったので、１件でも多くということで、締め切りを延ばしてお受けしたところです。","voiceIndex":57,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"アンケートは、では全部集計ができた段階でぜひご報告いただきたいと思うのですけど、その点だけお聞かせください。もう一つ、すみません。介護施設についてはまだ今のところは計画について示せるものがないということなのですけど、ぜひ計画を第七期の中で立てていっていただきたい。これも時間のかかることですので、ぜひそういう方針を持っていただきたいということで要望しておきます。","respondent":"寺嶋高齢者福祉課長","answer":"アンケートにつきましては、ご説明の時期・方法等につきましては、今まだ決まってはおりませんけれども、ご提出いただいたアンケートなので、情報としては何らかの形で必ずご報告できるようにしたいと考えております。","voiceIndex":59,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"特に拡充というのか充実というのか、１１ページのプロジェクト５「医療と介護の連携の推進」のところで、これは確認ぐらいのご答弁でいいと思うのですけれども、（１）「連携体制の強化」の中で、第七期には医療と介護の連携相談窓口を設置するということで、これについての、何というか、中身、内容、またどういう体制になるのか等スケジュール的なもの、これをお示しいただきたいと思います。","respondent":"大串福祉計画課長","answer":"そちらの窓口の設置につきましても、今現在、我々のほうでも検討しておりまして、対応する組織といったものもつくっていこうといったところで、どのように、医師会あるいは介護の双方の連携ができるような形で対応ができていくのか。","voiceIndex":62,"id":"exchange-025"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、全体としても、地域福祉計画というか、地域福祉に包含されている地域包括ケアということで、医療と介護も含めた、いわゆる複雑な事例とか、１つのセクション、部署で対応し切れない、できない事例というのがどんどん増えているということですので、医療と介護も含めた、いわゆる地域福祉としての、何か総合的な、ワンストップ的な窓口という色彩も含めて、要望になりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"}]},{"id":"topic-03","title":"品川区障害福祉計画・品川区障害児福祉計画（素案）』およびパブリックコメントの実施について","agenda":"品川区障害福祉計画・品川区障害児福祉計画（素案）』およびパブリックコメントの実施について","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントの募集期間を長くしていただいてありがとうあります。それで、「パブリックコメントの実施について」というところから、まずお聞かせいただきたいのですけれども、当事者の意見を聞いてほしいということでの請願が全会一致で趣旨採択されて、それを受けて、さまざまな団体からの申し入れに応えていただいて、これも本当にありがとうございました。それと、もう一つ。","respondent":"飛田障害者施策推進担当課長、中山障害者福祉課長","answer":"この間のアンケートは、今度またパブリックコメントがありますので、一緒に添えてと考えております。当日の資料も持ち帰りできるようにということで、今後考えてまいります。","voiceIndex":70,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回計画（素案）についても、そういう形で、希望する方には提供していただきたいということで、ぜひ対応していただきたいと思うのですけれども、その点もいかがでしょうか。それから、あと、今度傍聴に来られた方には合理的配慮をしていただくということでよかったと思うのですけれども、この計画（素案）についての合理的配慮というのは、どう考えられているかということもお聞かせいただきたいです。","respondent":"中山障害者福祉課長、飛田障害者施策推進担当課長","answer":"品川区地域自立支援協議会ですが、事前申し込みを基本としつつ、当日の会場にもよるかと思いますので、その辺は臨機応変な対応をしていければと考えています。ですので、ワードで読み上げて、聞き取り、リスニングでわかるようにはしたいとは考えております。点字やデイジー版など、要望があれば、またそこも対応する必要はあるかとは考えております。","voiceIndex":73,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新宿区の計画の素案だと、全部、読み取りができるような形での素案ができているのです。もう少し続けていいですか。そういう形で、障害者の計画に対してもＰＤＣＡで、１年ごとに、そういう計画がどこまで来たのか、そういうものをぜひまとめて、この厚生委員会にも報告していただきたいですし、品川区地域自立支援協議会には報告されるということになるのか、そのことの確認もお願いしたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"最初の、デイジー版や点字版等、今回のところ全てに合理的配慮を行うというのはなかなか難しいかと思いますが、今後のこともありますので、また検討させていただければと思います。","voiceIndex":76,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、資料についてはたくさん用意してくださるということだったのですけど、それは、ある程度までは、欲しいという方には、いただけるということでいいのかということが１つと、それから、これだけの団体にヒアリングをしてきましたので、ヒアリングをされた団体には、ぜひこれは何部かずつという形でも配付していただきたいと思うのですけれど、その点についてもお聞かせください。","respondent":"飛田障害者施策推進担当課長","answer":"今回、いろいろ団体のご意見をいただきましたので、またこちらを見ていただいて、またそれとともにいろんな意見があると思うのです。そこのところで、いろいろ、パブリックコメントとあわせていただければと考えていますので、配りたいと思います。","voiceIndex":78,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ本当に配付、いただきたいという方に対しては、計画そのものが配付されるということになってよかったと思います。ぜひ、この計画を立てるに当たっても、そういう視点を持っていただきたいと思ったのですけど、その点、障害者権利条約の位置づけというところはどう考えられているのか。そのことについて少しお聞かせください。","respondent":"飛田障害者施策推進担当課長","answer":"１ページ目の文面というところも、今ご意見をいただきましたので、そういうところもまた検討していきたいと考えています。","voiceIndex":80,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あと、先ほどもさまざま意見が出されたというところでもお聞きしましたけれど、情報が得にくいというところでは、２１ページの「今期の福祉計画における主要テーマと今後の取組み」というところで、（１）「相談支援の充実と適切な情報提供」の「現状と課題」の９行目に、「情報格差が生まれることなく、利用者が障害福祉の制度をよりよく知ることのできる環境づくりが大切」と書いてあるのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"そこの情報の共有のところでは、連絡会等も開きまして、そういう施設の状況とか、そういうところで共通認識をもっていきたいと考えております。","voiceIndex":82,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"あと、（１）「国の基本方針」では、平成３２年度末時点で、平成２８年度末の施設入所者数の９％以上が地域生活へ移行することということで、９％を目指すのが、この国の基本指針ということなのかと思うのですけれど、それに対して、品川区の場合は２％の６人ということにされているのは、どういう理由からなのか。","respondent":"中山障害者福祉課長","answer":"グループホームもそうでしょうし、あるいは例えば現在、グループホームにいらっしゃる方がさらに地域移行ということで、民間のアパートなどで暮らされる方も全くいないわけではないので、そういった全体の仕組み、あと地域での日常生活を支える仕組みがなければ。","voiceIndex":86,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当にグループホームは、ここの場でも何度も課長からも足りないというふうなことで、もっと増やしたいという思いだということも言われていたのですけれど、４１ページの2)「共同生活援助」の実際のこれからの見込量、グループホームはこれですよね。この共同生活援助というのは、何とかもう少したくさんつくれないのだろうかという思いがしているのですけれど、その点についてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、できれば年間２カ所ぐらいずつはつくりたいというようなことで予算的な措置はしておりますので、またグループホームを建設したい、あるいは運営したいというようなご相談があったときには、丁寧な対応で。","voiceIndex":88,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところで言えば、他区で展開している事業所にも、どんどんプロポーザルで品川区に入ってもらうような考え方というのもすごく大事なのではないかという思いがしているのですけれども、介護保険というか高齢者福祉では、特別養護老人ホームにしてもグループホームにしても、どんどんプロポーザルをかけて、さまざまな社会福祉法人が各県から来ているではないですか。","respondent":"中山障害者福祉課長","answer":"今回、南品川の児童学園の跡施設についてもプロポーザルで事業者を決定したというのは、１つそういうこともあったと考えています。それで、プロポーザルをやるには、やはり土地があって、そこに建物を建てて運営をしてもらう。","voiceIndex":90,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほかの区にもそういう場合はどうですかと聞いたら、そういうふうなことでプロポーザルをかけるのであれば、多分、それは検討に値するということもお聞きしたのですけれど、そういう形でできていくのではないかという思いがしています。やはり品川区の障害者福祉のサービスは、質・量ともに２３区の中でも最低の状況ですというお話をされたときに、濱野区長が、おっしゃるとおりですと言われたのです。","respondent":"飛田障害者施策推進担当課長","answer":"区長からも今後、福祉にも、今回の障害児者総合支援施設を１つの糧として区内にも広げていくというところで、一緒にまた障害児者福祉の施策をよりよくしていきたいと考えております。放課後等デイサービスのところです。","voiceIndex":92,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことで言えば、今、基本１０日で５.５日のところが、今度１０日になるということで、基本１０日というのは、私はなくしていただきたい。そして、その人に合わせた療育の必要性というところから、この日にちというのは組んでいくべきだと考えていますので、基本１０日という要綱上の制限というのもなくすのか、なくしてほしいという要望とあわせて、そのことをお聞かせいただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"保育所等訪問支援は今現在、１人利用があるというところですが、やはり体制を整えております。今後も、あくまでも見込量ですが、これより増えていくというところはこちらも望んでいるところなので、一応、見込量としては、今までのところではこのぐらいかと考えております。","voiceIndex":94,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、これをどこが請け負って、体制をどうとるのかというところもお聞かせいただきたいと思います。それで、そうやるのだとしても、独立した体制をとらなければだめですということで、文書としても出しています。そういう点では、平成３１年の障害児者総合支援施設ができて初めてそちらに移るという形にしかならないのか。そこまでの間、区で体制がとれるのか。その辺についてもお聞かせください。","respondent":"飛田障害者施策推進担当課長","answer":"確かに今、区でやっているところですが、平成３１年度の障害児者総合支援施設には、順次、移行はしていきたいとは考えておりますが、まだそこのところは、どのように、またどこの事業所が行っていくか、また、そこだけでやるのか、現在、検討しているところですので、また。","voiceIndex":96,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、先ほど、基本１０日はそのままにして、必要な人には出していくということなのですけれども、もう、１人１０日というふうなことで、平均でもそういうふうになっているわけですから、私はもう、厚生労働省の文書どおりに、ぜひ要綱でも基本１０日はなくしていただきたい。","respondent":"飛田障害者施策推進担当課長","answer":"現在、戸越でやっていますコンパス等では、月４回もしくは２回という、利用日数が少ない方もいます。ですので、そういうところもまた鑑みながら、利用者、また保護者と話し合いながら、その人に合った日数の提供をしたいと考えております。","voiceIndex":98,"id":"exchange-039"},{"speaker":"若林委員","kind":"質問","question":"私たちの問題意識では、本当にここの相談支援が今後、どうニーズをしっかりとお聞きしながら、提供体制の確保も含めて区がしっかり適切に対応できるかという、大もとのところなのだろうというふうな理解を今しながら進めていきたいと思うのですけれども、今のところについて、特に相談支援体制の構築については、今の委員の中でも。","respondent":"飛田障害者施策推進担当課長","answer":"今回、相談支援体制の構築というところで、今までも進めていたところです。地域生活支援拠点３カ所ということで、障害者生活支援センター、福栄会障害者相談支援センター、グロー障害者相談支援センターの設置をいたしました。","voiceIndex":101,"id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"次の２２ページの（２）「障害者の高齢化への対応」ということで、これも、私たちも含めて議会の中でたびたび議論になっておりまして、今後の取り組みの方向性というところで、一定、方向性が出ているのですが、最後のほうに、高齢福祉施策との連携とともに、サービス支援に係る者が理解を深めることで、適切な運用を行いますということでありますが、計画の素案ですので、文章にすると、こういうことで。","respondent":"飛田障害者施策推進担当課長","answer":"こちら、また介護保険の対応、移行になりますので、そういうところでは、基本的には６５歳というところなのですが、６５歳の方だったら、６４歳の、１年前から、もう実際、少し検討しながら、今もそういうところで、何人かピックアップして想定しているところです。","voiceIndex":103,"id":"exchange-041"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私は以前、所管は違うのですけど、小中一貫教育推進委員会に出たときに、４個か５個ぐらいある部会の報告があって、そして推進委員会が始まるという形だったのですけれども、ここもこういう専門部会があるのであれば、そういった部会の報告というものがされる、公開というか公表されるところがあるのかどうか伺いたいです。","respondent":"中山障害者福祉課長","answer":"今回の品川区地域自立支援協議会は、既にさまざまそれぞれの部会で検討したことが、この計画の素案の中に入っているために、それぞれの部会からの報告というのはなかったのですけれども、通常の品川区地域自立支援協議会ですと、現在の部会の状況ということで報告があります。","voiceIndex":106,"id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、品川区地域自立支援協議会に出られている方の中に、この部会の方がいるのか。部会の方が出てきて報告をされる。報告のされ方というのですか、それを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"例えば相談支援部会は、メンバーがこちらの品川区地域自立支援協議会にも入っていますので、その方が報告しますし、逆に日常生活用具検討部会ですと、行政のほうから、その部会で検討された内容を報告するというようなことになっております。","voiceIndex":108,"id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"わかりました。そうしたら、続いて２６ページの（６）「人材育成」の「現状と課題」のところに、利用者に身近な地域において相談支援事業や障害者福祉サービスが提供できるよう、多様な事業者の参入を促すとともにとあるのですけれども、４８ページの2)「相談支援事業」を見ますと、設置数が４カ所なのです。ここの表と文言の関係を教えてください。","respondent":"中山障害者福祉課長","answer":"それで、４８ページの「相談支援事業」というのは、地域生活支援事業の中の相談支援事業ということになりますので、いわゆる計画相談ではなく基本相談をやる、そういったところの箇所数になっているところです。","voiceIndex":110,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、２６ページで言っているものと、４８ページで見込んでいる箇所数というのは違うものということなのですか。","respondent":"中山障害者福祉課長","answer":"あるいはケアプランだけではなく、さまざまな就労継続支援Ｂ型でもそうですし、特に就労移行支援などは民間事業所も数多く参入していますので、そういったところとも連携しながら、区内にいろいろな支援の幅を広げていければと考えているところです。","voiceIndex":112,"id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それと、３１ページの下の３「地域生活支援拠点等の整備」の（２）「成果目標」のところの、さっきも地域生活拠点コーディネーターという名前が出てきて、ここでマネージャーと出てくる。ここは全体的に文章が、やはり「成果目標」なので大事なところだと思うのです。これもよくわからないのです。全体的に、ここで何をどう具体的にしようとしているのかがわからないので、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ただし、区内には２カ所、ショートステイがあったり、あるいは地域の拠点の相談支援事業所がありますので、そこに緊急対応とか、リスク把握をしたりという、前もっての準備をするようなマネージャーを置くことで、なるべく未然に対応ができるようにというような形で、今。","voiceIndex":114,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３７ページの2)「自立訓練」というところなのですけど、この生活訓練のところのｂの「見込量の確保等にあたって」というところで、平成２９年の６月現在、区内には自立訓練事業所１カ所（機能訓練定員６人、自立訓練定員６人）となっているのですけれど、この自立訓練というのは生活訓練の間違いではないでしょうか。特に区外の人数がどれぐらいになっているのかということを教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ｂ型のほうですが、これは利用者数ということなので、実際、例えば区内の今の就労継続支援Ｂ型が２６０人の定員だったとして、定員以上の利用登録者というのはいますので、残りが全部区外かというと、そうではありません。","voiceIndex":116,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その下の（４）「相談支援」のところなのですけれども、これは先ほどからも出ているように、サービスを受けるときにケアプランをつくるということになると思うのですけれども、ａ「見込量」の表のところで、利用者数というのは、何というのですか、モニタリングで３カ月ごとに計画を見ていくというのがありますよね。そういうのも含めた形でということになりますよね。","respondent":"中山障害者福祉課長、飛田障害者施策推進担当課長","answer":"ショートステイの支給決定のイメージなのですけれども、例えば瑞宝会の利用であれば、月３１日という支給決定をします。ですので、そこのところは実際にはカットをさせていただきまして、今後の書きぶりとしましては、支援対象の把握、意向の確認に努めるとともに、地域移行のための社会資源の連携等、地域での体制整備を進めていきますというようにし。","voiceIndex":118,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"「計画相談支援」のところの実際の数が１,３００人ということなのですけれど、障害者の福祉サービスの利用者は、これを含むということになると思うのですけれど、そうすると、サービス利用者が１,３００人ということで考えていいのか確認をお願いします。","respondent":"中山障害者福祉課長","answer":"地域生活支援事業は必要ないということになっておりますので、障害福祉サービスのご利用者数と考えていただければと考えています。","voiceIndex":121,"id":"exchange-049"}]},{"id":"topic-04","title":"平成３０年度からの国民健康保険広域化の動向等について","agenda":"平成３０年度からの国民健康保険広域化の動向等について","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、国民健康保険運営協議会の委員でもありますので、それは課長から説明を受けたところであります。それが大体９割ぐらいを占めるということでのご答弁もいただいていますけれども、残りの法定外繰り入れというのはどんなものがあるかということと、法定内の繰り入れというのがどういうものがあって、幾らぐらいになるのかということについて教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"法定内繰入金ですが、国からは３分の１という決まった割合がございまして、その内容が法律上、決まっているのが法定内繰入金ですので、そちらにつきましては、法律上、決まっている部分が、法定内繰入金として算定されております。","voiceIndex":128,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"法定内繰り入れの項目についてみたいなものがあるものなのか、その辺のところが。法定内繰り入れの項目と、あと品川区では法定内繰り入れというのが幾らぐらいなのかという点についてもお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"今回、手元に決算資料を持っていませんので、申しわけありません。具体的な金額ですけれども、今、手元にはないのですが、たしか４０億円程度が法定繰り入れ、法定内と外を両方合わせたものでございまして、その中の１５億円程度が法定外繰入金となっております。","voiceIndex":130,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今までが１２万３,０００円ぐらい。それからすると、本当にかなりの値上げになってしまうので、大変だと思うのですけれど、その辺のところでの２３区での方向というのは、まだ決まらないということにはなっていると思うのですけど、わかっている範囲での状況というのをお答えいただける範囲でお願いできたらと思います。","respondent":"三ッ橋国保医療年金課長","answer":"診療報酬の改定などもありますので、そのあたりが非常に難しい、読み切れない部分がありますので、なかなかはっきりと、この場では申し上げることができない状況ですが、試算として、東京都からの試算が出たということは事実ですので、１６万円ということは事実としています。","voiceIndex":132,"id":"exchange-052"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第１層協議体という、支え愛活動推進委員会のメンバーと、大体１年間に１回ぐらいということなのですけれど、その辺のところの活動の中身というのを改めて教えていただきたいのと、第２層協議体も支え愛活動会議となっているのですけれども、そこのメンバーについて、裏面に記載のある支え愛ひろばや支え愛サロン、主催のところにメンバーの方々が入っていますけれど、そういう方になるのか。","respondent":"大串福祉計画課長","answer":"こういった、通常、第２層協議体にも参加していただいている顔ぶれといいますか、そういった皆様方に来ていただいて、また先ほど申し上げました第１層協議体の統括支援コーディネーターという者が１名おりますので、そちらを中心にしながら、各地区での活動状況の報告。","voiceIndex":138,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あと、生活支援コーディネーターの役割ということになると、まずそこの担当する地域がどんな特徴があり、どんな課題があり、その課題をどういうふうにして、ある力を出してもらうかみたいな方針というのですか、そういうのもつくりながらやっていくということになるのか。その辺の取り組みあたりもお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"なかなか確保するのは難しいです。空き家の活用というお話も出てまいりました。それも１つのアイデアかとは思いますが、空き家につきましても、いろいろな課題等々あろうかと思います。居場所につきましては、引き続き検討していければと考えています。","voiceIndex":140,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは私も行かせていただいて、第１層ということで、堀田会長に来ていただいたのがありましたけど、あのときは、第１層の方で、本当にもう、ふだんやっていらっしゃる、町会長、民生委員の方が多かったので、たしかすごい数字が出たというのは記憶があるのです。そこが何か一体になっている日があれば、そこがこういう場なのかという感じもするのですけど、その辺はどう考えたらいいのかという点。","respondent":"大串福祉計画課長","answer":"来年予定している第１層協議体、支え愛活動推進委員会。活動の中身と報告の中身といったところで、こちらに掲げさせていただいています。２つの地域で行った取り組み。これについては、報告させていただければと考えております。","voiceIndex":143,"id":"exchange-055","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、いろんな面で広げていっていただきたいと思うと同時に、どうしても同じ方がメインになってしまう。それが一番、負担にならないように、町会長や民生委員というのは必ず、これもあの方、あれもあの方というのがあるので、それも我々も気をつけないといけないのだけど、やはりそういう方をどんどん増やしていってもらいたいと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-056","title":"町会・自治会支援"},{"speaker":"大倉委員","kind":"質問・要望","question":"最初の何かきっかけというのは当然、行政のほうでやっていく。今、先ほどもお話がありましたけれど、投げかけたら、積極的にやっていこうというお答えをいただいたところもあるというお話もありましたけど、最初はそれでやっていくしかないのかというところもあるのですが、今後の方法について、どうやっていくのかというのを教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"私ども、出席させていただいて、いろいろご説明しています。まだまだ、とば口かとは思っております。ただ、やはり中には、うん、そうだよねと言っていただける方も多数いらっしゃいます。","voiceIndex":147,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"本当に大変だと思うので、ぜひ頑張っていただければと思います。１点、裏面の支え愛活動の、これは、第１層と第２層が、大井第二や荏原第二などで行われているということでいいのでしたか。","respondent":"大串福祉計画課長","answer":"第２層と言っているものが、各地域、各地区での活動です。それで、第１層は区全体という形になります。その区分けになりますので、大崎第一などで行われているものが、第２層の協議体の活動という形になります。","voiceIndex":149,"id":"exchange-058"},{"speaker":"大倉委員","kind":"質問","question":"これは毎年、どこかに書いてあったかもしれないですけれど、１回、必ずやっていくのかというところと、これは増やしていくとか、そういう考え方があるのかと、あと、その地域で、今、助け合い体験ゲームやグループワークなどというのがやられている中で、これはどういうふうに開催していくのか。それが、今、３地区で、これは１３地域できるのかなどという、その辺の見通しや考え方について教えてください。","respondent":"大串福祉計画課長","answer":"やはり先ほどのお話に戻りますが、当事者意識といいますか、みずからの発案といいますか、そういったところで自発的にやっていただけるというのが一番大きなポイントかと考えていますので、大崎第一については、今回。","voiceIndex":151,"id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"統括もいらっしゃいますが。せっかくの所管事務調査なので、その辺の、ふだんなかなか、お話を伺うということはあるのですけれども、動きとして果たしてどういうふうなことをされているのかということ、この機会に全体として何か特徴的なことなどがあれば、ぜひ教えていただきたいと。","respondent":"大串福祉計画課長","answer":"コーディネーターの１日の業務の流れというようなことになるのかもしれないのですけれども、基本的に相談窓口ということで、地域センターのカウンターに窓口を設けしています。そこに相談者が来れば、その対応をするといったところ。","voiceIndex":154,"id":"exchange-060"},{"speaker":"若林委員","kind":"質問","question":"一方で、いわゆる総合事業の中での生活支援体制ということで、いわゆる包括ケア、また地域福祉という観点から見ると、そういう目の前にある地域、また高齢者、今後はまた障害のある方や生活困窮者などということも視野に入れつつ、そういう目の前にあるニーズ、対応が必要な方への対応ということで、今はそれが主な業務になっているとは思うのですが、一方で、やはり地域福祉、地域づくりですか。","respondent":"大串福祉計画課長","answer":"委員にご指摘いただいたとおりです。やはりコーディネーターを２人、配置していますけど、なかなかその地域を知るというのは難しいところかと思うのです。その辺で、先ほど申し上げましたように、地域のイベント行事といったものにも足しげく通ってほしい、顔を出してほしい。","voiceIndex":156,"id":"exchange-061"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、今の支え愛・ほっとステーションをどのようにさらに知っていただいて、広げていくかというところでは、ボランティアというのが、すごく１３地区それぞれで、まちまちなニーズを担っていただける方がなかなかいない地域もあるというところで、先ほどの第２層協議体のところでおっしゃられた人数は、あくまで会議体の人数であって、ここにはボランティアは入っていないということですか。","respondent":"大串福祉計画課長","answer":"支え合いというところでいけば、今日は支えられる側であった方が、明日は支える側になる。あるいはまたその逆もあるといった、役割分担といいますか、そういったものができれば一番理想的だと考えています。ただ、なかなか、やってもらう方は、やはり継続的にやってもらいたい。","voiceIndex":159,"id":"exchange-062"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういうコーディネートするのがコーディネーターなわけですけれど、この資料で、生活支援コーディネーターは２人常駐している。それで、統括のコーディネーターは１３地区で１人ということで、これも社会福祉協議会の方にお願いしているということだったのですが、この方は、１３地区に常駐している２人の社会福祉協議会の職員とはまた違って、もう一人、リーダー的な人がいるということですか。","respondent":"大串福祉計画課長","answer":"時には、ある地区でボランティアとのコーディネートがうまくいかないといったときには、その人が行って再度調整を行うとか、昨日、私も参加させていただいた支え愛活動会議には、２人のコーディネーター、その地区のコーディネーターと、プラス。","voiceIndex":161,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":83182,"voices":171}},{"id":"h29-20171129-8","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"建設委員会","time":"午前１０時０８分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"京浜急行本線連続立体交差化計画及び関連する道路計画の都市計画案等の説明会の開催","agenda":"京浜急行本線連続立体交差化計画及び関連する道路計画の都市計画案等の説明会の開催","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"高架化について伺いたいのですけれども、高架化は、今回、線路の真上でなく、東側に振れているので、立ち退きが発生すると思うのですけれども、高架化での立ち退きの件数を教えていただきたいのですが、建物棟数、世帯数、人数もわかれば教えてください。そうした方々への説明や意見は聞いているのか、どんな反応があると聞いているのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"高架化におけます立ち退き件数、事業にご協力いただく方の件数につきましては、今後、測量等を実施いたしまして、東京都のほうで確定をしていくものです。現在、つかんでいる情報は、区のほうでは持ち合わせてございません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、線路の真上での高架化計画にならなかった理由は何なのかということを伺いたいのですけれども、なぜ真上でできないのか、また、立体化担当課長ということで、ほかの高架化の事例もよく研究されているのではないかと思うのですけれども、ほかの事例でルート変更なしで立ち退きがなくて高架化している事例はあると思うのですけれども、幾つかわかれば紹介していただけないでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"説明会がここに記載してありますとおり、１２月に予定してございまして、その後、東京都のほうできちんとした調査を行いまして、権利者の確定をするというふうに聞いてあります。それから、直上で高架化ができない理由といたしましては、ちょうど八ツ山の跨線橋があります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"都の事業だということなのですけれども、これ、品川区民の住んでいる方の問題なので、やはり積極的に品川区としてもつかんでもらいたいと思います。今回の右側に振った計画になるにあたって、京急側の要望はあったのでしょうか、なかったのでしょうか。お伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"京急側から直接要望があったというよりは、どういう形での構造が望ましいかという検討の中で高架化になったというようなものです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本の土木技術をもってすれば、ルート変更なしの高架化も可能なのではないかと思うのですけれども、真剣な検討を行って、その結果もきちんと住民に示されなければ、今回の計画案にも単純に万歳と言えないかなと言わなくてはいけないのですけれども、検討と説明を強く都に区から求めてもらいたいのですけれども、立ち退きが伴うということになりますと、やはり住民にとっては大変なことになるので。","respondent":"東野まちづくり立体化担当課長","answer":"まさにその説明会をする場が今回の都市計画案の説明会です。こちらにつきましては、本年１月２７日、２８日におきまして、素案の説明会の中でも東京都が住民に対しての説明をしています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"できるのではないかと思わざるを得ないというか、もっと説明会の場で、そういう場というのであれば、事前に区民の方からこういう声も上がっているので、そこら辺もしっかりと、本当にいろいろな検討したけれどもこうなったということは、説明してもらいたいというか、再検討もするということもやはり要望してもらいたいのですけれども、ぜひそれをお願いしたいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"ご説明とこの文書で距離とかはわかるのですけれども、今回の説明会で、イメージを使った説明とかはなされるのでしょうか。というのは、やはりこういう文書だけとか、口頭の説明だけでは理解がちょっとしにくいので、何かイメージ図とかを提示していただけると非常にわかりやすいのですけれども、その点、今回の説明会はどうなっているのかおわかりでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましても、区民の皆さんがわかりやすい説明がなされるという予定です。まだでき上がっていないのですけれども、パンフレット等も当日配布する予定がありますので、そちらをあわせて説明を行う予定と聞いております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"正確な測量についてはこれからにせよ、この図を見ると、ある程度、線が引っ張ってあるわけですから。知るべきだろうと。そういった場合に、いや、知りませんという答弁は、ちょっとそれはあまりにも区民の皆さんに対してはどうなのだろうと非常に疑問があったのですけれども、東京都と品川区の立場、情報の共有化については、どう考えられて、どういう現状になっているのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"今回、事業主体は東京都ですけれども、こちらは連名になっていますとおり、品川区、港区、京急電鉄が事業者という形です。東京都との情報につきましては、一定程度の情報共有をした上で説明会を行うという立場です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"この図を見ますと、明らかにかぶっているのです。当然、ここは該当だろうなということはわかるわけです。わかるのです、きっちりと測量した上で、Ａさんについてはこれだけかかります、お願いしなければいけませんというのはわかります。そういう話はまだしていないということでいいのですか。もうしているということでいいのですか。","respondent":"東野まちづくり立体化担当課長","answer":"そういう中ですので、今回、説明会等で具体的にそういうご質問があれば、東京都のほうからお答えするような形になろうかと思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区の立場としては、やはり東京都が主体になっていますので、東京都の答えるべきものだというのは理解できます。なので、東京都のほうにかなりきつく言っていかないと、それと、手順です。そこら辺を東京都がやるにしても、品川区に責任もあるので、しっかりやっていただきたいと考えていますので、区の考え方もお知らせください。その方々とのやりとりはどこまでいっているのですか。","respondent":"東野まちづくり立体化担当課長","answer":"東京都への要望という形につきましては、委員会での要望があったということも踏まえまして、東京都のほうに報告をさせていただきたいと思います。駅前広場の進め方なのですけれども、こちらにつきましては、東京都の説明会と同じ手順で都市計画手続を現在進めているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"まとめますが、駅前広場については丁寧に進めていただきたい。住んでいる人たちをないがしろにしているとは思わないですけれども、でも、説明だけでいいやとかではなくて、一緒にやっていこうというところまで持っていかないと、やはりせっかくの広場ですから、皆さんの意見が詰まった広場にこれからなるのでしょうから、期待を込めて丁寧な進め方をお願いしたいと考えています。","respondent":"東野まちづくり立体化担当課長","answer":"今後も意見交換の予定をしておりますので、そういった中で区のほうで丁寧な説明を続けていきたいと考えています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"駅前広場のことについて、もう少し具体的にお伺いしたいと思います。今日、具体的にこのように地域も限定をされて示されているのですけれども、これまで今日示していただくまでの流れを少し教えていただきたいと思います。地域の方へどれぐらい、どのような形で説明をされて、意見交換をされてきたのか。それと、地域の方のお声は、どんな声があるのかということを教えていただきたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"これまでのこの区域をつくる考え方の変遷といいますか流れなのですけれども、１月に行った素案説明会の時点では、まだ区画といいますか、この範囲が決まっているものではございませんでした。","voiceIndex":24,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域のさまざまなお声があると思います。最後に１点ですけれども、この今示されているものが、ほぼ計画として進んでいくということでよろしいのでしょうか。それと、ここのこの形に決められたのはどうしてか。もうちょっと狭くならなかったのかとか、ここまでこうやって広くされている、もう一度そこの意義といいますか、それを教えていただきたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"図を見ていただければわかるとおり、東側だけでなく、西側にも乗降の状態を考えまして、たまり場等も考えた上での形となっているものです。この計画につきましては、今後、この形で都市計画手続を進めたいというふうに考えてあります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"広場について伺いたいのですが、交通広場と言っていたのですけれども、区画街路第７号線といつの間にか道路計画になっているのはなぜなのか。地名で言うと、この道路はどこなのかということをお伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"区画街路第７号線は、この駅前広場をつくる目的といたしまして、道路の名称です。この駅の南側、ちょうど区画外、図の一番南側のところ、直線になっていると思うのですけれども、こちらは１２ｍの道路がすりつくような形になります。","voiceIndex":28,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ道路の名称になるのか全然わからないのですけれども、しかも、１２ｍと言いましたけれども、これは相互通行ですか。最初は１０ｍという話も出たという話も聞いているのですけれども、そこら辺、もう少し詳しく教えていただきたいというのが１点。道路をつくる理由です。ここになぜ道路をつくるのか教えてください。","respondent":"東野まちづくり立体化担当課長","answer":"なぜ道路をつくるかという部分なのですけれども、駅前広場としての交通結節機能を十分に担保するため、それから、図を見ていただくとわかりますとおり、国道側から旧東海道側までの区画のところをタクシーや障害者用の車、一般車も含めて。","voiceIndex":30,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"そもそも広場なのですけれども、結節点とかタクシーとかありますけれども、先ほども課長も説明していましたが、９０％の方が北品川駅へ歩いてくるということで、タクシーは、地元の人も何度も言っていますけれども、タクシーでわざわざ北品川駅まで来て、そこから乗って品川駅に行く人はいなくて、各駅ということもあって、しかも品川駅からものすごく近いですから、ここにわざわざタクシーで来る人はいない。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは、９０％以上の方が徒歩で今現在使われているという状況は、必ずしも駅前の交通区間を担保するものとして適切なものとして考えてはいないものでございまして、将来的に高齢者、それから障害者の方が利用できるような安全なタクシー、障害者用の乗降場。","voiceIndex":32,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一度しっかりお答えいただきたいと思います。駅は駅としての機能で、広場についての発言に対しての答えだったのです。それで必ずしも必要ないと言っているのだから、これは引っ込めなくてはいけないのではないかと思うのです。そこら辺はどうなっているのですか。区の意思疎通といいますか、縦割りなのですか、そこら辺をもう一度お伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"その町会での勉強会につきましても、私どもの考え方について示させていただいて、意見交換をさせていただいているところです。今後も意見交換の場をつくっていきたいと考えています。","voiceIndex":34,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちゃんとあの区長の発言は何だったのかということを直接説明していただきたいというのが１つです。その２点をお伺いします。","respondent":"東野まちづくり立体化担当課長、藤田都市環境部長","answer":"そういったものを考えますと、ここへ相互通行の道路をつくることによりまして、その６００台分がこちらのほうへ流れていくという可能性もありますので、そういったことで旧東海道からの通過交通を一部ですけれども。基本的には、今、担当課長が先ほど来ご説明させていただいているとおりですけれども、それにもし加えるとするならば、区長の発言の中でも、先ほどのお話もされていましたとおり。","voiceIndex":36,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"確かに旧東海道に流入しますが、現行では、さらに南のほうに旧東海道を行って２００ｍ先には、すぐ一国へ抜ける道路があるので、その２００ｍほどの流入交通の解消のために、こういう道路を広げて立ち退きを出すというのは、私は政策として間違っているのではないかと、それは理由にならないのではないかと思うのですけれども、この交通流入というのは。","respondent":"東野まちづくり立体化担当課長","answer":"区の方針につきましては、今回、都市計画案として提出するこの方針を進めていきたいというところでございまして、地元の方にも丁寧な説明を今後も続けていきたいというふうに考えてあります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"課長もご存知だと思うのですけれども、その先にあるのはオフィスや復元された土蔵相模や品川浦など、再開発協議会が進めている開発計画地域なのです。結局は、この区画街路第７号線は、新たな新設道路でのさらなる立ち退きを呼び込むことになるし、また、再開発地域に一国から直接行ける再開発のグレードアップの道路になると思うのですけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、八ツ山通りまで抜ける道路につきましては、現在の道路形状を考えると、交差点も近いところから、抜くことができないということで、そういった警察との協議もしているところで、旧東海道のところでとめているような状況です。","voiceIndex":41,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"新設道路の要望はもらっているということですけれども、伺いたいのは、今回の道路をつくると、将来的には再開発にプラスになるでしょう。再開発協議組合が描いている絵にとって、非常にグレードアップになるし、プラスになるのではないですかということを伺ったので、お答えください。","respondent":"東野まちづくり立体化担当課長","answer":"再開発協議会が立ち上がって、現在、その再開発のコンセプトづくり等をしています。こちらにつきましては、この道路があるなしにかかわらず、地域の再開発をどう考えていくかというところを現状進めているところですので、そういうご理解をいただきたいと思います。","voiceIndex":43,"id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"それはなかなかそういうふうに言うのでしょうけれども、私はこれは再開発のさらに布石になる道路だというふうに認識を持たざるを得ません。過去の例を見ると、説明会、意見書、いくら意見を出しても、微塵も変わらない案が都市計画審議会へ出されて、都市計画審議会の中では、区の元まちづくり部長などが、学識経験者と称して２名入っていて、そうした多数で……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"だから、私が伺いたいのは、今回の国交省の都市計画法運用指針、公聴会を開かなくてはいけないのではないですかということが言いたいのです。運用指針では、第１項の公聴会について、都市計画の案が作成された後の手続としての意見書縦覧とは別に、都市計画の案の作成の段階でも、住民の意見をできるだけ反映させようという趣旨であるというふうに公聴会のことを言っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"今回のように、住民がまさに居住権や財産権にかかわる問題で、都市計画素案から、１月にやりました。案に至るまでの間に公聴会を開かないのは、これは問題なのではないですか。まさに必要があると認めるべき案件であって、公聴会を行うべきではないでしょうか。少なくとも公聴会を開いてから案を作成すべきだと思いますけれども、私は国交省のこの指針違反だと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、駅前広場計画につきましても、連続立体交差事業につきましても、２回ほど素案説明会、それから、今度行う都市計画案の説明会ということで、住民に対して２回の説明を行います。","voiceIndex":48,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"公聴会を開くつもりはないという、その品川区の対応は、私は国交省の指針違反なのではないですかと聞きましたので、しっかりとお答えください。先ほど、２回の説明をやると言いますけれども、素案の説明会１回、案の説明会１回、国が言っているのは、案を作成する段階で公聴会を開くべきだと言っているので、それは今のはお答えになっていません。しっかりとお答えください。違反なのではないですか。","respondent":"東野まちづくり立体化担当課長","answer":"都市計画法で定められている公聴会等という形での文書があります。この公聴会等の中には、こういう説明会も含まれているというふうに解釈しています。違反とは考えてございません。","voiceIndex":51,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"ところが、今回は、案を作成する段階で地権者の方々にも説明がない。私は、再開発の場合でも、地権者だけに説明すればいいとは思っていませんが、この都市計画案については、地権者にすら説明しないというのは、これは明らかに違反なのではないですかと思うのですけれども、いや、これまで区がやってきた対応とも矛盾するのではないですか。少なくともこれはやるべきでしょう。いかがですか。","respondent":"東野まちづくり立体化担当課長","answer":"冒頭の説明でも申し上げました今度行われる説明会につきましては、地権者の方にもご案内をする予定です。こういった公の説明の場で、都市計画案について、駅前広場については説明をしていくという予定です。","voiceIndex":53,"id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"それは絶対にそうした対応は改めるべきだと思います。強く意見を言っておきたいと思います。何かご意見がありましたら言ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"連続立体化というと思い出すのが目黒線ということで、武蔵小山、西小山、不動前ということで、こちらの場合、地下化ですけれども、非常にまちのポテンシャルが上がってきたのは、これはもう間違いない。ちなみに、ここのまちづくりと、将来行われる、３０年ぐらいでしょうか、リニアとの関連性についてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"リニア中央新幹線につきましては、品川駅の地下に駅が新設される予定です。こちらは、リニア中央新幹線から、また品川駅としまして、北品川の駅の方にも新たに来街者が訪れることが予測されます。","voiceIndex":59,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"今回、それから約１１カ月、説明会が行われるということですけれども、１月の素案の説明会を踏まえての今度の説明会、東京都が主体となるということですけれども、それを踏まえた場合、どのような考えというか、どのような意のもとに今回の説明会を行うおつもりでしょうか。そこのところの意気込みといいますか、臨む姿勢についてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"素案説明会、それから都市計画案の説明会につきましては、都市計画手続の中で進められているものです。素案説明会のときに、まだ未定だった部分、そういったものを今回の都市計画案説明会では、改めまして、住民の皆様に説明をするものです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"間違いなくまちの活性化と土地に対する可能性が無限に広がってくるわけですし、５０年後、将来の北品川、新馬場の駅周辺を考えた場合に、これは避けて通れない問題をまずクリアしていく、そのためにも住民の方の理解と協力が必要なわけでありまして、今後、そこのところのしっかりとした説明、昨日の目黒川デッキのところで、ボタンのかけ違いのような感じもしましたけれども、要は、計画案があっても。","respondent":"東野まちづくり立体化担当課長","answer":"説明会は、都市計画案という形での説明会になってあります。その後、意見書等で住民の方からも意見をいただきます。","voiceIndex":63,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"まちの活性化においては、鉄道、これは３カ所の踏切が除却されるということですから、非常にここの部分についてはまちの活性化、将来の駅周辺にとっては大きなプラスになるわけですので、しっかりとしたまちづくりをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-030"},{"speaker":"いながわ副委員長","kind":"質問","question":"そもそも今回の立体交差化というのは、東京都はよく開かずの踏切とか、そういうものをなるべく解消しようという動きの中でいろいろ事業に取り組んでいる、その一環でここがあって、逆に言えば、品川区というより、むしろ東京都と京急の間で、ここが京急が高架化なり踏切がなくなれば、おそらく大鳥居というか、あちらのほうも全部高架になっていますので、京急としては非常に安全な運行もできるし。","respondent":"東野まちづくり立体化担当課長","answer":"この京急線のこの区間の立体交差事業につきましては、東京都の踏切対策基本方針で開かずの踏切の解消でありますとか、ボトルネック踏切の解消でありますとか、その中に位置づけられているものを事業化していくものです。","voiceIndex":66,"id":"exchange-031"},{"speaker":"いながわ副委員長","kind":"質問","question":"これが立体交差は実現に向かって動き始めたとして、品川区がそこで京急なり東京都に言うべきことは、駅舎の様相をどうするかとか、いろいろな案、先ほど、地域のにぎわいということを触れていたので、その観点で言うと、やはりこの旧東海道の最初の宿がある品川宿ですから、やはりそれなりに、例えば、戸越銀座というのは昔ながらの様相に変わって、地域もすごく盛り上がっているという部分もあるので。","respondent":"東野まちづくり立体化担当課長","answer":"地元のまちづくり協議会などからも、そういった要望もありますので、その声を事業主体、東京都、京急のほうには、区としては伝えていきたいと考えています。","voiceIndex":68,"id":"exchange-032"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"ぜひそれは地域の声も聞きながら、前に進めていただきたいと思います。最後に、本当に初歩的なことなのですが、品川区画街路等７号ということは、７本目という、そういうイメージなのか。いろいろ調べると、区画街路で出ているのですけれども、イメージが沸かないので、例えば、品川区でほかにどういうところがありますか。","respondent":"東野まちづくり立体化担当課長","answer":"区決定の道路という形になりまして、区画街路という名前では、私のほうでは記憶がないところなのですけれども……。","voiceIndex":70,"id":"exchange-033"}]},{"id":"topic-02","title":"防災行政無線設備更新工事","agenda":"防災行政無線設備更新工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"更新の順番の考え方を１点お伺いします。更新で何が変わるのかというか、例えば、ちょっと聞こえづらいという問題もあちこちから出ていたと思うのですけれども、そういった不具合などは解決になるのかをお伺いします。","respondent":"古巻防災課長","answer":"何が変わるのかですけれども、設備的には、アナログの設備からデジタル化をするということで、聞こえづらさということがデジタル化によって解消するわけではないのですけれども、スピーカーの設備を物理的に変えるということと、あと、向きとか。","voiceIndex":79,"id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"やはり更新でさらに聞こえやすくなるというのが一番大事な点だと思いますので、ふだんからいろいろ情報を収集しているとは思うのですけれども、ぜひ更新にあたっては、そういった向きなども、地域の町会ですとか、そういった方々のお声も極力聞きながら、実態をつかみながら改善につなげていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"平成３１年度から戸別のところが３０局、１５０局と入っておりますけれども、この戸別の設置の仕方と、どういうところにつけるのか教えていただきたいのと、あと、現在使われております防災ラジオが使えなくなるというようなことも聞いておりますが、この防災ラジオの考え方を少し教えていただきたいと思います。","respondent":"古巻防災課長","answer":"ですから、防災ラジオの代替で防災行政無線を補完する何か仕組みをということにつきましては、デジタル化が完了するまでに検討を進めまして、どういった形が望ましいのか、今の防災ラジオがなるべく使えるようにするのが一番望ましいとは思うのですけれども。","voiceIndex":82,"id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、戸別のところ、確認させていただきました。私立保育園も入っているということですので、これは私立保育園は毎年拡大をしていただいておりますので、新設でできるところは、そのときにつけていただけるということでいいのでしょうか。これが１点。私のうちもつけていますが、品川区内の情報が発信されてくるわけで、持っている方はかなりまだ多くいらっしゃると思うのです。","respondent":"古巻防災課長","answer":"防災ラジオにつきましては、こちらは防災課としても課題だと認識をしておりますので、現在、ご活用いただいている方もたくさんいらっしゃると思いますので、そういった方々に不便にならないといいますか。","voiceIndex":84,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"約５,０００個ということなので、先ほどからのご答弁で、なるべく使えるようにという、技術的な件があると思うのですが、デジタル化になることと全然違うと思うのです。予算を立てていかないと、５,０００個ですから、たしか５,０００円かそのくらいしていたような気がするのですけれども、議員は全員買ったと思うのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうことも含めて、割引にするのか、それによって経費も対応していかなければいけないと思うのですが、それもあわせて今後検討していただきたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"あっ旋等を含めまして、どういった形でやるのかはこれからの検討になりますので、今いただいたご意見も参考にさせていただきながら、今後、十分検討していきたいと思います。","voiceIndex":89,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"先ほどご答弁に、デジタル化によって聞こえやすくなるとは限らないというような旨のご発言がありましたけれども、今回の更新によって、音は聞こえよくはならないのですか。","respondent":"古巻防災課長","answer":"できるだけ聞こえやすくするという意味で言うと、機器化ですとか、そういったところ、取りつけの位置ですとか方向、そういったものを細かく調整することで、できるだけ聞こえやすくということは努めてまいりたいと考えております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"音量の問題とかもあると思うのですけれども、やはり満遍なく幅広く聞こえさせるためには、具体的にどういったことが必要なのでしょうか。１カ所のスピーカーの数を増やすとか、そういったことも必要なのでしょうか。具体的にどうやって今後対応していくのかお知らせください。","respondent":"古巻防災課長","answer":"それはスピーカー自体の機器につきまして、例えばあまり広がりがあるものよりも、逆に指向性の高いもののほうが音響が反響しなくて聞こえやすいという場合もあると思いますし、そのあたりは、周辺の状況を踏まえながら、設置する機器でありますとか。","voiceIndex":93,"id":"exchange-041"},{"speaker":"いながわ副委員長","kind":"質問","question":"いろいろ同じような質問で申し訳ないのですけれども、私も地域からいろいろ声を聞いていますので、代弁するとなれば、要は、ほかの委員からもありましたように、やはり聞こえづらいと言うのです。１５２局つけているわけですから、要するに、同じ方向に向いて一斉にしゃべったら、真ん中にいる人は何を言っているのか全くわからなくなってしまうのですね。","respondent":"古巻防災課長","answer":"は音響として聞こえやすいようにということは心がけて努めていきたいと考えております。","voiceIndex":95,"id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"そこで、音ですから、耳の不自由な方、あるいは、今、外国の方も増えていらっしゃる。この方に対してどのように対応されていくのか教えてください。","respondent":"古巻防災課長","answer":"現状の仕組みで言えば、メールを使って周知をしたりとか、ホームページ等で周知をしたりとかと代替手段が幾つか考えられると思いますので、具体的に今これということで仕組みの導入を考えているものはないのですけれども、そういった方々への配慮についても、今後。","voiceIndex":99,"id":"exchange-043"}]},{"id":"topic-03","title":"品川区地域防災計画の素案","agenda":"品川区地域防災計画の素案","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"避難所の動物の問題ですとか、受援計画ですとか、これまで入っていなかったところを一定修正したというのは、それはいいと思うのですけれども、全体としてどうなのかと思う部分があるので、それはあとでやるのですけれども、まず細かい確認なのですが、避難所のところで大事だと思って何度か提案させていただいていたのは、段ボールベッドに対して、それはどこら辺に入っているのか教えていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、全体の問題としまして、私たちが何度も指摘しているのですけれども、やはり予防対策はすごく大事だということと、そういった点では、構成上変えたという話もありましたが、まず被害を出さないところに全力を尽くすという点では、まだまだ弱いのかということを１つ指摘をさせていただきたいのと、もう１つは、総－１６ページ、最初のほうの基本理念なのですけれども、これはちょっと疑問があって。","respondent":"古巻防災課長","answer":"そうした自助、共助、公助がきちんと連携をして災害に対応していく、これによって防災対策がきちんと、防災力の高度化、まさに地域防災計画の冒頭にも書かせていただいきましたけれども、防災力の高度化が図られるというような考え方に基づいてつくらせていただいておりますので。","voiceIndex":109,"id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"羽田のことはこれ以上やりませんけれども、ちょっと納得がいかないというか、やはり新ルートが予定されているから、それを見越してこれが入ったということをまず思うのですけれども、なぜ認めないのかというか、別にそこを認めたからといって、区がそのルートを推進しているというふうにはならないと思うのですけれども、なぜそれをかたくなに認めようとしないのかというのが逆にわからないと思ったので……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"何かあったら言ってください。どうぞ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"条例に書いてあると言われれば、それまでかもしれないのですけれども、私が聞いたのは、自助、まず第１に自己責任としての自助、第２に共助、最後に公助の役割を果たすと書いているのですけれども、伺ったのは、まず個人や地域社会に対応してもらう。それで解決できない問題について区が対応するというのが公助と言っているのですかと伺ったので、もう１回しっかりと考えを聞かせていただきたいと思います。","respondent":"古巻防災課長","answer":"これがあってからその次に共助ができるというようなことは、もう既にご存知のとおりだと思いますけれども、そういった中で、区が果たす役割は、条例にも書かれておりますけれども、こういった自助、共助、支援をしていくということは当然ありますし、また。","voiceIndex":113,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"中身についてもう少しお伺いしたいのですけれども、震災、震－１－８ですか、減災目標について書いているのですが、閣議決定された中央防災会議の首都直下地震緊急対策推進計画には、「耐震化率１００％で全壊棟数と死者数は約９割減らせる」、「感震ブレーカーなど出火防止と初期消火成功率の向上等で焼失棟数は９割以上減できる」とあるのですけれども、減災目標がなぜこんなに低いのかということが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"実質使えないのです。そうなったら、地域の避難所に来ざるを得ないわけです。だから、私は、なぜ超高層イコール、再開発イコール防災機能の促進になるのか。なぜそう言うのか、ここはお伺いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"やらないとおっしゃるのでしょうけれども、なぜやらないのでしょうか。景観計画ではやりました。財産にかかわることだからやったのかもしれませんけれども、それ以上に私たちの命と財産にかかわる計画ですから、ぜひ説明会、パブコメをやるのであれば、同時にこの計画についてしっかり対面で住民と話し合う、この計画の内容を説明する説明会をやるべきだと思うのですけれども、いかがでしょうか。","respondent":"古巻防災課長","answer":"当然、お問い合わせいただければ、丁寧に内容についてお問い合わせにお答えしていくという姿勢はありますけれども、説明会を開いてということで、今のところ予定をしているものではございません。","voiceIndex":120,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"一方では、この計画では自助、共助を住民の皆さんに求めているわけです。それでありながら説明しないというのはちょっと矛盾しているのではないかという点もありますし、なぜやれないのか、やる意思がないのか、説明したくないということなのでしょうか。私は説明会をやらないというのは、積極的な説明をしたくないとしか思えないのですけれども、そこら辺は、やらない理由をお伺いします。","respondent":"古巻防災課長","answer":"今までの延長線上でさらに対策を進めていくですので、そういう中で今後も含めまして、丁寧に啓発を進めていくですので、防災計画自体についての説明会は、今のところ必要はないと考えているものです。","voiceIndex":122,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"防災会議と言っても一部の方です。もちろん代表ではありますけれども、やはりこの計画は、本当に全区民の命と財産にかかわってくるものですから、私は積極的に説明をするということは必要だと思うのです。一方では、景観計画ではやったけれども、防災計画ではやらないということは、それは防災課といいますか、部の考えということなのでしょうか。どちらなのでしょうか。それだけ伺いたいと思います。","respondent":"古巻防災課長","answer":"一般的なお答えになるかと思いますけれども、特にパブリックコメントと説明会をセットでやる仕組みがあるわけではありませんので、状況に応じて説明会をする場合もあるし、地域防災計画については。","voiceIndex":124,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"防災ラジオについてのことなのですけれども、先ほど、防災行政無線設備更新工事についてのところでもお話があった点ですけれども、震－５－８で、防災行政無線を補完する情報伝達手段の確保というところで、(1)として、一番最初に「防災ラジオ」の配備と書いてあるのですけれども、先ほどのご答弁によると、防災ラジオが今後使えなくなる可能性が高いというご答弁もあったのですけれども、そうした場合。","respondent":"古巻防災課長","answer":"そのほかの情報伝達手段につきましても、さまざまな通信体制で補完をしていくということではありますけれども、あくまでも現行でですので、また今後、時点修正等もかけていきますので、場合によって、そのときの状況に応じた記載に改めていくというような形になります。","voiceIndex":126,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点ほどお伺いいたします。その中で１つ、備蓄のことです。ゆくゆく、多分公表される時期あたりが変わってくる時期なのかと思うのですけれども、東芝病院についての考え方と、また、品川区としても、議会としても、存続の要望をしっかりしておりますので、引き続き、こういう体制の協力をいただけるように、区からもぜひお願いをしていただきたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"備蓄の件ですけれども、地域防災計画ということで、一般的な用語として使わせていただいておりますが、今後、周知していく中で、委員ご指摘の用語、「ローリングストック」でありますとか「循環備蓄」。","voiceIndex":128,"id":"exchange-055"},{"speaker":"横山委員","kind":"確認","question":"ちょっとわからないところがありましたので確認の意味でお聞きしたいのですけれども、７番の女性の力を生かした対策を追加するというところなのですが、震－７－３９のところなのですけれども、「パトロールの実施や照明の配置による視認性の向上」とあるのですけれども、こちらは具体的にどういう意見が反映されて、どういった環境を整えるといいというようなことになるのでしょうか。","respondent":"古巻防災課長","answer":"今までも同様の記載事項がないわけではなかったのですけれども、男女共同参画の推進会議のメンバー等をヒアリングした中で、避難所の環境を整えていくということの重要性については、さまざまなご意見をいただきましたので、その中から男女共同参画といいますか。","voiceIndex":130,"id":"exchange-056"},{"speaker":"横山委員","kind":"質問","question":"そうしますと、例えばいろいろな方のパトロールを実施をして、防犯の見守りというか、そういった形ですとか、あとは、暗い場所だったり、誰も人気がないような場所をなるべくつくらないようにしていくという、そういう意味でよろしいのですか。女性だったり男女共同参画の視点から、そういった意見があって反映されてきたということで理解はよろしいのでしょうか。","respondent":"古巻防災課長","answer":"今まさに委員からお話がありましたとおりで、ただでさえストレスのかかる避難所生活でありますので、なるべくそういったストレスが少ない状況で生活ができるような環境を整えていくということで、男女共同参画というだけではありませんけれども。","voiceIndex":132,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"全体的な防災計画の冊子、これは多分、この厚さになるのだろうなと思って、今までは資料編というものもあったと思います。それの資料編も新しくなるのでしょうか。この文中に資料編○○参考とか、避難所一覧なども資料○○とかと書いてあるのです。なので、別途何かあるのかというふうに想像するのですが。それの位置づけです。これとの位置づけがよくわからない。そこら辺をまずお願いしたいです。","respondent":"古巻防災課長","answer":"用語については、一応、定義を各部ごとに書かせていただいておりますけれども、インデックス（索引）についても、当然、今の防災計画にもありますので、それは最終的にはきちんと整理をしていきたいと考えております。","voiceIndex":134,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"避難所の数であったり、区民の人口推移であったりという、細かいところですが、これからどんどん変わってくる部分があると思うのですけれども、それは大きく変わらなくても、変更点とかというのは、随時やっていくという認識でいいのですか。このマニュアルの防災計画の見直しは、何年ごとにとか、そういう大枠があるのでしょうか。","respondent":"古巻防災課長","answer":"数字的な部分で、当然、人口でありますとか、そういったところは刻々変化をしていくものでありますので、なるべく変化の大きいものについては、資料編のほうで記載をいたしまして、そこを差し替えていくような形で変更を加えていくというような形で考えております。","voiceIndex":136,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"そのほかに避難所の運営も町会・自治会の方々が該当になると思うのです。そうなってくると、実際、現場の一時避難所、例えば、震－７－８を見ていただくと、避難施設という中に、一時、広域、区民避難所とあります。これはわかります。そこら辺はまた運用の部分で今後検討していただきたいと考えていますので、これは要望として言っておきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問","question":"いろいろ説明ありがとうあります。それに全部周知して、みんなが同じ考えの中で最低限備蓄するということが一番美しいのですが、本当に周知ができるものなのですか。","respondent":"古巻防災課長","answer":"備蓄の考え方ですけれども、「不足する」というような書き方に関しましては、実際的に届かないということが可能性としてあるというようなことも考慮した上で、ご自身でもきちんと備蓄をしていただきたいということを、これは今までも備蓄について。","voiceIndex":139,"id":"exchange-061"},{"speaker":"いながわ副委員長","kind":"質問","question":"これをしっかり明記していただいて、各家庭でしっかり備蓄をしてくださいということは、重々私も理解できるのですけれども、例えば、一家、家族４人で、備蓄の量はどれぐらいになるのですかと、イメージがおそらく家庭でわからないような気がするのです。だから、そういうところで一人でも多くの目に触れるところに、そういった取組みをしていってもらいたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-062"}]},{"id":"topic-04","title":"本日は、防災対策に関することのうち、都市型災害","agenda":"本日は、防災対策に関することのうち、都市型災害","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ホースをつなげても届かないような地域というふうに聞いていますけれども、その活動困難地域が区内には今どれぐらいあって、その活動困難地域の存在と、この拡幅整備の事業の関連といいますか、そういうものはどうなっているのかお伺いしたいと思うのが１点です。広げるべきだと思うのですけれども、区内全域にこれを広げられない理由があるのか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"その対策といたしまして、先ほどご説明いたしましたような木密地域における道路拡幅であるとか、また、防災広場の設置に伴う貯水槽の設置等で消防活動困難区域を少しでもなくしていこうということで、取組みを現在も推進しています。","voiceIndex":149,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"伺います。私が伺ったのは、区内全域に広げられない理由はあるのですかと伺ったので、それがあれば、優先順位の話を聞いているのではないのですけれども、お伺いします。","respondent":"高梨木密整備推進課長","answer":"やはり改善が急がれるところから重点的に優先順位をつけて取り組むことが行政としては必要になってくる、このように考えております。","voiceIndex":151,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"例えば、北品川の二丁目あたりとか、西品川一丁目あたりとかは、局地的にはかなり住宅が密集していたりとかするのですけれども、そういったところは全く除外されているわけなのですけれども、そういったところは、１つ１つ見ればあるのです。それと、道路は、２９号線が延焼遮断ということはここには出ていないのですけれども、それはなぜなのでしょうか。","respondent":"高梨木密整備推進課長","answer":"西品川一丁目等、局地的に木密住宅密集地域があるような地域が入っていないことにつきましては、基本的には区としてもそういうような地域がある、局所的にあるものと考えておりまして、西品川一丁目につきましては、木密地域に連担する地域であるという認識のもと。","voiceIndex":153,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"道路に関しては、２９号線とは書いていないけれども入っているということだと思うのですけれども、道路が防災に役立つというのは、一般質問でもやっていましたけれども、しっかりなぜそうなのかというのは、区としても、それだけ言うわけですからお答えいただきたいのですけれども、一般質問では、道路は防災性があるのですかと質問しても、重層的にやるのだというふうに言いまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"それでも延焼遮断になるのかというのは伺いたいと。それと、何度もこれも指摘していますけれども、実際問題、大震災のときには車両が道路を埋めるのです。この車両火災についても、実際はどう考えているのですか。しっかりお答えいただかないと、防災のための道路と私は言ってほしくないと思うのですけれども、いかがでしょうか。","respondent":"高梨木密整備推進課長","answer":"現在のところ、その先に助成を見据えるのか、それとも地域の中で道路拡幅が必要なのか、防災広場の設置等、そういう公共施設の整備もあわせて行うのかというところについては、そのような基礎調査が行われた後。","voiceIndex":156,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"だから、飛び火というのはあるのに、なぜ延焼遮断になるのですかと伺ったのと、車のことに関しては一切答弁がないのですけれども、それは想定しないで、なぜ延焼遮断になるのですかというお答えがなかった。もう１つ、ついでに言いますと、品川ではほとんど東西の風が吹かないのです。だから、そこに関しても、風向きに関してもどう考えているのですか。お願いします。","respondent":"中村都市計画課長","answer":"ただ、車両についても、これも必ずしも全部燃えるということではないということと、あと、車両が道路を閉塞して埋めつくす割合も必ず１００％になるということではありませんし、かといって、車両が全部埋めつくして火災になるということを前提に延焼遮断帯を諦めたのでは。","voiceIndex":158,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。納得はいきませんけれども。東西の風についてはどうなのでしょうか。ですから、道路には全く意味がないわけではないのだということを繰り返しますけれども、それ以上に道路をつくることで失われるものがある。それは地域コミュニティ力。それに関してマイナスの面についてはどのように考えているのでしょうか。それが２点目です。","respondent":"中村都市計画課長","answer":"今回、この不燃化の取組みについて、所管事務調査ということで説明を申し上げておりますので、道路についてあまり詳しく申し上げるのはちょっとどうかと思いますけれども、ただ、今のご質問にお答えするとすれば、１つは風向きにつきましては、私、先日。","voiceIndex":160,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"コミュニティを維持しながらどうやってという話もありましたけれども、全ての説明を伺っていると、本当に道路をつくることを先にありきみたいな、もともとの道路自体が、防災のための計画ではなかったですから、それが長年、３回、区議会でも反対の請願が出されましたけれども、進まないと、住民も議会も反対して進まないというときに、３・１１が起こって、これを防災だということで位置づけ直して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"その期間を過ぎてもめどが立たないといった場合の見直しはするのでしょうかというところが１点目です。このパンフレットは、もっと有効活用できるのではないかと思うのですが、どういう形でこれを使って皆さんにお知らせをしているのかというところをお聞きしたいと思います。この助成事業、これ、実績はどのような感じなのでしょうかということで、現状を教えてください。","respondent":"高梨木密整備推進課長、持田河川下水道課長","answer":"事業期間を過ぎたらというところなのですが、その各地区、また各事業の進捗具合を見まして、当然、目標達成であるとか、あとはこのまま自然の建替え等で目標が達成する見込みとなれば完了となりますが。防水板の設置につきましては、昭和６２年より実施してございまして、これまで１４８件助成をしている。雨水タンクにつきましては、平成１８年から実施いたしまして、１７３件助成をしているです。","voiceIndex":163,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ここに書く必要はないかもしれないのですけれども、ただ、何か１枚ペラでも、目黒川はもう完了みたいなことも必要だと思うし、戸越・西品川だと、今どこまで進んでいますとか、あとは、完成時期がいついつまでとか、いついつ予定とか、立会川もいついつ予定という形で、そうなってくると、どんどんよくなってくるのだというような実感が沸くと思うので、進行状況もお伝えしていただけると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":63298,"voices":175}},{"id":"h29-20171129-9","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"文教委員会","time":"午前１０時０９分～午後１１時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度入学希望申請の状況","agenda":"平成３０年度入学希望申請の状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回抽せんになった学校と、ならなかった学校は、昨年と変わっていると思うのですけれども、その理由について伺いたいと思います。","respondent":"有馬学務課長","answer":"抽せんとなった学校、ならない学校ですけれども、今回抽せんとなった学校１４校のうち、昨年に引き続き抽せんとなった学校が１２校あります。今年度新規になったところが鈴ヶ森小学校と城南小学校です。こちらにつきましては、住基人口が増えているということが言えると思います。","voiceIndex":24,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"学務課は年に１回の大変な時期を乗り越えてこられて、今回初めて抽せんというのを見せていただいたので、ちょっと感想を述べさせていただきたいと思います。保護者の方々が結構な数、お見えになっておりまして、やはり意識が相当高いのだと思います。今回は小学校のほうですけれども、１４校の中で、兄弟枠すら拾えなかった学校がどこか、また何校あるのかを教えていただきたい。","respondent":"有馬学務課長","answer":"抽せんの結果は今集計中ですので、細かいところまで資料がないのですけれども、１点目の兄弟枠で入れなかった子供は１０校あります。１０校のうち、７校が全員待機ということで６４名です。全体から申しますと、まず兄弟枠で申し込まれた方は１２６名おります。","voiceIndex":29,"id":"exchange-002"},{"speaker":"渡部委員","kind":"意見","question":"ありがとうございました。私たちの会派でも、この辺は人口が増えて大変だなどとずっと言っている中で、学事制度審議会を受けて、このような地域には何らか手を入れていったりする必要があるのかなと思うのですけれども、その辺教育委員会としてお考えになっているところ、いわゆる玉突きみたいになってしまっているところについて、何か見解があれば、一言お願いできますか。","respondent":"有馬学務課長","answer":"学区域を含めた検討ということですけれども、まさに今、委員が言われたとおり、例えば、浜川小学校などでは、場合によっては４クラスということも考えていかなければいけないという逼迫した状況もあります。","voiceIndex":33,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問","question":"ありがとうございました。説明を伺いまして、よくわかりました。でも、それがいいのかどうかというのは、答えはわかりませんけれども、同じ兄弟枠という制度がある中で、そこでも抽せんになってしまうのは、やむを得ないところがあるのですけれども、そのほうがわかりいいかななどという思いがまだ私の中にあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"中学校、特に小中一貫校の関係なのですが、日野学園、伊藤学園、まあ、八潮学園は１桁、希望をしないという数字を見ると、１クラス以上の大きな数字になっています。これは教育委員会としてはどういうふうに評価しているのかを伺いたいと思うのです。正しい見方なのかどうかも含めて、いろいろ見解を伺いたいというのがまず１点です。よろしくお願いします。","respondent":"有馬学務課長","answer":"冒頭にちょっと説明させていただきましたけれども、前期課程のところで、区域外の方が義務教育学校に入りますと、９年間の学びの場を提供するという形になりますので、もう希望申請は出さずに、そのまま７年生に進級するという形になります。","voiceIndex":37,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"この数字の内訳を調べろと言うつもりは全然ないのですけれども、また大分前の希望申請するかしないかを見ているわけではないので、この数字だけ見てどう考えたらいいのかというので、ちょっと質問したいと思っているのです。それなりの数字になっているのではないかと私は思うので、教育委員会として、一貫教育については、この間保護者の方々の評価もあるという見解でずっと来ています。","respondent":"有馬学務課長","answer":"中学校の義務教育学校の申請数の増のところが、小学校と比べて少な目に出ているというところについては、隣の学区域外児童数の(b)欄、そこがもう既に小学校６年生、前期課程の６年生で区域外にいて、この義務教育学校にも在籍している方です。","voiceIndex":39,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"今の答弁は、それはそれとして私は受けとめました。希望申請のマイナスの数字は、この間ずっと経過を追っていった上での質問でないだけに、大変恐縮なのですけれども、もう少しその辺を見ていきたいと思っています。それといろいろな状況があるのではないかというご指摘なのですけれども、そうであるならいいのですけれども、今回の数字はちょっと重たいなと私は受けとめたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"城南小学校も６年生が２クラスなので、３クラスになれば、１クラス必要になる。特に浜川小学校は特別支援学級もたしか３クラスあると聞いているので、教室の状況がかなり苦しいところなので、そのあたりを教育委員会でも学校とよく打ち合わせて、入学される方や、カウンセリングをする部屋などに、どうしてもしわ寄せが行ってしまうので、その辺の環境をぜひ整備していただきたいと思っています。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"基本的に人口推計をしていまして、どうしても教室が必要だという学校が出たときに、どこを教室にしていくかということは内部でも検討を進めています。多目的室や、教室型に近い少人数ルームなど、そういったところを使っています。特別支援教育係で各校の状況を見せていただきながら、特別支援教室の利用者数が増えている学校については、例えば、理科準備室と理科室のところに、パーティションで区切って。","voiceIndex":43,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"最後に１つだけ、少人数学級のところがそこしかなくて、そこに入れかわり立ちかわり生徒が来るとなると、非常に慌ただしいというのもあるので、なかなか難しいところもあると思うのですけれども、それぞれ影響がないように、今お話にあったような形でぜひお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"確認も含めて、他の委員とちょっと重なってしまったらすみません。もう一つが、今定例会の本会議の質問でも、あくつ議員が質問した中で、城南小学校周辺も増えてくる。山中小学校はいきいきという高齢者の方等も教室を共有している部分がありますけれども、今後どうなってしまうのでしょうか。現時点で山中小学校は２クラスで、３クラスにするとなると、教室が確保できるのでしょうか。","respondent":"有馬学務課長、篠田学校計画担当課長","answer":"今ご質問があったとおり、就学人口の増は、今０歳の方の住民登録人数もわかりますので、６年後に入ってくるということから先６年間はまず毎年人口シミュレーションができます。したがいまして、現在もそうなのですけれども、現状ある学校の施設の中で対応し切れないだろうということになってくれば、当然今後学校の改築も視野に入れて、対応を進めていくことは考えながら進めていくです。","voiceIndex":48,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":16429,"voices":59}},{"id":"h29-20171129-5","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"総務委員会","time":"午後１０時１０分～午後 ４時１４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「議案審査」を議題とします。 審査の都合上、初めに(5)第８２号議案 職員の給与に関する条例の一部を改正する条例","agenda":"「議案審査」を議題とします。 審査の都合上、初めに(5)第８２号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"このたび給料改正ということで、条例改正があるわけですが、特に大半の品川区民の暮らしや中小零細企業を抱えている品川区として見れば、やはり給料等を上げるということは控えるべきではないかと思います。特に、品川区議会議員および品川区長は、区民から選ばれた、区民の代表であるわけですから、この方たちは、我々も含めて、逆に下げるべき。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いただいた資料の２の改正内容についてお伺いをします。その下なのですけれども、管理職および係長職の職責の高まり等を考慮して、４級以上の級において引き上げを強め、６級以上の級において、さらに強めた引き上げを行うとありますが、４級が多分、係長職で、６級以上が部長級以上だと思うのですが、この中身がどういうことなのか教えてください。","respondent":"黒田人事課長","answer":"そのほか、例えば若手職員のところも、平均０.４％ということで、若手職員のところも引き上げを強めておりますので、そういった形で、若手の引き上げと職責の高まりを考慮して、全体的に０.１３％に給料改定の引き上げを行ったものです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"初任給のところは、国に準じてということですけれども、初任給というのは、結構、民間のところは最初は高めというところで、やはり開きがあるから、初任給のところも引き上げが行われているという認識で私はいます。ここ３年くらいこんな状況で、ここは区のところで変えられる問題ではないのかもしれませんけれども、平等ではないという思いがあるのですが、その辺のご意見はいかがでしょうか。","respondent":"黒田人事課長","answer":"職責の高まりを考慮しての給料引き上げというのは、行政課題が複雑化する中で、いろいろ係という単位で行政が進行しておりますので、その係の長である係長でありますとか、係長を監督する管理職というところは職責が高まっているという意味では。","voiceIndex":8,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、若干、さっき意見を述べたように、アンバランス、不平等なところがあるので、その辺は改善していただきたいと思っています。全体的には賛成ということで意見を添えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"第８０号議案 品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例および(4)第８１号議案","agenda":"第８０号議案 品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例および(4)第８１号議案","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"改正の趣旨のところに、品川区特別職報酬等審議会の答申どおりということで、先ほど課長から、職員に準じた内容と説明をいただいたのですけれども、私は、一般職の方々と特別職の報酬というのは考え方が違うのではないかと思うのですが、その辺のご意見があったら聞かせてください。","respondent":"米田総務課長","answer":"あわせて、特別区人事委員会の勧告を踏まえた引き上げを行っている区が非常に多いということを踏まえまして、特別職報酬等審議会の委員の方々から、総意といたしまして、特別区人事委員会の今回の引き上げ率、０.１３％と期末手当の引き上げ率について。","voiceIndex":24,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"特別職報酬等審議会においては、総意で職員と同様に引き上げをというご意見だったと思うのですが、私たちは、一般職の方々の状況は、先ほど賛成をいたしましたように、引き上げるべきであると思っています。しかし、区議会議員をはじめ区長等は区民によって選挙で選ばれた方が中心なのですけれども、やはり区民の生活実態をしっかり見据えた検討が必要ではないかと思っています。意見だけで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"先ほどもお話ししましたが、特別職、品川区議会議員、区長は、私も同様に思うのですが、選挙で選ばれて、区民、中小零細企業、その他さまざまありますが、そういう方たちの生活を支えるというのが第一の職務だと考えています。私は、そういうことを思えば、区議会議員とか区長は逆に下げるべきだと思います。これに対しては、特に反対しておきます。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"以前の総務委員会でも同じような質問をさせていただいたのですが、議員報酬と区長の報酬というのは、別々にそれぞれ決まって、何で期末手当が区長や副区長に連動してしまうつくりになっているのか質問したところ、歴史的な経過というご答弁をいただいて、私、うかつにもそのまま受けとめてしまったのですけれども、その歴史的経過というものの中身を教えていただけると判断がしやすいと思うのですが。","respondent":"米田総務課長","answer":"条例のつくりとしては、明記するということも１つでありますし、このような形で準用するというやり方もできると思いますが、歴史的経過ということについては、区議会議員であったり区長であったりということにつきましては、任期が限られている中で。","voiceIndex":28,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"ただ、額をどう考えるかというのは大変難しくて、この額がほかの民間のどの事業と比べたら妥当なのかというところは、正直なところ、本当になかなか判断はできないと思っています。ですから、特別職でも、上げるのは、その職務の重責に対してどうこうということで言えば、それはぜひ、しかるべきときにはきちんとした額をとって、そのかわり、きちんと重責を果たしていただくという考え方が妥当と思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"議員が監査委員でこの中に入っていますが、法改正があって、もう議員でなくていいとなったわけですから、これも改善して、一般の人がやるべきではないかと私は思います。教育長の給料だけになっているのですが、もし違っていたら申し訳ありませんが、教育委員も、今お話ししたとおり、同様に日当制という形で持っていくべきではないかと私は考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、今回は、今の制度にのっとった報酬の議論ということで理解して、賛否を言わせていただきたいと思います。ネットとしては、置かなくていいとか、そういう議論の前に、ぜひ、きちんと監査をしていただいて、その監査を受けたところできちんと活かすということを優先して、報酬のことはまた、その制度とは切り離して考えるべきではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"先ほど申しましたとおり、区長、副区長に関しては、給与および旅費ということに関しては賛成なのですけれども、これに賛成してしまうと、議員の期末手当も一緒に上がってしまうということで、そうしますと、主張の趣旨と整合性がとれないので、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-012"}]},{"id":"topic-03","title":"の２、「報告事項」を聴取いたします。 まず、(1)長期基本計画の検証状況","agenda":"の２、「報告事項」を聴取いたします。 まず、(1)長期基本計画の検証状況","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"Ａ４のところから質問しますけれども、まず１つは、検討委員会の作業部会は非公開になっています。そういった意味で、委員会ではもちろんご報告いただけると思うのですが、どうしたら中身がわかるのかというのが１点です。(3)のその他のところに区内団体等へのインタビュー実施とありますが、これの中身、どのような団体に対して、どのくらいの規模でやられるのか、そこのところを教えてください。","respondent":"柏原企画調整課長","answer":"この検討状況の内容です。基本的には、内部の検討ですので、公開というような趣旨にはないと思ってありますが、議会に対してということでは、今回はこういう形で資料をお示しさせていただきました。","voiceIndex":76,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今回、来街者の方のアンケートをとられたということで、興味深く見させていただいたのですが、ＷＥＢモニターがよくわからないので、選択の仕方とか、どうやって選ばれて、意見を集められたのか、その辺を教えてください。","respondent":"柏原企画調整課長","answer":"今回、こういった形で初めての試みで行ったのですが、来街者の方からどうやってご意見を伺うかというのは、なかなか難しいところがありまして、いろいろな手法を考えていたところですが、民間の調査会社にモニターとして。","voiceIndex":78,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういったご説明だったのですけれども、この自己評価のところを、前のアンケートのところも踏まえて、意見を幾つか述べさせていただきたいと思います。作業部会とか、現場の中で話し合うのは重要ですけれども、折に触れて、やはりこのアンケート結果を深めていくような住民との接点も、パブコメを最後にとるだけではなくて、ぜひ入れていただきたいと思うのですが、この点はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"今回はお示しできていませんけれども、数値で達成できたとかできていないとか、そういったところもかなり深く分析して、出していこうというところもありますので、そういった数値とか、そういうのも含めて進めていきたいと、場合によっては。","voiceIndex":80,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前にも、４次の総合実施計画の中で数値なども具体的にしていきたいとおっしゃっていたので、ぜひ、その辺は具体的に区民の願いが、どこがかなっていて、どこが遅れて進んでいないのかというあたりもわかりやすく検証していただいて、充実していっていただきたいと思います。その点はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"どちらも必要なことだと思いますので、そういった個別の分野もそうですけれども、区全体としていかに効果的、効率的にうまく動かしていくのか。それから、職員がきちんとノウハウだったり、そういったものを継承できるかというのは、両方あわせながら検討すべきと思います。","voiceIndex":82,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"それで、このアンケートの集計についてなのですけれども、せっかく属性について幾つかアンケートがあるのですが、それとほかの回答についてのクロス集計みたいなのがされたのかどうかということも伺いたいと思いますので、それだけ教えてください。","respondent":"柏原企画調整課長","answer":"今、生データというものに分析をさらにかけて、どういう形にまとめるかというのは、これから作業部会に入っていきますので、そういったものをどういうふうに練り上げて、ご報告する際も、どういった形でお見せできるかというのは、今後検討したいと考えています。","voiceIndex":84,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれ所管のところは把握していらっしゃるということですけれども、ぜひ、検討にあたっては、もう少し達成状況、それぞれ把握していらっしゃるところから、意見とかを出し合って、内容は深めていくのだと思うのですけれども、もう少し詳しい内容のもとに、それぞれのほかの所管のことも把握しながら議論をしていただきたいと思います。どうここから読み取るか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、ここまできちんとそろえられたのですが、先ほど課長がおっしゃったとおり、さまざまな属性の方が意見を言うわけで、そうすると、年齢とか暮らしている環境、家族構成、職業、そういうもので、みんなさまざまな意見をぶつけてくるわけですから、それをどうやってまとめるのか。ちょっと大変なのかと。そうすると、ここで矛盾というのが必ず出てきてしまう。意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば、「重視してほしい施策」の中で、生涯学習・スポーツ活動の質問で、その下の答えで、「生涯スポーツ施設の整備」が１位になっているではないですか。その点、例えば１０年前と今回の調査で、同じような位置に答えをきちんと載せているのか。若干、ニュアンスが違う部分があると思ったのですけれども、その辺がどのようになっていたのか教えてほしい。委託されているのかどうかも含めて教えてください。","respondent":"柏原企画調整課長","answer":"先ほどもお話がありましたけれども、検討委員会でも同様なお話が出ておりまして、やはりどういう形でクロス集計をやるのかは大切なところですので、それはぜひ、積極的にやっていきたいと思っています。それから、アンケートのつくり等々です。","voiceIndex":88,"id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ、これだけの情報があるので、活かしていただきたいと思いますが、これだけではなくて、ほかにも区で、さまざまなアンケートで、いろいろなときに、いろいろな手法でとられていると思うのです。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"非常に興味深く拝見をしました。関心があるところで具体的に聞いてしまいますけれども、そういう項目、子どもの経済的な支援はそもそもないところで、今回のアンケート結果から、そこを見直すということをここでおっしゃっているのかについて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今後検討を進めていく中では、今、副委員長がおっしゃったような内容は検討の１つの大きな論点、視点になってくるだろうと思ってあります。","voiceIndex":91,"id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"俎上にのるということを確認させていただきました。もう一点だけ。そのようなことで、これをもう一回、確認をさせていただきたいのですが、この長期基本計画に関してです。ご答弁を最後にいただきたいと思います。","respondent":"柏原企画調整課長","answer":"先般の本会議でもご答弁申し上げた内容のままですけれども、考え方といたしましては、長期基本計画、これは品川区の行政計画ですので、区が主体となった考え方で進めるというのが、まず第一なのだろうと思います。","voiceIndex":93,"id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"長期基本計画の検証ということで、さまざまなアンケート結果、さまざまな取組み、これからやっていかなければいけないところだと思うのですけれども、４ページ、問１０のところで、「まちづくりに関する取り組みの中で重視すべき取り組みはどれですか」というところなのですけれども、やはり１０年前と同じように、歩きやすい道路環境づくりというのが１位になっています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-024"}]},{"id":"topic-04","title":"地方公会計制度に基づく財務４表","agenda":"地方公会計制度に基づく財務４表","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"もう一つは、品川区は、今までずっとバランスシートとか行政コスト計算書も区民に向けて公表しています。パンフレットというのが、これまではカラーのものだったかと思うのですが、その辺がどういうふうに変わるのか。その移行期というのでしょうか。どういうふうに変わっていくのか、ご説明いただけると助かります。","respondent":"秋山財政課長","answer":"それがあります。今回の公表については、総務省改訂モデルでやっているのを出していきますので、そこの公会計について検討していますということは載せますけれども、具体的にどうなるかは、そこまではできていません。","voiceIndex":102,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"そして下のほうに、「平成２７年１月に『統一的な基準による地方公会計の整備促進』を要請されました」ということで、この間、議会で新公会計制度の説明を受けたとき、公認会計士の方のいろいろな説明の中では、東京都のモデルという感じで、多分、東京都方式で説明があったかと思うのですが、ごちゃごちゃになっているので、東京都モデルとか総務省のモデルとか幾つもある中で、今回。","respondent":"秋山財政課長","answer":"東京都方式と総務省方式は、並行してもいいということになっていますけれども、東京都方式をとっている団体も、機械的に総務省方式のほうに財務４表は変換できますので、そういう形で総務省には報告する形になっています。","voiceIndex":104,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"別に面倒くさくはないのか、後で比較とか対照をしたとき。それが１点。もう一回、お答えいただきたい。もし、そうやって１つのものに連結されていって、予算、決算のときに出されるということは、予算、決算の特別委員会の折に、ここの部分もしっかりと議会の中でチェック、議論ができることになるということなのかどうか、そこのところを教えてください。","respondent":"秋山財政課長","answer":"それと、最初の面倒かどうかという話なのですが、なぜ東京都方式なのかという部分では、考え方の違いというのがありまして、税収を収益と見るのか、それとも受益者負担として見るのかみたいなところがありまして、国との検討の中でも、それは１つにまとめることはできない。","voiceIndex":106,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"連結財務４表については、議会の議決を得るところではないので、予算、決算のところで議論する中身ではないけれども、具体的にどういうところで取り上げられる、議論ができるのですか。質問したいとか、疑問があるというときに、どういうところでその中身の議論をさせてくれるのかどうかというところはどうでしょうか。","respondent":"秋山財政課長","answer":"今でも、品川区国際友好協会であるとか品川区文化振興事業団につきましては、報告として、各団体の事業報告と決算報告等が出ておりますので、その中でご議論いただくことになっております。","voiceIndex":108,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なところからお聞きしたいのですけれども、去年の１月から個人番号カードが希望者には交付をされているわけですけれども、通知カードが相変わらず届いていなくて、行方がはっきりしていなくて、届いていない人がいらっしゃるのかどうか。個人番号のカードの交付が何％ぐらい進んでいるのか、基本的なところを教えていただきたい。そこのところを教えてください。","respondent":"仁平情報推進課長","answer":"基本方針に挙げております各事務の照会方法なのですけれども、こちらの照会にあたりましては、マイナンバーカードを使うという仕組みではございませんで、国と各地方公共団体がつくった情報提供ネットワークシステムという専用のシステムがあるのですが。","voiceIndex":115,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"一番最初の通知カードが届いていない人というのは、残っているところで何％いるのかというのを１つ、先ほどの続きで伺いたい。個人番号カードの発行率が人口比で１３％と、大変厳しい数字だと思うのですが、今後、この辺はどうしていくのか伺いたいと思います。共産党としては、この間、マイナンバーカードに対しては、１つには大事なプライバシーの人権が侵害される危険が大きくあるということ。","respondent":"仁平情報推進課長","answer":"カードの利活用につきましては、特に区が考えているのは、その中のＩＣ機能を使ったサービス提供が考えられるのではないかということで、引き続き検討していくと、そういうことにしているものです。","voiceIndex":117,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ＩＣ機能を使う部分では、今後いろいろ便利なところは広げていくということだったのでしょうか。そういった意味で、１３％にとどまっている個人番号カードを請求される方を増やしていくようなことをこれからやられるのでしょうか。持ちたくありません。個人情報の漏えいなども大丈夫だというお話も伺いました。私どもは広めてほしくない、廃止してほしいという思いが非常に強いのです。いかがでしょうか。","respondent":"仁平情報推進課長","answer":"２点目のカードの活用の仕方ですけれども、ＩＣカードとしての機能を使ってのサービス展開を考えているところでございまして、カードの番号そのものを使っての利用の仕方というのは、番号法とか条例で、もう使える分野は決めておりますので。","voiceIndex":119,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際にカードを１３％の方が持っておられるということについては、個人情報の漏えいがされない、漏れないように、本当にしっかりと今の段階ではやっていただきたいと考えていますけれども、とにかくコンビニ交付とか、便利だといって使えば使うほど、個人の情報が連結されて、広まっていくというのが事実なので、共産党としては、何としてでも国の段階で廃止をしてほしいと期待をしているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"質問としては、よく理解ができないのですけれども、資料の１７ページの６番の品川区における特定個人情報保護評価対応についてという中身が私はよく理解できないので、教えていただきたいと思います。今、現に評価をしていて、これらの手順を踏まえ、評価書を国へ提出し、公表もしていますということなのですが、この評価がどう行われているのか。その辺を教えてください。","respondent":"中元広報広聴課長、仁平情報推進課長","answer":"評価書といたしましては、こちらは１８ページからありますが、その中の該当する事務の一つ一つにつきまして、全項目評価と基礎項目評価と、それぞれ項目ごとに全部、評価書をつくらせていただきまして。項番の１、２につきましては、今、広報広聴課長の説明があったとおりでございまして、以下、重点、基礎とありまして、これは扱うデータの規模によって、重点と基礎という評価書の分かれ方になります。","voiceIndex":122,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"ホームページ、私、こういうのが苦手で、検索もとても下手なのですけれども、検索していけば、ここの情報に当たって、私たちも、みんな見ることができるということですか。今、ここで説明するのは、すごく大変なことでしょうか。もし、すごい大変だったら、後で個人的に伺いますけれども、もし、ざっと説明していただければ、伺いたいのですが。","respondent":"仁平情報推進課長","answer":"方針（案）の３０ページの下の囲みの中に、今の特定個人情報保護評価の評価の内容とか実施等を説明しています。","voiceIndex":125,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"詳しくは、やはりまた改めて個別に伺いたいと思いますが、ネットとしても、個人情報がどれくらい広がる可能性があるのか、今、きちんと保護されているかどうかということと、このシステムを広げていくことによって、新たな個人情報のような使われ方をするのではないかという危険性のところで反対をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-035"}]},{"id":"topic-05","title":"防災行政無線設備更新工事請負契約","agenda":"防災行政無線設備更新工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この防災行政無線設備更新工事というのは、今年の初めのプレス発表のところに載っているデジタル化と関係があるのでしょうか。デジタル化の問題と、親局の設置と屋外拡声子局のところが１０箇所ということなのですけれども、親局は区庁舎の中だと思うのですが、デジタル化というのがどういうものなのか。１０箇所というのは、今、区内に幾つあって、この１０箇所がどういう位置付けにあるのか。","respondent":"立川経理課長","answer":"少しだけ説明します。今の通信方式はアナログということで、それで、今回の工事からデジタル化を進めるというところまでは聞いてあります。全体、親局につきましては、現在も第二庁舎にあります。それを新しくする。","voiceIndex":132,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"プレス発表のところがあまり詳しくは書いていないのです。実際に、平成３３年までに順次、かえていって、老朽化はもちろんあると思うのですが、具体的にどこがどう改善されるのか。聞こえない部分とか、区内でよく届かないという声がたびたび出ている。そういうところの改善も今回の中に含まれているのかどうかを教えてください。","respondent":"立川経理課長","answer":"中身につきましては、所管で。","voiceIndex":134,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、やはり内容を伝えていただきたいし、資料は多分、今日の委員会の資料だから間に合わないかもしれないですが、必要な工事だとはわかっていますが、この金額が妥当かどうか判断する大もとの問題だと思うのです。だから、そこはご理解いただいて、ご努力をしていただきたい。これはお願いにしておきます。具体的な中身を聞きますけれども、いつものように、辞退の理由を教えてください。","respondent":"立川経理課長","answer":"今回、７業者ございまして、２者は積算額が予定価格を超えたものです。もう２者が配置技術者の調整がつかなかったです。もう１者が自社都合によるです。","voiceIndex":136,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"結局、７者がトライをしたけれども、２者の入札金額で低いほうが選ばれたということなのですけれども、この工事自体が難しい工事なのか、新しいことを取り入れた工事なのか、大体、ここに挙がっているような企業だったらやっていける中身なのか、そういう部分はいかがでしょうか。","respondent":"立川経理課長","answer":"この工事につきましては、対象業種としまして、電話通信、そういった専門性のある事業者に限るということで報告を受けておりまして、東京都全体と品川区で工事をする意思のある、そういった登録のある事業者が自主的に、とりあえず申し込みを行ったというのがこの７者です。","voiceIndex":138,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"そういったところで、１回目の入札の金額の違いがあるのですけれども、低いほうが落札をされたわけですけれども、工事の内容的にはきちんとチェックがされていると思うのですが、そういうのは、一つ一つ、積算の項目の比較をするのでしょうか。","respondent":"立川経理課長","answer":"入札の報告をする時点で、格付であるとか、防災行政無線の官公庁での導入実績とか、その辺をまず基準としまして、申し込めるか申し込めないかというのは決まってきますので、既に申し込みを行った事業者については、防災行政無線の設置については問題ない。","voiceIndex":140,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、今までの工事のいろいろな状況とか入札の状況とかが、それで大丈夫だろうと、そういった判断が１つあるということは、そうすると、新しい事業者が参入するときは、すごい不利になるのでしょうか。そこだけ、最後に教えて下さい。","respondent":"立川経理課長","answer":"それで、なおかつ、今回、具体的に申し上げますと、過去１０年間で官公庁の発注の類似工事の実績が予定価格の５０％以上あるということになりますので、そういったことで、品質の確保等を進めるですので、当然、実績のない事業者については参入ができないです。","voiceIndex":142,"id":"exchange-041"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。建設委員会の資料によると、平成２９年から平成３４年の期間で、親局をはじめとして、多分、４０３基ぐらいかえるのです。それで、今回のこの契約は、あくまで親局と残りの１０局との契約です。例えばスピーカー等の更新と書いてあるのですけれども、基本的には平成３４年までにやる残りの工事も同じ内容になるのか、それとも、年度によって、契約の内容によって変わってしまうのか。","respondent":"立川経理課長","answer":"防災課から聞いたのですけれども、どういったシステムを入れるかというのは、事前にプロポーザル方式で選定するですので、今後導入する機械につきましても、今回導入するシステムと同一のものということで聞いています。","voiceIndex":144,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、少なくても、こういう更新工事、入札になりましたという話ぐらいはしてほしいと思うのです。それは所管が違う、所管が違うで、別に金額だけなら、ここで金額の話をする、入札がこうなりましたという話はわかるのですが、でも、最低限、こういうふうに性能がよくなる、こういうふうに順次変わっていきますぐらいは、やはりきちんと話していただきたいと思います。","respondent":"立川経理課長、伊藤委員長","answer":"どこまで深く話せるかというのはありますが、基本的なことにつきましては、ご報告申し上げたと考えております。所管のことをおっしゃいますけれども、これは委員会が独立していますから、私どもが建設委員会のそこまで入り込んで質疑することはできないと考えていますので、それはご理解していただきたいと思います。","voiceIndex":146,"id":"exchange-043"},{"speaker":"須貝委員","kind":"質問・要望","question":"何も突っ込もうというのではなくて、こういう内容で、こうなりましたということぐらいは話していいのではないかと思うのです。やはりそういう話や情報は提供していただきたいという意見だけであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-044"},{"speaker":"あくつ副委員長","kind":"確認","question":"その上で質問するのですけれども、それは当然だと思うので、この場で全部というのは難しい話ですから、見れば、必要な情報がわかるわけですから、所管が違うと思ったら、それは所管の課長に聞いて委員会に臨むのが我々の仕事だと思っています。それで、今回は１０本立てる。アナログのものをとってしまうということなのです。わかれば、そこだけ確認させてください。","respondent":"立川経理課長","answer":"そこについては、所管に確認します。","voiceIndex":150,"id":"exchange-045"}]},{"id":"topic-06","title":"住民税（普通徴収）・軽自動車税のクレジットカード等による収納開始","agenda":"住民税（普通徴収）・軽自動車税のクレジットカード等による収納開始","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"都議選のときがひどかったのです。今回、１８歳の選挙権で、１８歳の方たちの投票率が若い方たちの中では高くなっているという意味では、いろいろ工夫次第で投票率は上がるのだという希望が持てると思っているのです。この数字を出していただいてありがたいのですが、これを活用して、いい方向に持っていっていただきたいのですけれども、今、考えていらっしゃることが何かあったら、お聞かせください。","respondent":"安井選挙管理委員会事務局長","answer":"１８歳のほうの啓発は、メッセージカード等をやっていますけれども、１９歳のほうも何らかの対応を考えていかなければいけないと思っています。","voiceIndex":164,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2096#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":58628,"voices":166}},{"id":"h29-20171129-10","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"意見","question":"１点、各委員会で、皆さん質疑等で発言をされていると思いますが、これは発言を制限するつもりはないのですけれども、委員会運営上、一定の発言をする際はまとめて内容を発言していただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"今の発言の趣旨がよくわからなかったので、具体的に例えばどんなケースが、実際にあったのだったら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば１つの議題に対して各議員が質問をされますね。そのときに、例えば行ってこいで何回も同じようなことを繰り返し質問して答弁が、例えば理事者から先ほどと同じ答弁になってしまいますがみたいなことが、何回も繰り返されるような発言はぜひ考えていただきたいなということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5256#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1493,"voices":12}}]);
